function pickVenueMetadataFields(metadata, allowedKeys) {
    const source = normalizeVenueMetadataObject(metadata);

    return allowedKeys.reduce((result, key) => {
        if (Object.prototype.hasOwnProperty.call(source, key)) {
            result[key] = source[key];
        }

        return result;
    }, {});
}

function mergeVenueReviewMetadata(currentMetadata, proposedMetadata) {
    const baseMetadata = normalizeVenueMetadataObject(currentMetadata);
    const reviewMetadata = pickVenueMetadataFields(proposedMetadata, VENUE_REVIEW_METADATA_KEYS);

    return {
        ...baseMetadata,
        ...reviewMetadata
    };
}

function extractVenueOwnerCandidateIds(venue) {
    if (!venue || typeof venue !== 'object') {
        return [];
    }

    return [...new Set(
        [venue.submitted_by_user_id, venue.owner_user_id]
            .map((value) => String(value || '').trim())
            .filter(Boolean)
    )];
}

async function resolveVenueOwnerUserIdByVenueId(venueId) {
    const normalizedVenueId = Number(venueId);

    if (!Number.isFinite(normalizedVenueId) || normalizedVenueId <= 0) {
        return '';
    }

    const venueHasOwnerUserColumn = await hasVenueOwnerUserColumn();
    const ownerSelect = venueHasOwnerUserColumn
        ? `${buildResolvedVenueOwnerUserSql('venues')} AS owner_user_id,`
        : 'NULL::uuid AS owner_user_id,';

    const result = await pool.query(
        `
            SELECT
                ${ownerSelect}
                venues.submitted_by_user_id
            FROM venues
            WHERE venues.id = $1
            LIMIT 1
        `,
        [normalizedVenueId]
    );

    if (!result.rows.length) {
        return '';
    }

    return extractVenueOwnerCandidateIds(result.rows[0])[0] || '';
}

async function resolveNotificationActorName(userId, fallback = 'Người dùng') {
    const normalizedUserId = String(userId || '').trim();

    if (!normalizedUserId) {
        return fallback;
    }

    try {
        const result = await pool.query(
            `
                SELECT fullname, username, email
                FROM users
                WHERE id::text = $1
                LIMIT 1
            `,
            [normalizedUserId]
        );

        return String(
            result.rows[0]?.fullname
            || result.rows[0]?.username
            || result.rows[0]?.email
            || fallback
        ).trim() || fallback;
    } catch {
        return fallback;
    }
}

function parsePositiveIntegerList(input) {
    if (input === undefined || input === null || input === '') {
        return { values: [], invalid: false };
    }

    const rawItems = Array.isArray(input)
        ? input.flatMap((value) => String(value).split(','))
        : String(input).split(',');

    const values = [];

    for (const item of rawItems) {
        const trimmed = String(item).trim();

        if (!trimmed) {
            continue;
        }

        const parsed = Number(trimmed);

        if (!Number.isInteger(parsed) || parsed <= 0) {
            return { values: [], invalid: true };
        }

        values.push(parsed);
    }

    return { values: [...new Set(values)], invalid: false };
}

function parseTextList(input) {
    if (input === undefined || input === null || input === '') {
        return [];
    }

    const rawItems = Array.isArray(input)
        ? input.flatMap((value) => String(value).split(','))
        : String(input).split(',');

    return [...new Set(rawItems.map((value) => String(value).trim()).filter(Boolean))];
}

function normalizeNullableNumber(value) {
    if (value === undefined || value === null || value === '') {
        return null;
    }

    const parsed = Number(value);
    if (!Number.isInteger(parsed) || parsed <= 0) {
        return Number.NaN;
    }

    return parsed;
}

function normalizeNullableText(value) {
    if (value === undefined || value === null) {
        return null;
    }

    const trimmed = String(value).trim();
    return trimmed === '' ? null : trimmed;
}

