function normalizeVenueMetadataObject(metadata) {
    if (metadata && typeof metadata === 'object' && !Array.isArray(metadata)) {
        return metadata;
    }

    if (typeof metadata === 'string') {
        try {
            const parsed = JSON.parse(metadata);
            if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
                return parsed;
            }
        } catch (_error) {
            return {};
        }
    }

    return {};
}

function normalizeKeywordStringArray(value) {
    if (!Array.isArray(value)) {
        return [];
    }

    const extracted = value.flatMap((item) => {
        if (typeof item === 'string' || typeof item === 'number') {
            return [item];
        }

        if (item && typeof item === 'object') {
            const candidates = [
                item.name,
                item.label,
                item.title,
                item.value,
                item.text,
                item.serviceName,
                item.service_name,
                item.keyword,
                item.tag,
                item.slug
            ];

            return candidates.filter((candidate) => typeof candidate === 'string' || typeof candidate === 'number');
        }

        return [];
    });

    return [...new Set(
        extracted
            .map((item) => String(item || '').trim())
            .filter(Boolean)
    )];
}

function normalizeStringArray(value) {
    if (!Array.isArray(value)) {
        return [];
    }

    const extracted = value.flatMap((item) => {
        if (typeof item === 'string') {
            return [item];
        }

        if (item && typeof item === 'object') {
            const candidates = [
                item.url,
                item.image_url,
                item.imageUrl,
                item.src,
                item.path,
                item.file_url,
                item.fileUrl
            ];

            return candidates.filter((candidate) => typeof candidate === 'string');
        }

        return [];
    });

    return extracted
        .map((item) => String(item || '').trim())
        .map((item) => item.replace(/^['"]|['"]$/g, '').replace(/\\/g, '/'))
        .map((item) => item.replace(/^\/?api\/v\d+\/uploads\//i, '/uploads/'))
        .map((item) => item.replace(/^\/?api\/uploads\//i, '/uploads/'))
        .map((item) => item.replace(/^(https?:\/\/[^/]+)\/api\/v\d+\/uploads\//i, '$1/uploads/'))
        .map((item) => item.replace(/^(https?:\/\/[^/]+)\/api\/uploads\//i, '$1/uploads/'))
        .filter((item) => {
            const normalized = String(item || '').trim().toLowerCase();
            const hasValidImagePath =
                /^https?:\/\//i.test(normalized)
                || normalized.startsWith('/uploads/')
                || normalized.startsWith('uploads/')
                || normalized.startsWith('data:image/');

            return Boolean(normalized)
                && hasValidImagePath
                && !['nan', 'null', 'undefined'].includes(normalized)
                && !normalized.startsWith('blob:');
        });
}

function normalizeVenueImageKey(value) {
    const normalized = String(value || '')
        .trim()
        .replace(/^['"]|['"]$/g, '')
        .replace(/\\/g, '/')
        .replace(/^\/?api\/v\d+\/uploads\//i, '/uploads/')
        .replace(/^\/?api\/uploads\//i, '/uploads/')
        .replace(/^(https?:\/\/[^/]+)\/api\/v\d+\/uploads\//i, '$1/uploads/')
        .replace(/^(https?:\/\/[^/]+)\/api\/uploads\//i, '$1/uploads/');

    if (!normalized) {
        return '';
    }

    if (/^https?:\/\//i.test(normalized)) {
        try {
            const parsed = new URL(normalized);
            const pathname = parsed.pathname
                .replace(/^\/api\/v\d+\/uploads\//i, '/uploads/')
                .replace(/^\/api\/uploads\//i, '/uploads/');
            return `${pathname}${parsed.search || ''}`;
        } catch (_error) {
            return normalized;
        }
    }

    return normalized;
}

function resolveVenueMetadataImageCandidates(metadata) {
    return [
        ...normalizeStringArray(metadata.galleryImages),
        ...normalizeStringArray(metadata.images),
        ...normalizeStringArray(metadata.imageUrls),
        ...normalizeStringArray(metadata.photos),
        ...normalizeStringArray(metadata.photoUrls),
        ...normalizeStringArray(metadata.mapImages),
        ...normalizeStringArray(metadata.mapImageUrls),
        ...normalizeStringArray(metadata.map_images),
        ...normalizeStringArray(metadata.map_image_urls),
        ...normalizeStringArray([metadata.mapImage]),
        ...normalizeStringArray([metadata.map_image])
    ];
}

function mergeUniqueVenueImages(candidates = []) {
    const imageByKey = new Map();

    candidates.forEach((item) => {
        const normalizedValue = String(item || '').trim();
        if (!normalizedValue) {
            return;
        }

        const imageKey = normalizeVenueImageKey(normalizedValue);
        if (!imageKey || imageByKey.has(imageKey)) {
            return;
        }

        imageByKey.set(imageKey, normalizedValue);
    });

    return [...imageByKey.values()];
}

function extractVenueImageUrls(venue, externalImages = []) {
    const metadata = normalizeVenueMetadataObject(venue?.metadata);
    const mergedCandidates = [
        ...normalizeStringArray([venue?.venue_primary_image_url, venue?.map_image_url]),
        ...normalizeStringArray(externalImages),
        ...resolveVenueMetadataImageCandidates(metadata),
        ...normalizeStringArray(venue?.venue_images)
    ];

    const coverImageUrl = String(venue?.cover_image_url || '').trim();
    if (coverImageUrl) {
        mergedCandidates.push(coverImageUrl);
    }

    return mergeUniqueVenueImages(mergedCandidates);
}

function resolveNumericCoordinate(value) {
    const normalizedValue = typeof value === 'string'
        ? value.trim().replace(',', '.')
        : value;
    const numeric = Number(normalizedValue);
    return Number.isFinite(numeric) ? numeric : null;
}

function normalizeVenueCoordinates(venue) {
    const metadata = normalizeVenueMetadataObject(venue?.metadata);
    const metadataLocation = metadata?.location && typeof metadata.location === 'object' ? metadata.location : {};

    const latitudeCandidates = [
        venue?.latitude,
        metadata.latitude,
        metadata.lat,
        metadataLocation.latitude,
        metadataLocation.lat
    ];
    const longitudeCandidates = [
        venue?.longitude,
        metadata.longitude,
        metadata.lng,
        metadata.lon,
        metadataLocation.longitude,
        metadataLocation.lng,
        metadataLocation.lon
    ];

    let latitude = latitudeCandidates
        .map((candidate) => resolveNumericCoordinate(candidate))
        .find((candidate) => candidate !== null);
    let longitude = longitudeCandidates
        .map((candidate) => resolveNumericCoordinate(candidate))
        .find((candidate) => candidate !== null);

    const latitudeInRange = Number.isFinite(latitude) && latitude >= -90 && latitude <= 90;
    const longitudeInRange = Number.isFinite(longitude) && longitude >= -180 && longitude <= 180;
    const swappedLatitudeInRange = Number.isFinite(longitude) && longitude >= -90 && longitude <= 90;
    const swappedLongitudeInRange = Number.isFinite(latitude) && latitude >= -180 && latitude <= 180;

    if ((!latitudeInRange || !longitudeInRange) && swappedLatitudeInRange && swappedLongitudeInRange) {
        const originalLatitude = latitude;
        latitude = longitude;
        longitude = originalLatitude;
    }

    if (!Number.isFinite(latitude) || latitude < -90 || latitude > 90) {
        latitude = null;
    }

    if (!Number.isFinite(longitude) || longitude < -180 || longitude > 180) {
        longitude = null;
    }

    return {
        ...venue,
        latitude,
        longitude
    };
}

async function loadVenueGalleryImageUrls(venueId) {
    if (!Number.isFinite(Number(venueId))) {
        return [];
    }

    try {
        const galleryResult = await pool.query(
            `
                SELECT image_url
                FROM venue_images
                WHERE venue_id = $1
                ORDER BY display_order ASC, id ASC
            `,
            [venueId]
        );

        return normalizeStringArray(galleryResult.rows.map((row) => row.image_url));
    } catch (error) {
        if (error?.code === '42P01') {
            return [];
        }

        throw error;
    }
}

function getZonedNowSnapshot(now = new Date(), timeZone = VENUE_OPENING_TIMEZONE) {
    const formatter = new Intl.DateTimeFormat('en-US', {
        timeZone,
        weekday: 'long',
        hour: '2-digit',
        minute: '2-digit',
        hour12: false
    });

    const parts = formatter.formatToParts(now);
    const valueByType = new Map(parts.map((part) => [part.type, part.value]));
    const weekdayRaw = String(valueByType.get('weekday') || '').toLowerCase();
    const hour = Number(valueByType.get('hour'));
    const minute = Number(valueByType.get('minute'));
    const todayKeyByWeekday = {
        monday: 'monday',
        tuesday: 'tuesday',
        wednesday: 'wednesday',
        thursday: 'thursday',
        friday: 'friday',
        saturday: 'saturday',
        sunday: 'sunday'
    };

    return {
        nowMinutes: (Number.isFinite(hour) ? hour : 0) * 60 + (Number.isFinite(minute) ? minute : 0),
        todayKey: todayKeyByWeekday[weekdayRaw] || 'monday'
    };
}

function normalizeWeeklyScheduleInput(scheduleInput, options = {}) {
    const fallbackStart = String(options.fallbackStart || '').trim();
    const fallbackEnd = String(options.fallbackEnd || '').trim();
    const hasFallbackRange = /^\d{2}:\d{2}$/.test(fallbackStart) && /^\d{2}:\d{2}$/.test(fallbackEnd) && fallbackStart < fallbackEnd;
    const source = scheduleInput && typeof scheduleInput === 'object' && !Array.isArray(scheduleInput) ? scheduleInput : null;

    if (!source && !hasFallbackRange) {
        return {
            value: null,
            error: 'weeklySchedule is required and must include all 7 days'
        };
    }

    const normalized = {};

    for (const day of WEEKLY_SCHEDULE_DAYS) {
        const dayValue = source?.[day.key] || null;
        const startRaw = String(dayValue?.start ?? '').trim();
        const endRaw = String(dayValue?.end ?? '').trim();
        const isOff = Boolean(dayValue?.off) || startRaw.toUpperCase() === 'OFF' || endRaw.toUpperCase() === 'OFF';

        if (isOff) {
            normalized[day.key] = {
                day: day.label,
                start: 'OFF',
                end: 'OFF',
                off: true
            };
            continue;
        }

        const start = startRaw || (hasFallbackRange ? fallbackStart : '');
        const end = endRaw || (hasFallbackRange ? fallbackEnd : '');

        if (!start || !end) {
            return {
                value: null,
                error: `${day.label} must include both start and end time, or use OFF`
            };
        }

        if (!/^\d{2}:\d{2}$/.test(start) || !/^\d{2}:\d{2}$/.test(end)) {
            return {
                value: null,
                error: `${day.label} has invalid time format`
            };
        }

        if (start >= end) {
            return {
                value: null,
                error: `${day.label} end time must be later than start time`
            };
        }

        normalized[day.key] = {
            day: day.label,
            start,
            end,
            off: false
        };
    }

    return {
        value: normalized,
        error: null
    };
}

function mapWeeklyOpenHoursToWeeklySchedule(source) {
    if (!source || typeof source !== 'object' || Array.isArray(source)) {
        return null;
    }

    return WEEKLY_SCHEDULE_DAYS.reduce((accumulator, day) => {
        const dayValue = source?.[day.key] || {};
        const start = String(dayValue?.openTime ?? '').trim();
        const end = String(dayValue?.closeTime ?? '').trim();
        const off = Boolean(dayValue?.isClosed) || start.toUpperCase() === 'OFF' || end.toUpperCase() === 'OFF';

        accumulator[day.key] = {
            day: day.label,
            start: off ? 'OFF' : start,
            end: off ? 'OFF' : end,
            off
        };

        return accumulator;
    }, {});
}

function resolveWeeklyScheduleSource(normalizedMetadata, incomingMetadata = null) {
    const mergedMetadata =
        normalizedMetadata && typeof normalizedMetadata === 'object' && !Array.isArray(normalizedMetadata)
            ? normalizedMetadata
            : {};
    const incomingSource =
        incomingMetadata && typeof incomingMetadata === 'object' && !Array.isArray(incomingMetadata)
            ? incomingMetadata
            : null;

    const incomingCanonicalSource =
        incomingSource &&
        incomingSource.weeklySchedule &&
        typeof incomingSource.weeklySchedule === 'object' &&
        !Array.isArray(incomingSource.weeklySchedule)
            ? incomingSource.weeklySchedule
            : null;

    if (incomingCanonicalSource) {
        return incomingCanonicalSource;
    }

    const incomingLegacySource =
        incomingSource &&
        incomingSource.weeklyOpenHours &&
        typeof incomingSource.weeklyOpenHours === 'object' &&
        !Array.isArray(incomingSource.weeklyOpenHours)
            ? mapWeeklyOpenHoursToWeeklySchedule(incomingSource.weeklyOpenHours)
            : null;

    if (incomingLegacySource) {
        return incomingLegacySource;
    }

    const canonicalSource =
        mergedMetadata.weeklySchedule &&
        typeof mergedMetadata.weeklySchedule === 'object' &&
        !Array.isArray(mergedMetadata.weeklySchedule)
            ? mergedMetadata.weeklySchedule
            : null;

    if (canonicalSource) {
        return canonicalSource;
    }

    return mergedMetadata.weeklyOpenHours &&
        typeof mergedMetadata.weeklyOpenHours === 'object' &&
        !Array.isArray(mergedMetadata.weeklyOpenHours)
        ? mapWeeklyOpenHoursToWeeklySchedule(mergedMetadata.weeklyOpenHours)
        : null;
}

function toMinutesFromHHmm(value) {
    const normalized = String(value || '').trim();

    if (!/^\d{2}:\d{2}$/.test(normalized)) {
        return null;
    }

    const [hourText, minuteText] = normalized.split(':');
    const hour = Number(hourText);
    const minute = Number(minuteText);

    if (!Number.isInteger(hour) || !Number.isInteger(minute)) {
        return null;
    }

    if (hour < 0 || hour > 23 || minute < 0 || minute > 59) {
        return null;
    }

    return hour * 60 + minute;
}

function extractVenueWeeklySchedule(metadata) {
    const normalizedMetadata = normalizeVenueMetadataObject(metadata);
    const source = resolveWeeklyScheduleSource(normalizedMetadata);

    const fallbackStart = String(normalizedMetadata.startTime || '').trim();
    const fallbackEnd = String(normalizedMetadata.endTime || '').trim();
    const hasFallbackRange =
        /^\d{2}:\d{2}$/.test(fallbackStart) && /^\d{2}:\d{2}$/.test(fallbackEnd) && fallbackStart < fallbackEnd;

    if (!source && !hasFallbackRange) {
        return [];
    }

    return WEEKLY_SCHEDULE_DAYS.map((day) => {
        const daySchedule = source?.[day.key] || {};
        const start = String(daySchedule.start || '').trim() || (hasFallbackRange ? fallbackStart : '');
        const end = String(daySchedule.end || '').trim() || (hasFallbackRange ? fallbackEnd : '');
        const off = Boolean(daySchedule.off) || start === 'OFF' || end === 'OFF';

        return {
            key: day.key,
            label: day.label,
            open: off ? 'OFF' : start || 'N/A',
            close: off ? 'OFF' : end || 'N/A',
            off
        };
    });
}

function buildVenueRealtimeOpeningPayload(metadata, now = new Date()) {
    const weeklySchedule = extractVenueWeeklySchedule(metadata);

    if (!weeklySchedule.length) {
        return {
            timezone: VENUE_OPENING_TIMEZONE,
            serverTime: now.toISOString(),
            current: {
                dayKey: null,
                dayLabel: null,
                isOpen: false,
                start: 'N/A',
                end: 'N/A'
            },
            weeklySchedule: []
        };
    }

    const zonedNow = getZonedNowSnapshot(now, VENUE_OPENING_TIMEZONE);
    const todayKey = zonedNow.todayKey;
    const nowMinutes = zonedNow.nowMinutes;

    const weeklyScheduleWithFlags = weeklySchedule.map((item) => ({
        ...item,
        isToday: item.key === todayKey
    }));

    const todaySchedule = weeklyScheduleWithFlags.find((item) => item.key === todayKey) || weeklyScheduleWithFlags[0];
    const startMinutes = toMinutesFromHHmm(todaySchedule.open);
    const endMinutes = toMinutesFromHHmm(todaySchedule.close);
    const isOpenNow =
        !todaySchedule.off &&
        startMinutes !== null &&
        endMinutes !== null &&
        nowMinutes >= startMinutes &&
        nowMinutes < endMinutes;

    return {
        timezone: VENUE_OPENING_TIMEZONE,
        serverTime: now.toISOString(),
        current: {
            dayKey: todaySchedule.key,
            dayLabel: todaySchedule.label,
            isOpen: isOpenNow,
            start: todaySchedule.open,
            end: todaySchedule.close
        },
        weeklySchedule: weeklyScheduleWithFlags
    };
}

function slugifyText(value) {
    return String(value || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/(^-|-$)/g, '');
}

function sanitizeTextField(value) {
    if (value === undefined || value === null) {
        return null;
    }

    const text = String(value);
    if (text.toLowerCase() === 'nan') {
        return null;
    }

    return text;
}

function isValidEmail(value) {
    if (value === undefined || value === null) {
        return false;
    }

    const normalized = String(value).trim();
    if (!normalized) {
        return false;
    }

    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalized);
}

function escapeHtml(value) {
    return String(value || '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

function formatMultilineHtml(value) {
    return escapeHtml(value).replace(/\n/g, '<br />');
}

function normalizeFeedbackStatusLabel(value) {
    const map = {
        new: 'New',
        in_progress: 'In Progress',
        replied: 'Replied',
        closed: 'Closed'
    };

    return map[String(value || '').toLowerCase()] || 'Replied';
}

function formatFeedbackTimestamp(value) {
    if (!value) {
        return 'N/A';
    }

    const date = new Date(value);
    if (Number.isNaN(date.getTime())) {
        return 'N/A';
    }

    return date.toLocaleString('en-US', {
        dateStyle: 'medium',
        timeStyle: 'short'
    });
}

function normalizeFeedbackStatusList(statusInput) {
    if (!statusInput) {
        return [];
    }

    const allowedStatuses = new Set(['new', 'in_progress', 'replied', 'closed']);

    return String(statusInput)
        .split(',')
        .map((value) => value.trim().toLowerCase())
        .filter((value) => allowedStatuses.has(value));
}

function normalizePaginationValue(value, fallback, { min = 1, max = 100 } = {}) {
    const parsed = Number(value);

    if (!Number.isInteger(parsed)) {
        return fallback;
    }

    return Math.min(Math.max(parsed, min), max);
}

function normalizeBooleanQueryValue(value, fallback = false) {
    if (value === undefined || value === null || value === '') {
        return fallback;
    }

    const normalized = String(value).trim().toLowerCase();

    if (['1', 'true', 'yes', 'on'].includes(normalized)) {
        return true;
    }

    if (['0', 'false', 'no', 'off'].includes(normalized)) {
        return false;
    }

    return fallback;
}

function shouldUseDatabaseSsl() {
    const sslValue = String(process.env.DB_SSL || process.env.PGSSLMODE || '').trim().toLowerCase();

    if (['false', '0', 'disable', 'off', 'no'].includes(sslValue)) {
        return false;
    }

    if (['true', '1', 'require', 'on', 'yes'].includes(sslValue)) {
        return true;
    }

    // Default to no SSL for local/self-hosted development to avoid connection failures.
    return false;
}

function buildDatabasePoolConfig() {
    const connectionString = String(process.env.DATABASE_URL || '').trim();
    const config = connectionString
        ? {
              connectionString
          }
        : {
              host: process.env.DB_HOST || '127.0.0.1',
              port: Number(process.env.DB_PORT) || 5432,
              user: process.env.DB_USER || 'postgres',
              password: String(process.env.DB_PASSWORD ?? ''),
              database: process.env.DB_NAME || 'postgres'
          };

    if (shouldUseDatabaseSsl()) {
        config.ssl = {
            rejectUnauthorized: false
        };
    }

    return config;
}

function resolveUploadPathFromUrl(fileUrl) {
    if (!fileUrl || typeof fileUrl !== 'string') {
        return null;
    }

    const normalizedUrl = fileUrl.replace(/\\/g, '/');
    if (!normalizedUrl.startsWith('/uploads/')) {
        return null;
    }

    const relativePath = normalizedUrl.replace('/uploads/', '');
    const uploadsRoot = path.resolve(path.join(__dirname, 'uploads'));
    const targetPath = path.resolve(path.join(uploadsRoot, relativePath));

    if (!targetPath.startsWith(uploadsRoot)) {
        return null;
    }

    return targetPath;
}

function safeDeleteUploadedFile(fileUrl) {
    const targetPath = resolveUploadPathFromUrl(fileUrl);

    if (!targetPath || !fs.existsSync(targetPath)) {
        return;
    }

    try {
        fs.unlinkSync(targetPath);
    } catch (error) {
        console.warn(`Unable to delete uploaded file ${targetPath}:`, error.message);
    }
}

async function generateWardIdFromName(name) {
                const fallbackSeed = Date.now().toString().slice(-6);
                const baseSlug = slugifyText(name).slice(0, 42) || `ward-${fallbackSeed}`;
                let candidate = baseSlug;
                let suffix = 1;

                // Keep deriving a suffix until the ward id is unique.
                while (true) {
                    const exists = await pool.query(
                        `
                SELECT 1
                FROM wards
                WHERE ward_id = $1
                LIMIT 1
            `,
                        [candidate]
                    );

                    if (!exists.rows.length) {
                        return candidate;
                    }

                    candidate = `${baseSlug.slice(0, 40)}-${suffix}`;
                    suffix += 1;
                }
            }

            function extractBoundaryFeatures(boundary) {
                if (!boundary || typeof boundary !== 'object') {
                    return [];
                }

                if (boundary.type === 'FeatureCollection' && Array.isArray(boundary.features)) {
                    return boundary.features;
                }

                if (boundary.type === 'Feature') {
                    return [boundary];
                }

                return [];
            }

            function validateBoundaryGeoJson(boundary) {
                const features = extractBoundaryFeatures(boundary);

                if (!features.length) {
                    return false;
                }

                return features.some((feature) => {
                    const geometryType = feature?.geometry?.type;
                    return geometryType === 'Polygon' || geometryType === 'MultiPolygon';
                });
            }

            function canonicalizeJsonValue(value) {
                if (Array.isArray(value)) {
                    return value.map((item) => canonicalizeJsonValue(item));
                }

                if (value && typeof value === 'object') {
                    return Object.keys(value)
                        .sort()
                        .reduce((result, key) => {
                            result[key] = canonicalizeJsonValue(value[key]);
                            return result;
                        }, {});
                }

                return value;
            }

            function areJsonValuesEqual(firstValue, secondValue) {
                return JSON.stringify(canonicalizeJsonValue(firstValue)) === JSON.stringify(canonicalizeJsonValue(secondValue));
            }

            function normalizeCoordinateValue(value) {
                if (typeof value !== 'number' || !Number.isFinite(value)) {
                    return value;
                }

                return Number(value.toFixed(6));
            }

            function normalizeGeometryCoordinates(coordinates) {
                if (!Array.isArray(coordinates)) {
                    return normalizeCoordinateValue(coordinates);
                }

                return coordinates.map((item) => normalizeGeometryCoordinates(item));
            }

            function buildBoundaryGeometrySignature(boundary) {
                const features = extractBoundaryFeatures(boundary);

                const geometrySignatures = features
                    .map((feature) => feature?.geometry)
                    .filter((geometry) => geometry && ['Polygon', 'MultiPolygon'].includes(geometry.type))
                    .map((geometry) =>
                        JSON.stringify(
                            canonicalizeJsonValue({
                                type: geometry.type,
                                coordinates: normalizeGeometryCoordinates(geometry.coordinates)
                            })
                        )
                    )
                    .sort();

                if (!geometrySignatures.length) {
                    return '';
                }

                return JSON.stringify(geometrySignatures);
            }

            function haveSameBoundaryGeometry(firstBoundary, secondBoundary) {
                const firstSignature = buildBoundaryGeometrySignature(firstBoundary);
                const secondSignature = buildBoundaryGeometrySignature(secondBoundary);

                return Boolean(firstSignature) && firstSignature === secondSignature;
            }

            const wardBoundaryCache = {
                loadedAt: 0,
                rows: null
            };
            const WARD_BOUNDARY_CACHE_TTL_MS = 2 * 60 * 1000;

            async function getWardBoundaryRows() {
                const now = Date.now();
                if (Array.isArray(wardBoundaryCache.rows) && now - wardBoundaryCache.loadedAt < WARD_BOUNDARY_CACHE_TTL_MS) {
                    return wardBoundaryCache.rows;
                }

                const wardsResult = await pool.query('SELECT ward_id, name, boundary FROM wards');
                wardBoundaryCache.rows = Array.isArray(wardsResult.rows) ? wardsResult.rows : [];
                wardBoundaryCache.loadedAt = now;
                return wardBoundaryCache.rows;
            }

            async function detectWardByCoordinates(latitude, longitude) {
                const point = turf.point([longitude, latitude]);
                const wardRows = await getWardBoundaryRows();

                let detectedWardId = null;
                let detectedWardName = 'Not detected (Outside boundary)';

                for (const ward of wardRows) {
                    const features = extractBoundaryFeatures(ward.boundary);

                    for (const feature of features) {
                        const geometryType = feature?.geometry?.type;

                        if (geometryType !== 'Polygon' && geometryType !== 'MultiPolygon') {
                            continue;
                        }

                        if (turf.booleanPointInPolygon(point, feature)) {
                            detectedWardId = ward.ward_id;
                            detectedWardName = ward.name;
                            break;
                        }
                    }

                    if (detectedWardId) {
                        break;
                    }
                }

                return {
                    wardId: detectedWardId,
                    wardName: detectedWardName
                };
            }

