        async function getVenueServices(req, res) {
            const venueId = Number(req.params.venueId);

            if (!Number.isFinite(venueId)) {
                return res.status(400).json({ message: 'Invalid venue id' });
            }

            try {
                const isAdmin = normalizeRole(req.authUser?.role) === 'admin';
                const venue = await getPublicVenueForDetail(venueId, isAdmin);

                if (!venue) {
                    return res.status(404).json({ message: 'Venue not found' });
                }

                const metadata = normalizeVenueMetadataObject(venue.metadata);
                const selectedServiceIds = normalizeServiceIds(metadata.selectedServices);

                if (!selectedServiceIds.length) {
                    return res.json({
                        venueId,
                        services: []
                    });
                }

                const servicesQuery = `
                    SELECT id, name, slug, icon, description
                    FROM merchant_services
                    WHERE is_active = true
                      AND id = ANY($1::int[])
                    ORDER BY array_position($1::int[], id), sort_order ASC, name ASC
                `;

                const { rows: venueServices } = await pool.query(servicesQuery, [selectedServiceIds]);

                return res.json({
                    venueId,
                    services: venueServices
                });
            } catch (error) {
                return res.status(500).json({ message: error.message });
            }
        }

        function submitVenueReview(req, res) {
            uploadVenueReview.array('images', 6)(req, res, async (uploadErr) => {
                if (uploadErr) {
                    return res.status(400).json({ message: uploadErr.message || 'Upload failed' });
                }

                const uploadedFiles = Array.isArray(req.files) ? req.files : [];
                const cleanupUploadedFiles = () => {
                    uploadedFiles.forEach((file) => {
                        if (file?.filename) {
                            safeDeleteUploadedFile(`/uploads/reviews/${file.filename}`);
                        }
                    });
                };

                const venueId = Number(req.params.venueId);
                const rawRating = String(req.body.rating || '').trim();
                const title = String(req.body.title || '').trim();
                const comment = String(req.body.comment || '').trim();
                const userId = String(req.user?.id || '').trim();
                let rating = null;

                if (!userId) {
                    cleanupUploadedFiles();
                    return res.status(401).json({ message: 'Bạn cần đăng nhập để bình luận.' });
                }

                if (!Number.isFinite(venueId)) {
                    cleanupUploadedFiles();
                    return res.status(400).json({ message: 'Invalid venue id' });
                }

                if (rawRating) {
                    const parsedRating = Number(rawRating);
                    if (
                        !Number.isFinite(parsedRating)
                        || parsedRating < 0.5
                        || parsedRating > 5
                        || !Number.isInteger(parsedRating * 2)
                    ) {
                        cleanupUploadedFiles();
                        return res.status(400).json({ message: 'rating must be from 0.5 to 5 with step 0.5' });
                    }

                    rating = parsedRating;
                }

                if (!comment) {
                    cleanupUploadedFiles();
                    return res.status(400).json({ message: 'comment is required' });
                }

                if (findBlockedReviewTerm(`${title} ${comment}`)) {
                    cleanupUploadedFiles();
                    return res.status(400).json({ message: 'Nội dung bình luận chứa từ ngữ không phù hợp.' });
                }

                try {
                    const venueResult = await pool.query(
                        `
                            SELECT id, status::text AS status
                            FROM venues
                            WHERE id = $1
                            LIMIT 1
                        `,
                        [venueId]
                    );

                    if (!venueResult.rows.length) {
                        cleanupUploadedFiles();
                        return res.status(404).json({ message: 'Venue not found' });
                    }

                    if (String(venueResult.rows[0].status || '').toLowerCase() !== 'approved') {
                        cleanupUploadedFiles();
                        return res.status(404).json({ message: 'Venue not found' });
                    }

                    const userResult = await pool.query(
                        `
                            SELECT id, fullname, username
                            FROM users
                            WHERE id::text = $1
                            LIMIT 1
                        `,
                        [userId]
                    );

                    const authorName =
                        userResult.rows[0]?.fullname || userResult.rows[0]?.username || req.authUser?.email || 'Người dùng';
                    const imageUrls = uploadedFiles.map((file) => `/uploads/reviews/${file.filename}`);

                    const insertResult = await pool.query(
                        `
                            INSERT INTO venue_public_reviews (
                                venue_id,
                                user_id,
                                author_name,
                                title,
                                comment,
                                rating,
                                image_urls,
                                updated_at
                            )
                            VALUES ($1, $2, $3, $4, $5, $6, $7::jsonb, NOW())
                            RETURNING id, venue_id, user_id, author_name, title, comment, rating, image_urls, created_at, updated_at
                        `,
                        [venueId, userId, authorName, title || null, comment, rating, JSON.stringify(imageUrls)]
                    );

                    const statsResult = await pool.query(
                        `
                            SELECT
                                COALESCE(AVG(rating)::numeric(10,2), 0) AS average_rating,
                                COUNT(*)::int AS total_reviews
                            FROM venue_public_reviews
                            WHERE venue_id = $1
                        `,
                        [venueId]
                    );

                    const created = insertResult.rows[0];
                    const venueOwnerUserId = await resolveVenueOwnerUserIdByVenueId(venueId);

                    if (venueOwnerUserId && venueOwnerUserId !== userId) {
                        await createUserNotification({
                            userId: venueOwnerUserId,
                            type: 'venue_review',
                            title: 'Bài đăng của bạn có bình luận mới',
                            content: `${authorName} đã bình luận về bài đăng của bạn.`,
                            metadata: {
                                venueId,
                                reviewId: Number(created.id),
                                actorUserId: userId
                            }
                        });
                    }

                    invalidateVenueCommunityBundleCacheByVenueId(venueId);

                    return res.status(201).json({
                        message: 'Review submitted successfully',
                        review: {
                            id: created.id,
                            venueId: created.venue_id,
                            userId: created.user_id,
                            authorName: created.author_name,
                            title: created.title || '',
                            comment: created.comment,
                            rating: created.rating === null ? null : Number(created.rating || 0),
                            imageUrls: Array.isArray(created.image_urls) ? created.image_urls : [],
                            createdAt: created.created_at,
                            updatedAt: created.updated_at,
                            canDelete: true
                        },
                        stats: {
                            averageRating: Number(statsResult.rows[0]?.average_rating || 0),
                            totalReviews: Number(statsResult.rows[0]?.total_reviews || 0)
                        }
                    });
                } catch (error) {
                    cleanupUploadedFiles();
                    return res.status(500).json({ message: error.message });
                }
            });
        }

        async function toggleVenueReviewLike(req, res) {
            const venueId = normalizeNullableNumber(req.params.venueId);
            const reviewId = normalizeNullableNumber(req.params.reviewId);
            const userId = String(req.user?.id || '').trim();

            if (Number.isNaN(venueId) || venueId === null || Number.isNaN(reviewId) || reviewId === null) {
                return res.status(400).json({ message: 'venueId/reviewId không hợp lệ.' });
            }

            if (!userId) {
                return res.status(401).json({ message: 'Bạn cần đăng nhập để thích bình luận.' });
            }

            try {
                const reviewResult = await pool.query(
                    `
                        SELECT id
                        FROM venue_public_reviews
                        WHERE id = $1 AND venue_id = $2
                        LIMIT 1
                    `,
                    [reviewId, venueId]
                );

                if (!reviewResult.rows.length) {
                    return res.status(404).json({ message: 'Không tìm thấy bình luận.' });
                }

                const existingLike = await pool.query(
                    `
                        SELECT 1
                        FROM venue_review_likes
                        WHERE review_id = $1 AND user_id = $2
                        LIMIT 1
                    `,
                    [reviewId, userId]
                );

                let liked = false;

                if (existingLike.rows.length) {
                    await pool.query(
                        `
                            DELETE FROM venue_review_likes
                            WHERE review_id = $1 AND user_id = $2
                        `,
                        [reviewId, userId]
                    );
                } else {
                    await pool.query(
                        `
                            INSERT INTO venue_review_likes (review_id, user_id)
                            VALUES ($1, $2)
                            ON CONFLICT (review_id, user_id) DO NOTHING
                        `,
                        [reviewId, userId]
                    );
                    liked = true;
                }

                const countResult = await pool.query(
                    `
                        SELECT COUNT(*)::int AS like_count
                        FROM venue_review_likes
                        WHERE review_id = $1
                    `,
                    [reviewId]
                );

                invalidateVenueCommunityBundleCacheByVenueId(venueId);

                return res.json({
                    success: true,
                    reviewId,
                    liked,
                    likeCount: Number(countResult.rows[0]?.like_count || 0)
                });
            } catch (error) {
                return res.status(500).json({ message: error.message });
            }
        }

        function createVenueReviewReply(req, res) {
            uploadVenueReview.array('images', 3)(req, res, async (uploadErr) => {
                if (uploadErr) {
                    return res.status(400).json({ message: uploadErr.message || 'Upload failed' });
                }

                const uploadedFiles = Array.isArray(req.files) ? req.files : [];
                const cleanupUploadedFiles = () => {
                    uploadedFiles.forEach((file) => {
                        if (file?.filename) {
                            safeDeleteUploadedFile(`/uploads/reviews/${file.filename}`);
                        }
                    });
                };

                const venueId = normalizeNullableNumber(req.params.venueId);
                const reviewId = normalizeNullableNumber(req.params.reviewId);
                const userId = String(req.user?.id || '').trim();
                const content = String(req.body?.content || '').trim();
                const title = String(req.body?.title || '').trim();
                const rawRating = String(req.body?.rating || '').trim();
                let rating = null;

                if (Number.isNaN(venueId) || venueId === null || Number.isNaN(reviewId) || reviewId === null) {
                    cleanupUploadedFiles();
                    return res.status(400).json({ message: 'venueId/reviewId không hợp lệ.' });
                }

                if (!userId) {
                    cleanupUploadedFiles();
                    return res.status(401).json({ message: 'Bạn cần đăng nhập để thảo luận.' });
                }

                if (!content) {
                    cleanupUploadedFiles();
                    return res.status(400).json({ message: 'Nội dung thảo luận không được để trống.' });
                }

                if (rawRating) {
                    const parsedRating = Number(rawRating);
                    if (
                        !Number.isFinite(parsedRating)
                        || parsedRating < 0.5
                        || parsedRating > 5
                        || !Number.isInteger(parsedRating * 2)
                    ) {
                        cleanupUploadedFiles();
                        return res.status(400).json({ message: 'Số sao phải từ 0.5 đến 5 và cách nhau 0.5.' });
                    }

                    rating = parsedRating;
                }

                if (findBlockedReviewTerm(`${title} ${content}`)) {
                    cleanupUploadedFiles();
                    return res.status(400).json({ message: 'Nội dung thảo luận chứa từ ngữ không phù hợp.' });
                }

                try {
                    const reviewResult = await pool.query(
                        `
                            SELECT id, user_id
                            FROM venue_public_reviews
                            WHERE id = $1 AND venue_id = $2
                            LIMIT 1
                        `,
                        [reviewId, venueId]
                    );

                    if (!reviewResult.rows.length) {
                        cleanupUploadedFiles();
                        return res.status(404).json({ message: 'Không tìm thấy bình luận.' });
                    }

                    const userResult = await pool.query(
                        `
                            SELECT fullname, username
                            FROM users
                            WHERE id::text = $1
                            LIMIT 1
                        `,
                        [userId]
                    );

                    const authorName = userResult.rows[0]?.fullname || userResult.rows[0]?.username || req.authUser?.email || 'Người dùng';
                    const imageUrls = uploadedFiles.map((file) => `/uploads/reviews/${file.filename}`);

                    const insertResult = await pool.query(
                        `
                            INSERT INTO venue_review_replies (review_id, user_id, author_name, rating, title, content, image_urls, updated_at)
                            VALUES ($1, $2, $3, $4, $5, $6, $7::jsonb, NOW())
                            RETURNING id, review_id, user_id, author_name, rating, title, content, image_urls, created_at, updated_at
                        `,
                        [reviewId, userId, authorName, rating, title || null, content, JSON.stringify(imageUrls)]
                    );

                    const countResult = await pool.query(
                        `
                            SELECT COUNT(*)::int AS reply_count
                            FROM venue_review_replies
                            WHERE review_id = $1
                        `,
                        [reviewId]
                    );

                    const created = insertResult.rows[0];
                    const reviewOwnerUserId = String(reviewResult.rows[0]?.user_id || '').trim();

                    if (reviewOwnerUserId && reviewOwnerUserId !== userId) {
                        await createUserNotification({
                            userId: reviewOwnerUserId,
                            type: 'venue_reply',
                            title: 'Bình luận của bạn có phản hồi mới',
                            content: `${authorName} đã phản hồi bình luận của bạn.`,
                            metadata: {
                                venueId,
                                reviewId,
                                replyId: Number(created.id),
                                actorUserId: userId
                            }
                        });
                    }

                    invalidateVenueCommunityBundleCacheByVenueId(venueId);

                    return res.status(201).json({
                        success: true,
                        reply: {
                            id: created.id,
                            reviewId: created.review_id,
                            userId: created.user_id,
                            authorName: created.author_name,
                            rating: Number(created.rating || 0),
                            title: created.title || '',
                            content: created.content,
                            imageUrls: Array.isArray(created.image_urls) ? created.image_urls : [],
                            likeCount: 0,
                            likedByMe: false,
                            createdAt: created.created_at,
                            updatedAt: created.updated_at,
                            canDelete: true
                        },
                        replyCount: Number(countResult.rows[0]?.reply_count || 0)
                    });
                } catch (error) {
                    cleanupUploadedFiles();
                    return res.status(500).json({ message: error.message });
                }
            });
        }

        async function toggleVenueReviewReplyLike(req, res) {
            const venueId = normalizeNullableNumber(req.params.venueId);
            const reviewId = normalizeNullableNumber(req.params.reviewId);
            const replyId = normalizeNullableNumber(req.params.replyId);
            const userId = String(req.user?.id || '').trim();

            if (
                Number.isNaN(venueId) || venueId === null
                || Number.isNaN(reviewId) || reviewId === null
                || Number.isNaN(replyId) || replyId === null
            ) {
                return res.status(400).json({ message: 'venueId/reviewId/replyId không hợp lệ.' });
            }

            if (!userId) {
                return res.status(401).json({ message: 'Bạn cần đăng nhập để thích bình luận.' });
            }

            try {
                const replyResult = await pool.query(
                    `
                        SELECT replies.id
                        FROM venue_review_replies AS replies
                        INNER JOIN venue_public_reviews AS reviews ON reviews.id = replies.review_id
                        WHERE replies.id = $1
                          AND replies.review_id = $2
                          AND reviews.venue_id = $3
                        LIMIT 1
                    `,
                    [replyId, reviewId, venueId]
                );

                if (!replyResult.rows.length) {
                    return res.status(404).json({ message: 'Không tìm thấy bình luận nhỏ.' });
                }

                const existingLike = await pool.query(
                    `
                        SELECT 1
                        FROM venue_review_reply_likes
                        WHERE reply_id = $1 AND user_id = $2
                        LIMIT 1
                    `,
                    [replyId, userId]
                );

                let liked = false;

                if (existingLike.rows.length) {
                    await pool.query(
                        `
                            DELETE FROM venue_review_reply_likes
                            WHERE reply_id = $1 AND user_id = $2
                        `,
                        [replyId, userId]
                    );
                } else {
                    await pool.query(
                        `
                            INSERT INTO venue_review_reply_likes (reply_id, user_id)
                            VALUES ($1, $2)
                            ON CONFLICT (reply_id, user_id) DO NOTHING
                        `,
                        [replyId, userId]
                    );
                    liked = true;
                }

                const countResult = await pool.query(
                    `
                        SELECT COUNT(*)::int AS like_count
                        FROM venue_review_reply_likes
                        WHERE reply_id = $1
                    `,
                    [replyId]
                );

                invalidateVenueCommunityBundleCacheByVenueId(venueId);

                return res.json({
                    success: true,
                    reviewId,
                    replyId,
                    liked,
                    likeCount: Number(countResult.rows[0]?.like_count || 0)
                });
            } catch (error) {
                return res.status(500).json({ message: error.message });
            }
        }

        async function deleteVenueReview(req, res) {
            const venueId = normalizeNullableNumber(req.params.venueId);
            const reviewId = normalizeNullableNumber(req.params.reviewId);
            const userId = String(req.user?.id || '').trim();
            const isAdmin = normalizeRole(req.authUser?.role) === 'admin';

            if (Number.isNaN(venueId) || venueId === null || Number.isNaN(reviewId) || reviewId === null) {
                return res.status(400).json({ message: 'venueId/reviewId không hợp lệ.' });
            }

            if (!userId) {
                return res.status(401).json({ message: 'Bạn cần đăng nhập để xóa bình luận.' });
            }

            try {
                const reviewResult = await pool.query(
                    `
                        SELECT id, user_id
                        FROM venue_public_reviews
                        WHERE id = $1 AND venue_id = $2
                        LIMIT 1
                    `,
                    [reviewId, venueId]
                );

                if (!reviewResult.rows.length) {
                    return res.status(404).json({ message: 'Không tìm thấy bình luận.' });
                }

                const ownerId = String(reviewResult.rows[0].user_id || '').trim();

                if (!ownerId || (ownerId !== userId && !isAdmin)) {
                    return res.status(403).json({ message: 'Bạn không có quyền xóa bình luận này.' });
                }

                await pool.query(
                    `
                        DELETE FROM venue_public_reviews
                        WHERE id = $1 AND venue_id = $2
                    `,
                    [reviewId, venueId]
                );

                invalidateVenueCommunityBundleCacheByVenueId(venueId);

                return res.json({ success: true, deletedReviewId: reviewId });
            } catch (error) {
                return res.status(500).json({ message: error.message });
            }
        }

