        function updateVenueReview(req, res) {
            uploadVenueReview.array('images', 6)(req, res, async (uploadErr) => {
                if (uploadErr) {
                    return res.status(400).json({ message: uploadErr.message || 'Upload failed' });
                }

                const uploadedFiles = Array.isArray(req.files) ? req.files : [];
                const cleanupUploadedFiles = () => {
                    uploadedFiles.forEach((file) => {
                        if (file?.filename) {
                            safeDeleteUploadedFile(`/uploads/reviews/${file.filename}`);
                        }
                    });
                };

                const venueId = normalizeNullableNumber(req.params.venueId);
                const reviewId = normalizeNullableNumber(req.params.reviewId);
                const userId = String(req.user?.id || '').trim();
                const rawRating = String(req.body.rating || '').trim();
                const title = String(req.body.title || '').trim();
                const comment = String(req.body.comment || '').trim();
                const hasCommentField = Object.prototype.hasOwnProperty.call(req.body || {}, 'comment');
                const removeExistingMedia = String(req.body.removeExistingMedia || '').trim().toLowerCase() === 'true';

                if (Number.isNaN(venueId) || venueId === null || Number.isNaN(reviewId) || reviewId === null) {
                    cleanupUploadedFiles();
                    return res.status(400).json({ message: 'venueId/reviewId không hợp lệ.' });
                }

                if (!userId) {
                    cleanupUploadedFiles();
                    return res.status(401).json({ message: 'Bạn cần đăng nhập để chỉnh sửa bình luận.' });
                }

                let rating = null;
                if (rawRating) {
                    const parsedRating = Number(rawRating);
                    if (
                        !Number.isFinite(parsedRating)
                        || parsedRating < 0.5
                        || parsedRating > 5
                        || !Number.isInteger(parsedRating * 2)
                    ) {
                        cleanupUploadedFiles();
                        return res.status(400).json({ message: 'rating must be from 0.5 to 5 with step 0.5' });
                    }

                    rating = parsedRating;
                }

                try {
                    const reviewResult = await pool.query(
                        `
                            SELECT id, user_id, comment, title, rating, image_urls
                            FROM venue_public_reviews
                            WHERE id = $1 AND venue_id = $2
                            LIMIT 1
                        `,
                        [reviewId, venueId]
                    );

                    if (!reviewResult.rows.length) {
                        cleanupUploadedFiles();
                        return res.status(404).json({ message: 'Không tìm thấy bình luận.' });
                    }

                    const currentReview = reviewResult.rows[0];
                    const ownerId = String(currentReview.user_id || '').trim();
                    if (!ownerId || ownerId !== userId) {
                        cleanupUploadedFiles();
                        return res.status(403).json({ message: 'Bạn chỉ có thể chỉnh sửa bình luận của chính mình.' });
                    }

                    const nextComment = hasCommentField ? comment : String(currentReview.comment || '');
                    if (!String(nextComment || '').trim()) {
                        cleanupUploadedFiles();
                        return res.status(400).json({ message: 'comment is required' });
                    }

                    const nextTitle = Object.prototype.hasOwnProperty.call(req.body || {}, 'title')
                        ? title
                        : String(currentReview.title || '');
                    const nextRating = rawRating ? rating : currentReview.rating;

                    if (findBlockedReviewTerm(`${nextTitle} ${nextComment}`)) {
                        cleanupUploadedFiles();
                        return res.status(400).json({ message: 'Nội dung bình luận chứa từ ngữ không phù hợp.' });
                    }

                    const existingMedia = Array.isArray(currentReview.image_urls) ? currentReview.image_urls : [];
                    const uploadedMedia = uploadedFiles.map((file) => `/uploads/reviews/${file.filename}`);
                    const shouldReplaceMedia = uploadedMedia.length > 0 || removeExistingMedia;
                    const nextMedia = shouldReplaceMedia ? uploadedMedia : existingMedia;

                    const updateResult = await pool.query(
                        `
                            UPDATE venue_public_reviews
                            SET
                                title = $3,
                                comment = $4,
                                rating = $5,
                                image_urls = $6::jsonb,
                                updated_at = NOW()
                            WHERE id = $1 AND venue_id = $2
                            RETURNING id, venue_id, user_id, author_name, title, comment, rating, image_urls, created_at, updated_at
                        `,
                        [reviewId, venueId, nextTitle || null, nextComment, nextRating, JSON.stringify(nextMedia)]
                    );

                    if (shouldReplaceMedia) {
                        existingMedia.forEach((mediaUrl) => {
                            if (!nextMedia.includes(mediaUrl)) {
                                safeDeleteUploadedFile(mediaUrl);
                            }
                        });
                    }

                    const statsResult = await pool.query(
                        `
                            SELECT
                                COALESCE(AVG(rating)::numeric(10,2), 0) AS average_rating,
                                COUNT(*)::int AS total_reviews
                            FROM venue_public_reviews
                            WHERE venue_id = $1
                        `,
                        [venueId]
                    );

                    const updated = updateResult.rows[0];
                    invalidateVenueCommunityBundleCacheByVenueId(venueId);

                    return res.json({
                        message: 'Review updated successfully',
                        review: {
                            id: updated.id,
                            venueId: updated.venue_id,
                            userId: updated.user_id,
                            authorName: updated.author_name,
                            title: updated.title || '',
                            comment: updated.comment,
                            rating: updated.rating === null ? null : Number(updated.rating || 0),
                            imageUrls: Array.isArray(updated.image_urls) ? updated.image_urls : [],
                            createdAt: updated.created_at,
                            updatedAt: updated.updated_at,
                            canDelete: true
                        },
                        stats: {
                            averageRating: Number(statsResult.rows[0]?.average_rating || 0),
                            totalReviews: Number(statsResult.rows[0]?.total_reviews || 0)
                        }
                    });
                } catch (error) {
                    cleanupUploadedFiles();
                    return res.status(500).json({ message: error.message });
                }
            });
        }

        async function listPublicVenueReviews(req, res) {
            const venueId = Number(req.params.venueId);
            const sort = String(req.query.sort || 'newest').trim().toLowerCase();
            const limit = normalizePaginationValue(req.query.limit, 20, { min: 1, max: 100 });
            const currentUserId = String(req.user?.id || '').trim();

            if (!Number.isFinite(venueId)) {
                return res.status(400).json({ message: 'Invalid venue id' });
            }

            const sortClauseByType = {
                newest: 'r.created_at DESC, r.id DESC',
                oldest: 'r.created_at ASC, r.id ASC',
                rating_high: 'r.rating DESC, r.created_at DESC',
                rating_low: 'r.rating ASC, r.created_at DESC'
            };

            const sortClause = sortClauseByType[sort] || sortClauseByType.newest;

            try {
                const venueResult = await pool.query(
                    `
                        SELECT id, submitted_by_user_id, status::text AS status
                        FROM venues
                        WHERE id = $1
                        LIMIT 1
                    `,
                    [venueId]
                );

                if (!venueResult.rows.length) {
                    return res.status(404).json({ message: 'Venue not found' });
                }

                const venue = venueResult.rows[0];
                const isAdmin = normalizeRole(req.authUser?.role) === 'admin';
                const requesterId = req.authUser?.id ? String(req.authUser.id).trim() : '';
                const venueOwnerId = venue.submitted_by_user_id ? String(venue.submitted_by_user_id).trim() : '';
                const isOwner = Boolean(requesterId && venueOwnerId && requesterId === venueOwnerId);
                let adminUserIds = new Set();

                try {
                    const adminUsersResult = await pool.query(
                        `
                            SELECT id::text AS id
                            FROM users
                            WHERE LOWER(COALESCE(role::text, '')) = 'admin'
                        `
                    );

                    adminUserIds = new Set(
                        adminUsersResult.rows
                            .map((row) => String(row.id || '').trim())
                            .filter(Boolean)
                    );
                } catch {
                    adminUserIds = new Set();
                }

                if (!isAdmin && !isOwner && String(venue.status || '').toLowerCase() !== 'approved') {
                    return res.status(404).json({ message: 'Venue not found' });
                }

                const reviewResult = await pool.query(
                    `
                        SELECT
                            r.id,
                            r.user_id,
                            r.rating,
                            r.title,
                            r.comment,
                            r.author_name,
                            r.image_urls,
                            r.created_at,
                            r.updated_at,
                            COALESCE(like_stats.like_count, 0)::int AS like_count,
                            COALESCE(reply_stats.reply_count, 0)::int AS reply_count,
                            CASE
                                WHEN $2::text = '' THEN false
                                WHEN liked.review_id IS NULL THEN false
                                ELSE true
                            END AS liked_by_me
                        FROM venue_public_reviews AS r
                        LEFT JOIN (
                            SELECT review_id, COUNT(*)::int AS like_count
                            FROM venue_review_likes
                            GROUP BY review_id
                        ) AS like_stats ON like_stats.review_id = r.id
                        LEFT JOIN (
                            SELECT review_id, COUNT(*)::int AS reply_count
                            FROM venue_review_replies
                            GROUP BY review_id
                        ) AS reply_stats ON reply_stats.review_id = r.id
                        LEFT JOIN venue_review_likes AS liked
                            ON liked.review_id = r.id
                           AND liked.user_id = $2
                        WHERE r.venue_id = $1
                        ORDER BY ${sortClause}
                        LIMIT $3
                    `,
                    [venueId, currentUserId, limit]
                );

                const statsResult = await pool.query(
                    `
                        SELECT
                            COALESCE(AVG(rating)::numeric(10,2), 0) AS average_rating,
                            COUNT(*)::int AS total_reviews
                        FROM venue_public_reviews
                        WHERE venue_id = $1
                    `,
                    [venueId]
                );

                const normalizedReviewIds = reviewResult.rows
                    .map((review) => Number(review.id))
                    .filter((reviewId) => Number.isInteger(reviewId));

                let repliesByReviewId = new Map();

                if (normalizedReviewIds.length) {
                    const repliesResult = await pool.query(
                        `
                            SELECT
                                replies.id,
                                replies.review_id,
                                replies.user_id,
                                replies.author_name,
                                replies.rating,
                                replies.title,
                                replies.content,
                                replies.image_urls,
                                replies.created_at,
                                replies.updated_at,
                                COALESCE(reply_like_stats.like_count, 0)::int AS like_count,
                                CASE
                                    WHEN $2::text = '' THEN false
                                    WHEN liked.reply_id IS NULL THEN false
                                    ELSE true
                                END AS liked_by_me
                            FROM venue_review_replies AS replies
                            LEFT JOIN (
                                SELECT reply_id, COUNT(*)::int AS like_count
                                FROM venue_review_reply_likes
                                GROUP BY reply_id
                            ) AS reply_like_stats ON reply_like_stats.reply_id = replies.id
                            LEFT JOIN venue_review_reply_likes AS liked
                                ON liked.reply_id = replies.id
                               AND liked.user_id = $2
                            WHERE replies.review_id = ANY($1::bigint[])
                            ORDER BY replies.created_at ASC, replies.id ASC
                        `,
                        [normalizedReviewIds, currentUserId]
                    );

                    repliesByReviewId = repliesResult.rows.reduce((acc, reply) => {
                        const parentReviewId = Number(reply.review_id);
                        if (!acc.has(parentReviewId)) {
                            acc.set(parentReviewId, []);
                        }

                        const normalizedReplyUserId = String(reply.user_id || '').trim();
                        const isAdminReply = normalizedReplyUserId ? adminUserIds.has(normalizedReplyUserId) : false;
                        const canDeleteReply = Boolean(
                            currentUserId && (currentUserId === normalizedReplyUserId || isAdmin)
                        );

                        acc.get(parentReviewId).push({
                            id: reply.id,
                            review_id: reply.review_id,
                            user_id: reply.user_id,
                            author_name: String(reply.author_name || '').trim() || 'Anonymous',
                            rating: Number(reply.rating || 0),
                            title: reply.title || '',
                            content: reply.content || '',
                            image_urls: normalizeStringArray(reply.image_urls),
                            like_count: Number(reply.like_count || 0),
                            liked_by_me: Boolean(reply.liked_by_me),
                            is_admin: isAdminReply,
                            author_role: isAdminReply ? 'admin' : 'user',
                            can_delete: canDeleteReply,
                            created_at: reply.created_at,
                            updated_at: reply.updated_at
                        });

                        return acc;
                    }, new Map());
                }

                const reviewItems = reviewResult.rows.map((review) => {
                    const normalizedReviewId = Number(review.id);
                    const normalizedReviewUserId = String(review.user_id || '').trim();
                    const isAdminReview = normalizedReviewUserId ? adminUserIds.has(normalizedReviewUserId) : false;
                    const canDeleteReview = Boolean(
                        currentUserId && (currentUserId === normalizedReviewUserId || isAdmin)
                    );

                    return {
                        ...review,
                        image_urls: normalizeStringArray(review.image_urls),
                        like_count: Number(review.like_count || 0),
                        reply_count: Number(review.reply_count || 0),
                        liked_by_me: Boolean(review.liked_by_me),
                        is_admin: isAdminReview,
                        author_role: isAdminReview ? 'admin' : 'user',
                        can_delete: canDeleteReview,
                        replies: repliesByReviewId.get(normalizedReviewId) || []
                    };
                });

                return res.json({
                    items: reviewItems,
                    total: reviewItems.length,
                    stats: {
                        averageRating: Number(statsResult.rows[0]?.average_rating || 0),
                        totalReviews: Number(statsResult.rows[0]?.total_reviews || 0)
                    },
                    sort,
                    limit
                });
            } catch (error) {
                if (['42P01', '42703', '42883'].includes(error?.code)) {
                    return res.json({
                        items: [],
                        total: 0,
                        stats: {
                            averageRating: 0,
                            totalReviews: 0
                        },
                        sort,
                        limit
                    });
                }

                return res.status(500).json({ message: error.message });
            }
        }

        // API 2: Receive venue coordinates, use AI to detect Ward and save to Database
        async function createVenueSubmission(req, res) {
            const {
                name,
                title,
                address,
                categoryId,
                category_id,
                category,
                latitude,
                longitude,
                description,
                phone,
                coverImageUrl,
                businessLicenseImageUrl,
                contactEmail,
                metadata
            } = req.body;

            const normalizedName = String(name || '').trim();
            const normalizedAddress = String(address || '').trim() || 'Address not provided';
            const normalizedLatitude = Number(latitude);
            const normalizedLongitude = Number(longitude);
            const normalizedCategoryId = normalizeCategoryId(categoryId ?? category_id);
            const normalizedCategoryName = String(category || '').trim();
            const normalizedMetadata = metadata && typeof metadata === 'object' ? { ...metadata } : {};
            const requestedServiceIds = normalizeServiceIds(normalizedMetadata.selectedServices);
            const normalizedContactEmail = normalizeNullableText(
                contactEmail ?? normalizedMetadata.contactEmail ?? req.authUser?.email
            );
            const resolvedOwnerUserId = await getAuthenticatedChatUserId(req);
            const submitterUserId = String(resolvedOwnerUserId || req.authUser?.id || '').trim();

            if (normalizedContactEmail && !isValidEmail(normalizedContactEmail)) {
                return res.status(400).json({ message: 'contactEmail is invalid' });
            }

            if (!submitterUserId) {
                return res.status(401).json({ message: 'Missing authentication token' });
            }

            if (normalizedContactEmail && !normalizedMetadata.contactEmail) {
                normalizedMetadata.contactEmail = normalizedContactEmail;
            }

            if (!normalizedMetadata.category && normalizedCategoryName) {
                normalizedMetadata.category = normalizedCategoryName;
            }

            if (!normalizedName) {
                return res.status(400).json({ message: 'Venue name is required' });
            }

            if (!Number.isFinite(normalizedLatitude) || !Number.isFinite(normalizedLongitude)) {
                return res.status(400).json({ message: 'Latitude and longitude must be valid numbers' });
            }

            if (Number.isNaN(normalizedCategoryId)) {
                return res.status(400).json({ message: 'categoryId must be a positive integer' });
            }

            try {
                const venueHasOwnerUserColumn = await hasVenueOwnerUserColumn();
                let resolvedCategoryId = normalizedCategoryId;
                const activePurchase = await getLatestActiveUserAdPackagePurchase(submitterUserId);
                const activePackageFeatures = activePurchase?.package?.features || {};
                const isPostLimitEnabled = Boolean(activePackageFeatures.postLimitEnabled);
                const postLimit = Number(activePackageFeatures.postLimit);

                const existingVenueCountResult = await pool.query(
                    `
                        SELECT COUNT(*)::int AS total
                        FROM venues
                        WHERE ${buildResolvedVenueOwnerUserSql('venues')} = $1
                          AND LOWER(COALESCE(venues.status::text, '')) NOT IN ('deleted', 'rejected')
                    `,
                    [submitterUserId]
                );
                const existingVenueCount = Number(existingVenueCountResult.rows[0]?.total) || 0;
                const effectivePostLimit = isPostLimitEnabled && Number.isFinite(postLimit) && postLimit > 0
                    ? postLimit
                    : 1;

                if (existingVenueCount >= effectivePostLimit) {
                    const limitMessage = effectivePostLimit === 1
                        ? 'Each merchant account can publish 1 venue by default. Purchase a package with Post Quantity Limit to unlock more posts.'
                        : `Your active package allows up to ${effectivePostLimit} venue posts. Delete an existing venue or switch to a higher package to submit more posts.`;

                    return res.status(409).json({
                        message: limitMessage
                    });
                }

                if (resolvedCategoryId === null && normalizedCategoryName) {
                    const inferredSlug = slugifyText(normalizedCategoryName);
                    const categoryLookup = await pool.query(
                        `
                    SELECT id
                    FROM place_categories
                    WHERE is_active = true
                      AND (LOWER(name) = LOWER($1) OR slug = $2)
                    LIMIT 1
                `,
                        [normalizedCategoryName, inferredSlug]
                    );

                    resolvedCategoryId = categoryLookup.rows[0]?.id ?? null;
                }

                if (resolvedCategoryId !== null) {
                    const categoryCheck = await pool.query(
                        `
                    SELECT id
                    FROM place_categories
                    WHERE id = $1
                      AND is_active = true
                    LIMIT 1
                `,
                        [resolvedCategoryId]
                    );

                    if (!categoryCheck.rows.length) {
                        return res.status(400).json({ message: 'Selected category is invalid or inactive' });
                    }
                }

                if (requestedServiceIds.length) {
                    const servicesResult = await pool.query(
                        `
                        SELECT id, name
                        FROM merchant_services
                        WHERE id = ANY($1::int[])
                          AND is_active = true
                    `,
                        [requestedServiceIds]
                    );

                    if (servicesResult.rows.length !== requestedServiceIds.length) {
                        return res.status(400).json({ message: 'Selected services are invalid or inactive' });
                    }

                    const serviceNameMap = new Map(
                        servicesResult.rows.map((service) => [Number(service.id), service.name])
                    );

                    normalizedMetadata.selectedServices = requestedServiceIds;
                    normalizedMetadata.selectedServiceNames = requestedServiceIds
                        .map((serviceId) => serviceNameMap.get(serviceId))
                        .filter(Boolean);
                } else {
                    normalizedMetadata.selectedServices = [];
                    normalizedMetadata.selectedServiceNames = [];
                }

                const metadataStartTime = String(normalizedMetadata.startTime || '').trim();
                const metadataEndTime = String(normalizedMetadata.endTime || '').trim();
                const incomingMetadata = normalizedMetadata;
                const hasCanonicalWeeklySchedule =
                    normalizedMetadata.weeklySchedule &&
                    typeof normalizedMetadata.weeklySchedule === 'object' &&
                    !Array.isArray(normalizedMetadata.weeklySchedule);
                const hasLegacyWeeklyOpenHours =
                    normalizedMetadata.weeklyOpenHours &&
                    typeof normalizedMetadata.weeklyOpenHours === 'object' &&
                    !Array.isArray(normalizedMetadata.weeklyOpenHours);
                const hasGlobalTimeRange =
                    /^\d{2}:\d{2}$/.test(metadataStartTime) &&
                    /^\d{2}:\d{2}$/.test(metadataEndTime) &&
                    metadataStartTime < metadataEndTime;

                if (hasCanonicalWeeklySchedule || hasLegacyWeeklyOpenHours || hasGlobalTimeRange) {
                    const weeklyScheduleCandidate = resolveWeeklyScheduleSource(normalizedMetadata, incomingMetadata);

                    const normalizedScheduleResult = normalizeWeeklyScheduleInput(weeklyScheduleCandidate, {
                        fallbackStart: metadataStartTime,
                        fallbackEnd: metadataEndTime
                    });

                    if (normalizedScheduleResult.error) {
                        return res.status(400).json({ message: normalizedScheduleResult.error });
                    }

                    normalizedMetadata.weeklySchedule = normalizedScheduleResult.value;
                }

                const duplicateLocationResult = await pool.query(
                    `
                    SELECT id, status::text AS status
                    FROM venues
                    WHERE COALESCE(status::text, '') IN ('pending', 'approved')
                                            AND ABS(latitude - $1) <= 0.00003
                                            AND ABS(longitude - $2) <= 0.00003
                    ORDER BY COALESCE(submitted_at, created_at) DESC, id DESC
                    LIMIT 1
                `,
                    [normalizedLatitude, normalizedLongitude]
                );

                if (duplicateLocationResult.rows.length) {
                    const existingStatus = String(duplicateLocationResult.rows[0].status || '').toLowerCase();
                    return res.status(409).json({
                        message:
                            existingStatus === 'pending'
                                ? 'A venue submission at this location is already waiting for admin review.'
                                : 'A venue at this location has already been approved. Please pick a different location.'
                    });
                }

                const detection = await detectWardByCoordinates(normalizedLatitude, normalizedLongitude);

                const insertColumns = [
                    'name',
                    'title',
                    ...(venueHasOwnerUserColumn ? ['owner_user_id'] : []),
                    'submitted_by_user_id',
                    'address',
                    'description',
                    'phone',
                    'latitude',
                    'longitude',
                    'ward_id',
                    'category_id',
                    'cover_image_url',
                    'business_license_image_url',
                    'metadata',
                    'status',
                    'submitted_at',
                    'updated_at'
                ];
                const insertValues = [
                    normalizedName,
                    String(title || '').trim() || normalizedName,
                    ...(venueHasOwnerUserColumn
                        ? [submitterUserId]
                        : []),
                    submitterUserId,
                    normalizedAddress,
                    String(description || '').trim() || null,
                    String(phone || '').trim() || null,
                    normalizedLatitude,
                    normalizedLongitude,
                    detection.wardId,
                    resolvedCategoryId,
                    String(coverImageUrl || '').trim() || null,
                    String(businessLicenseImageUrl || '').trim() || null,
                    normalizedMetadata
                ];
                const insertPlaceholders = insertValues.map((_, index) => `$${index + 1}`);

                const insertResult = await pool.query(
                    `
                INSERT INTO venues (
                    ${insertColumns.join(',\n                    ')}
                )
                VALUES (
                    ${insertPlaceholders.join(',\n                    ')},
                    'pending',
                    now(),
                    now()
                )
                RETURNING id
            `,
                    insertValues
                );

                try {
                    if (activePurchase?.packageId) {
                        await syncUserAdPackageAssignments(submitterUserId, activePurchase.packageId, pool, {
                            specificVenueIds: [insertResult.rows[0].id]
                        });
                    }
                } catch (assignmentSyncError) {
                    console.error('Sync account ad package for new venue error:', assignmentSyncError);
                }

                const venueDetails = await pool.query(
                    `
                SELECT
                    venues.id,
                    venues.name,
                    venues.title,
                    venues.address,
                    venues.description,
                    venues.phone,
                    venues.latitude,
                    venues.longitude,
                    venues.ward_id,
                    wards.name AS ward_name,
                    venues.category_id,
                    place_categories.name AS category_name,
                    place_categories.slug AS category_slug,
                    venues.cover_image_url,
                    venues.business_license_image_url,
                    venues.metadata,
                    venues.submitted_by_user_id,
                    venues.status::text AS status,
                    venues.submitted_at,
                    venues.created_at,
                    venues.updated_at
                FROM venues
                LEFT JOIN wards ON wards.ward_id = venues.ward_id
                LEFT JOIN place_categories ON place_categories.id = venues.category_id
                WHERE venues.id = $1
                LIMIT 1
            `,
                    [insertResult.rows[0].id]
                );

                await createUserNotification({
                    userId: submitterUserId,
                    type: 'venue_submission',
                    title: 'Đăng bài thành công',
                    content: `${normalizedName} đang chờ quản trị viên duyệt.`,
                    metadata: {
                        venueId: Number(insertResult.rows[0].id),
                        status: 'pending'
                    }
                });

                res.json({
                    message: 'Venue submitted successfully and is waiting for admin approval.',
                    submissionStatus: 'pending',
                    detectedWard: detection.wardName,
                    detected_ward: detection.wardName,
                    venue: venueDetails.rows[0]
                });
            } catch (err) {
                console.error('API error:', err);
                res.status(500).json({ error: 'Server error' });
            }
        }

        async function getMerchantVenueEditDraft(req, res) {
            const venueId = Number(req.params.venueId);

            if (!Number.isFinite(venueId)) {
                return res.status(400).json({ message: 'Invalid venue id' });
            }

            try {
                const currentUserId = await getAuthenticatedChatUserId(req);
                const isAdmin = normalizeRole(req.authUser?.role) === 'admin';

                if (!currentUserId && !isAdmin) {
                    return res.status(401).json({ message: 'Missing authentication token' });
                }

                const venueHasOwnerUserColumn = await hasVenueOwnerUserColumn();
                const resolvedOwnerUserSql = buildResolvedVenueOwnerUserSql('venues');
                const ownerSelect = venueHasOwnerUserColumn
                    ? `${resolvedOwnerUserSql} AS owner_user_id,`
                    : `NULL::uuid AS owner_user_id,`;

                const result = await pool.query(
                    `
                        SELECT
                            venues.id,
                            venues.name,
                            venues.title,
                            ${ownerSelect}
                            venues.submitted_by_user_id,
                            venues.address,
                            venues.description,
                            venues.phone,
                            venues.latitude,
                            venues.longitude,
                            venues.ward_id,
                            wards.name AS ward_name,
                            venues.category_id,
                            place_categories.name AS category_name,
                            place_categories.slug AS category_slug,
                            venues.cover_image_url,
                            venues.business_license_image_url,
                            venues.metadata,
                            venues.average_rating,
                            venues.total_reviews,
                            venues.status::text AS status,
                            venues.submitted_at,
                            venues.approved_at,
                            venues.rejected_at,
                            venues.rejection_reason,
                            venues.created_at,
                            venues.updated_at
                        FROM venues
                        LEFT JOIN wards ON wards.ward_id = venues.ward_id
                        LEFT JOIN place_categories ON place_categories.id = venues.category_id
                        WHERE venues.id = $1
                        LIMIT 1
                    `,
                    [venueId]
                );

                if (!result.rows.length) {
                    return res.status(404).json({ message: 'Venue not found' });
                }

                const venue = result.rows[0];
                const ownerCandidateIds = extractVenueOwnerCandidateIds(venue);
                const isOwner = Boolean(currentUserId && ownerCandidateIds.includes(String(currentUserId || '').trim()));

                if (!isAdmin && !isOwner) {
                    return res.status(403).json({ message: 'You do not have permission to edit this venue' });
                }

                const galleryImagesFromTable = await loadVenueGalleryImageUrls(venue.id);
                const resolvedReviewStats = await resolveVenueReviewStatsByVenueId(venue.id);
                const normalizedVenue = normalizeVenueCoordinates(venue);
                const enrichedVenue = {
                    ...normalizedVenue,
                    average_rating: Number(resolvedReviewStats?.averageRating ?? venue.average_rating ?? 0),
                    total_reviews: Number(resolvedReviewStats?.totalReviews ?? venue.total_reviews ?? 0),
                    averageRating: Number(resolvedReviewStats?.averageRating ?? venue.average_rating ?? 0),
                    totalReviews: Number(resolvedReviewStats?.totalReviews ?? venue.total_reviews ?? 0),
                    review_count: Number(resolvedReviewStats?.totalReviews ?? venue.total_reviews ?? 0),
                    reviewCount: Number(resolvedReviewStats?.totalReviews ?? venue.total_reviews ?? 0),
                    venue_images: extractVenueImageUrls(venue, galleryImagesFromTable)
                };

                let pendingUpdateRequest = null;

                try {
                    const updateRequestResult = await pool.query(
                        `
                            SELECT
                                id,
                                venue_id,
                                submitted_by_user_id,
                                old_snapshot,
                                proposed_snapshot,
                                status,
                                rejection_reason,
                                reviewed_by,
                                submitted_at,
                                reviewed_at,
                                created_at,
                                updated_at
                            FROM venue_update_requests
                            WHERE venue_id = $1
                              AND status = 'pending'
                            ORDER BY COALESCE(submitted_at, created_at) DESC, id DESC
                            LIMIT 1
                        `,
                        [venueId]
                    );

                    if (updateRequestResult.rows.length) {
                        pendingUpdateRequest = updateRequestResult.rows[0];
                    }
                } catch (updateRequestError) {
                    if (!isUndefinedTableError(updateRequestError)) {
                        throw updateRequestError;
                    }
                }

                return res.json({
                    venue: enrichedVenue,
                    pendingUpdateRequest
                });
            } catch (error) {
                return res.status(500).json({ message: error.message });
            }
        }

        async function submitMerchantVenueUpdateRequest(req, res) {
            const venueId = Number(req.params.venueId);

            if (!Number.isFinite(venueId)) {
                return res.status(400).json({ message: 'Invalid venue id' });
            }

            try {
                const currentUserId = await getAuthenticatedChatUserId(req);
                const isAdmin = normalizeRole(req.authUser?.role) === 'admin';

                if (!currentUserId && !isAdmin) {
                    return res.status(401).json({ message: 'Missing authentication token' });
                }

                const venueHasOwnerUserColumn = await hasVenueOwnerUserColumn();
                const resolvedOwnerUserSql = buildResolvedVenueOwnerUserSql('venues');
                const ownerSelect = venueHasOwnerUserColumn
                    ? `${resolvedOwnerUserSql} AS owner_user_id,`
                    : `NULL::uuid AS owner_user_id,`;

                const venueResult = await pool.query(
                    `
                        SELECT
                            venues.id,
                            venues.name,
                            venues.title,
                            ${ownerSelect}
                            venues.submitted_by_user_id,
                            venues.address,
                            venues.description,
                            venues.phone,
                            venues.latitude,
                            venues.longitude,
                            venues.ward_id,
                            venues.category_id,
                            venues.cover_image_url,
                            venues.business_license_image_url,
                            venues.metadata,
                            venues.status::text AS status
                        FROM venues
                        WHERE venues.id = $1
                        LIMIT 1
                    `,
                    [venueId]
                );

                if (!venueResult.rows.length) {
                    return res.status(404).json({ message: 'Venue not found' });
                }

                const venue = venueResult.rows[0];
                const ownerCandidateIds = extractVenueOwnerCandidateIds(venue);
                const isOwner = Boolean(currentUserId && ownerCandidateIds.includes(String(currentUserId || '').trim()));

                if (!isAdmin && !isOwner) {
                    return res.status(403).json({ message: 'You do not have permission to edit this venue' });
                }

                if (String(venue.status || '').toLowerCase() !== 'approved') {
                    return res.status(400).json({ message: 'Only approved venues can submit update requests' });
                }

                const {
                    name,
                    title,
                    address,
                    categoryId,
                    category_id,
                    category,
                    wardId,
                    ward_id,
                    latitude,
                    longitude,
                    description,
                    phone,
                    coverImageUrl,
                    businessLicenseImageUrl,
                    contactEmail,
                    metadata
                } = req.body || {};

                const normalizedName = String(name || title || '').trim();
                const normalizedAddress = String(address || '').trim();
                const normalizedLatitude = Number(latitude);
                const normalizedLongitude = Number(longitude);
                const normalizedCategoryId = normalizeCategoryId(categoryId ?? category_id);
                const normalizedCategoryName = String(category || '').trim();
                const existingMetadata = normalizeVenueMetadataObject(venue.metadata);
                const incomingMetadata = metadata && typeof metadata === 'object' && !Array.isArray(metadata)
                    ? { ...metadata }
                    : {};
                const normalizedMetadata = {
                    ...existingMetadata,
                    ...incomingMetadata
                };

                if (!normalizedName) {
                    return res.status(400).json({ message: 'Venue name is required' });
                }

                if (!normalizedAddress) {
                    return res.status(400).json({ message: 'Address is required' });
                }

                if (!Number.isFinite(normalizedLatitude) || !Number.isFinite(normalizedLongitude)) {
                    return res.status(400).json({ message: 'Latitude and longitude must be valid numbers' });
                }

                if (Number.isNaN(normalizedCategoryId)) {
                    return res.status(400).json({ message: 'categoryId must be a positive integer' });
                }

                let resolvedCategoryId = normalizedCategoryId;

                if (resolvedCategoryId === null && normalizedCategoryName) {
                    const inferredSlug = slugifyText(normalizedCategoryName);
                    const categoryLookup = await pool.query(
                        `
                            SELECT id
                            FROM place_categories
                            WHERE is_active = true
                              AND (LOWER(name) = LOWER($1) OR slug = $2)
                            LIMIT 1
                        `,
                        [normalizedCategoryName, inferredSlug]
                    );

                    resolvedCategoryId = categoryLookup.rows[0]?.id ?? null;
                }

                if (resolvedCategoryId !== null) {
                    const categoryCheck = await pool.query(
                        `
                            SELECT id
                            FROM place_categories
                            WHERE id = $1
                              AND is_active = true
                            LIMIT 1
                        `,
                        [resolvedCategoryId]
                    );

                    if (!categoryCheck.rows.length) {
                        return res.status(400).json({ message: 'Selected category is invalid or inactive' });
                    }
                }

                const requestedServiceIds = normalizeServiceIds(normalizedMetadata.selectedServices);
                if (requestedServiceIds.length) {
                    const servicesResult = await pool.query(
                        `
                            SELECT id, name
                            FROM merchant_services
                            WHERE id = ANY($1::int[])
                              AND is_active = true
                        `,
                        [requestedServiceIds]
                    );

                    if (servicesResult.rows.length !== requestedServiceIds.length) {
                        return res.status(400).json({ message: 'Selected services are invalid or inactive' });
                    }

                    const serviceNameMap = new Map(
                        servicesResult.rows.map((service) => [Number(service.id), service.name])
                    );

                    normalizedMetadata.selectedServices = requestedServiceIds;
                    normalizedMetadata.selectedServiceNames = requestedServiceIds
                        .map((serviceId) => serviceNameMap.get(serviceId))
                        .filter(Boolean);
                } else {
                    normalizedMetadata.selectedServices = [];
                    normalizedMetadata.selectedServiceNames = [];
                }

                const metadataStartTime = String(normalizedMetadata.startTime || '').trim();
                const metadataEndTime = String(normalizedMetadata.endTime || '').trim();
                const hasCanonicalWeeklySchedule =
                    normalizedMetadata.weeklySchedule &&
                    typeof normalizedMetadata.weeklySchedule === 'object' &&
                    !Array.isArray(normalizedMetadata.weeklySchedule);
                const hasLegacyWeeklyOpenHours =
                    normalizedMetadata.weeklyOpenHours &&
                    typeof normalizedMetadata.weeklyOpenHours === 'object' &&
                    !Array.isArray(normalizedMetadata.weeklyOpenHours);
                const hasGlobalTimeRange =
                    /^\d{2}:\d{2}$/.test(metadataStartTime) &&
                    /^\d{2}:\d{2}$/.test(metadataEndTime) &&
                    metadataStartTime < metadataEndTime;

                if (hasCanonicalWeeklySchedule || hasLegacyWeeklyOpenHours || hasGlobalTimeRange) {
                    const weeklyScheduleCandidate = resolveWeeklyScheduleSource(normalizedMetadata, incomingMetadata);

                    const normalizedScheduleResult = normalizeWeeklyScheduleInput(weeklyScheduleCandidate, {
                        fallbackStart: metadataStartTime,
                        fallbackEnd: metadataEndTime
                    });

                    if (normalizedScheduleResult.error) {
                        return res.status(400).json({ message: normalizedScheduleResult.error });
                    }

                    normalizedMetadata.weeklySchedule = normalizedScheduleResult.value;
                }

                const normalizedContactEmail = normalizeNullableText(
                    contactEmail ?? normalizedMetadata.contactEmail ?? req.authUser?.email
                );

                if (normalizedContactEmail && !isValidEmail(normalizedContactEmail)) {
                    return res.status(400).json({ message: 'contactEmail is invalid' });
                }

                if (normalizedContactEmail) {
                    normalizedMetadata.contactEmail = normalizedContactEmail;
                }

                const requestedWardId = normalizeNullableText(wardId ?? ward_id ?? normalizedMetadata.wardId);
                const detectedWard = await detectWardByCoordinates(normalizedLatitude, normalizedLongitude);
                const resolvedWardId = normalizeNullableText(detectedWard?.wardId || requestedWardId);

                if (!resolvedWardId) {
                    return res.status(400).json({ message: 'Selected location must be inside a valid ward boundary' });
                }

                if (requestedWardId && requestedWardId !== resolvedWardId) {
                    return res.status(400).json({ message: 'Selected ward does not match chosen map location' });
                }

                const duplicateLocationResult = await pool.query(
                    `
                        SELECT id, status::text AS status
                        FROM venues
                        WHERE id <> $3
                          AND COALESCE(status::text, '') IN ('pending', 'approved')
                          AND ABS(latitude - $1) <= 0.00003
                          AND ABS(longitude - $2) <= 0.00003
                        ORDER BY COALESCE(submitted_at, created_at) DESC, id DESC
                        LIMIT 1
                    `,
                    [normalizedLatitude, normalizedLongitude, venueId]
                );

                if (duplicateLocationResult.rows.length) {
                    const existingStatus = String(duplicateLocationResult.rows[0].status || '').toLowerCase();
                    return res.status(409).json({
                        message:
                            existingStatus === 'pending'
                                ? 'A venue submission at this location is already waiting for admin review.'
                                : 'A venue at this location has already been approved. Please pick a different location.'
                    });
                }

                normalizedMetadata.category = normalizedCategoryName || normalizedMetadata.category || null;
                normalizedMetadata.categoryId = resolvedCategoryId;
                normalizedMetadata.wardId = resolvedWardId;
                normalizedMetadata.wardName = String(detectedWard?.wardName || normalizedMetadata.wardName || '').trim() || null;

                const proposedSnapshot = normalizeVenueUpdateSnapshot({
                    name: normalizedName,
                    title: String(title || '').trim() || normalizedName,
                    address: normalizedAddress,
                    description: normalizeNullableText(description),
                    phone: normalizeNullableText(phone),
                    latitude: normalizedLatitude,
                    longitude: normalizedLongitude,
                    wardId: resolvedWardId,
                    categoryId: resolvedCategoryId,
                    coverImageUrl,
                    businessLicenseImageUrl,
                    metadata: normalizedMetadata
                });

                const oldSnapshot = normalizeVenueUpdateSnapshot({
                    name: venue.name,
                    title: venue.title,
                    address: venue.address,
                    description: venue.description,
                    phone: venue.phone,
                    latitude: venue.latitude,
                    longitude: venue.longitude,
                    wardId: venue.ward_id,
                    categoryId: venue.category_id,
                    coverImageUrl: venue.cover_image_url,
                    businessLicenseImageUrl: venue.business_license_image_url,
                    metadata: existingMetadata
                });

                if (areJsonValuesEqual(oldSnapshot, proposedSnapshot)) {
                    return res.status(400).json({ message: 'No changes detected. Please update at least one field.' });
                }

                const pendingRequestResult = await pool.query(
                    `
                        SELECT id
                        FROM venue_update_requests
                        WHERE venue_id = $1
                          AND status = 'pending'
                        ORDER BY COALESCE(submitted_at, created_at) DESC, id DESC
                        LIMIT 1
                    `,
                    [venueId]
                );

                let requestRecord = null;

                if (pendingRequestResult.rows.length) {
                    const existingRequestId = Number(pendingRequestResult.rows[0].id);
                    const updateResult = await pool.query(
                        `
                            UPDATE venue_update_requests
                            SET
                                submitted_by_user_id = $2,
                                old_snapshot = $3::jsonb,
                                proposed_snapshot = $4::jsonb,
                                status = 'pending',
                                rejection_reason = NULL,
                                reviewed_by = NULL,
                                reviewed_at = NULL,
                                submitted_at = now(),
                                updated_at = now()
                            WHERE id = $1
                            RETURNING *
                        `,
                        [existingRequestId, currentUserId, oldSnapshot, proposedSnapshot]
                    );

                    requestRecord = updateResult.rows[0] || null;
                } else {
                    const insertResult = await pool.query(
                        `
                            INSERT INTO venue_update_requests (
                                venue_id,
                                submitted_by_user_id,
                                old_snapshot,
                                proposed_snapshot,
                                status,
                                submitted_at,
                                created_at,
                                updated_at
                            )
                            VALUES (
                                $1,
                                $2,
                                $3::jsonb,
                                $4::jsonb,
                                'pending',
                                now(),
                                now(),
                                now()
                            )
                            RETURNING *
                        `,
                        [venueId, currentUserId, oldSnapshot, proposedSnapshot]
                    );

                    requestRecord = insertResult.rows[0] || null;
                }

                return res.json({
                    message: 'Update request submitted successfully and is awaiting admin review.',
                    updateRequest: requestRecord,
                    proposedWardName: detectedWard?.wardName || null
                });
            } catch (error) {
                if (isUndefinedTableError(error)) {
                    return res.status(500).json({
                        message: 'Venue update workflow is not initialized. Please run backend migrations.'
                    });
                }

                return res.status(500).json({ message: error.message });
            }
        }

        async function updateMerchantVenueSimpleInfo(req, res) {
            const venueId = Number(req.params.venueId);

            if (!Number.isFinite(venueId)) {
                return res.status(400).json({ message: 'Invalid venue id' });
            }

            try {
                const currentUserId = await getAuthenticatedChatUserId(req);
                const isAdmin = normalizeRole(req.authUser?.role) === 'admin';

                if (!currentUserId && !isAdmin) {
                    return res.status(401).json({ message: 'Missing authentication token' });
                }

                const venueHasOwnerUserColumn = await hasVenueOwnerUserColumn();
                const resolvedOwnerUserSql = buildResolvedVenueOwnerUserSql('venues');
                const ownerSelect = venueHasOwnerUserColumn
                    ? `${resolvedOwnerUserSql} AS owner_user_id,`
                    : `NULL::uuid AS owner_user_id,`;

                const venueResult = await pool.query(
                    `
                        SELECT
                            venues.id,
                            venues.name,
                            venues.title,
                            ${ownerSelect}
                            venues.submitted_by_user_id,
                            venues.description,
                            venues.phone,
                            venues.metadata,
                            venues.status::text AS status
                        FROM venues
                        WHERE venues.id = $1
                        LIMIT 1
                    `,
                    [venueId]
                );

                if (!venueResult.rows.length) {
                    return res.status(404).json({ message: 'Venue not found' });
                }

                const venue = venueResult.rows[0];
                const ownerCandidateIds = extractVenueOwnerCandidateIds(venue);
                const isOwner = Boolean(currentUserId && ownerCandidateIds.includes(String(currentUserId || '').trim()));

                if (!isAdmin && !isOwner) {
                    return res.status(403).json({ message: 'You do not have permission to edit this venue' });
                }

                if (String(venue.status || '').toLowerCase() !== 'approved') {
                    return res.status(400).json({ message: 'Only approved venues can be updated directly' });
                }

                const body = req.body || {};
                const existingMetadata = normalizeVenueMetadataObject(venue.metadata);
                const incomingMetadata = body.metadata && typeof body.metadata === 'object' && !Array.isArray(body.metadata)
                    ? body.metadata
                    : {};
                const allowedSimpleMetadata = pickVenueMetadataFields(incomingMetadata, VENUE_SIMPLE_METADATA_KEYS);
                const normalizedMetadata = {
                    ...existingMetadata,
                    ...allowedSimpleMetadata
                };

                const hasPhoneField = Object.prototype.hasOwnProperty.call(body, 'phone');
                const hasDescriptionField = Object.prototype.hasOwnProperty.call(body, 'description');
                const normalizedPhone = hasPhoneField
                    ? normalizeNullableText(body.phone)
                    : normalizeNullableText(venue.phone);
                const normalizedDescription = hasDescriptionField
                    ? normalizeNullableText(body.description)
                    : normalizeNullableText(venue.description);

                if (!normalizedPhone) {
                    return res.status(400).json({ message: 'Phone number is required' });
                }

                if (!/^\d{10,11}$/.test(normalizedPhone)) {
                    return res.status(400).json({ message: 'Phone number must contain 10-11 digits' });
                }

                const normalizedMinPrice =
                    normalizedMetadata.minPrice === undefined || normalizedMetadata.minPrice === null || normalizedMetadata.minPrice === ''
                        ? null
                        : Number(normalizedMetadata.minPrice);
                const normalizedMaxPrice =
                    normalizedMetadata.maxPrice === undefined || normalizedMetadata.maxPrice === null || normalizedMetadata.maxPrice === ''
                        ? null
                        : Number(normalizedMetadata.maxPrice);

                if (normalizedMinPrice !== null && (!Number.isFinite(normalizedMinPrice) || normalizedMinPrice < 0)) {
                    return res.status(400).json({ message: 'minPrice must be a non-negative number' });
                }

                if (normalizedMaxPrice !== null && (!Number.isFinite(normalizedMaxPrice) || normalizedMaxPrice < 0)) {
                    return res.status(400).json({ message: 'maxPrice must be a non-negative number' });
                }

                if (normalizedMinPrice !== null || normalizedMaxPrice !== null) {
                    if (normalizedMinPrice === null || normalizedMaxPrice === null) {
                        return res.status(400).json({ message: 'Both minPrice and maxPrice are required when setting a price range' });
                    }

                    if (normalizedMinPrice >= normalizedMaxPrice) {
                        return res.status(400).json({ message: 'maxPrice must be greater than minPrice' });
                    }
                }

                normalizedMetadata.minPrice = normalizedMinPrice;
                normalizedMetadata.maxPrice = normalizedMaxPrice;

                const metadataStartTime = String(normalizedMetadata.startTime || '').trim();
                const metadataEndTime = String(normalizedMetadata.endTime || '').trim();
                const hasCanonicalWeeklySchedule =
                    normalizedMetadata.weeklySchedule &&
                    typeof normalizedMetadata.weeklySchedule === 'object' &&
                    !Array.isArray(normalizedMetadata.weeklySchedule);
                const hasLegacyWeeklyOpenHours =
                    normalizedMetadata.weeklyOpenHours &&
                    typeof normalizedMetadata.weeklyOpenHours === 'object' &&
                    !Array.isArray(normalizedMetadata.weeklyOpenHours);
                const hasGlobalTimeRange =
                    /^\d{2}:\d{2}$/.test(metadataStartTime) &&
                    /^\d{2}:\d{2}$/.test(metadataEndTime) &&
                    metadataStartTime < metadataEndTime;

                if (hasCanonicalWeeklySchedule || hasLegacyWeeklyOpenHours || hasGlobalTimeRange) {
                    const weeklyScheduleCandidate = resolveWeeklyScheduleSource(normalizedMetadata, allowedSimpleMetadata);
                    const normalizedScheduleResult = normalizeWeeklyScheduleInput(weeklyScheduleCandidate, {
                        fallbackStart: metadataStartTime,
                        fallbackEnd: metadataEndTime
                    });

                    if (normalizedScheduleResult.error) {
                        return res.status(400).json({ message: normalizedScheduleResult.error });
                    }

                    normalizedMetadata.weeklySchedule = normalizedScheduleResult.value;
                }

                const requestedServiceIds = normalizeServiceIds(normalizedMetadata.selectedServices);
                if (requestedServiceIds.length) {
                    const servicesResult = await pool.query(
                        `
                            SELECT id, name
                            FROM merchant_services
                            WHERE id = ANY($1::int[])
                              AND is_active = true
                        `,
                        [requestedServiceIds]
                    );

                    if (servicesResult.rows.length !== requestedServiceIds.length) {
                        return res.status(400).json({ message: 'Selected services are invalid or inactive' });
                    }

                    const serviceNameMap = new Map(
                        servicesResult.rows.map((service) => [Number(service.id), service.name])
                    );

                    normalizedMetadata.selectedServices = requestedServiceIds;
                    normalizedMetadata.selectedServiceNames = requestedServiceIds
                        .map((serviceId) => serviceNameMap.get(serviceId))
                        .filter(Boolean);
                } else {
                    normalizedMetadata.selectedServices = [];
                    normalizedMetadata.selectedServiceNames = [];
                }

                const normalizedContactEmail = normalizeNullableText(
                    normalizedMetadata.contactEmail ?? req.authUser?.email
                );

                if (normalizedContactEmail && !isValidEmail(normalizedContactEmail)) {
                    return res.status(400).json({ message: 'contactEmail is invalid' });
                }

                if (normalizedContactEmail) {
                    normalizedMetadata.contactEmail = normalizedContactEmail;
                } else {
                    delete normalizedMetadata.contactEmail;
                }

                const previousSnapshot = {
                    phone: normalizeNullableText(venue.phone),
                    description: normalizeNullableText(venue.description),
                    metadata: pickVenueMetadataFields(existingMetadata, VENUE_SIMPLE_METADATA_KEYS)
                };
                const nextSnapshot = {
                    phone: normalizedPhone,
                    description: normalizedDescription,
                    metadata: pickVenueMetadataFields(normalizedMetadata, VENUE_SIMPLE_METADATA_KEYS)
                };

                if (areJsonValuesEqual(previousSnapshot, nextSnapshot)) {
                    return res.status(400).json({ message: 'No changes detected. Please update at least one simple field.' });
                }

                const updateResult = await pool.query(
                    `
                        UPDATE venues
                        SET
                            description = $2,
                            phone = $3,
                            metadata = $4::jsonb,
                            updated_at = now()
                        WHERE id = $1
                        RETURNING id, description, phone, metadata, updated_at
                    `,
                    [venueId, normalizedDescription, normalizedPhone, normalizedMetadata]
                );

                if (!updateResult.rows.length) {
                    return res.status(404).json({ message: 'Venue not found' });
                }

                invalidateVenueCommunityBundleCacheByVenueId(venueId);
                publicCompactApprovedVenuesCache = { timestamp: 0, data: null };
                publicVenueDetailCache.delete(`public:${venueId}`);
                publicVenueDetailCache.delete(`admin:${venueId}`);
                publicVenueForDetailCache.delete(`public:${venueId}`);
                publicVenueForDetailCache.delete(`admin:${venueId}`);

                return res.json({
                    message: 'Simple venue information updated successfully.',
                    venue: updateResult.rows[0]
                });
            } catch (error) {
                return res.status(500).json({ message: error.message });
            }
        }

        async function deleteMerchantVenue(req, res) {
            const venueId = Number(req.params.venueId);

            if (!Number.isFinite(venueId)) {
                return res.status(400).json({ message: 'Invalid venue id' });
            }

            try {
                const currentUserId = await getAuthenticatedChatUserId(req);
                const isAdmin = normalizeRole(req.authUser?.role) === 'admin';

                if (!currentUserId && !isAdmin) {
                    return res.status(401).json({ message: 'Missing authentication token' });
                }

                const venueHasOwnerUserColumn = await hasVenueOwnerUserColumn();
                const resolvedOwnerUserSql = buildResolvedVenueOwnerUserSql('venues');
                const ownerSelect = venueHasOwnerUserColumn
                    ? `${resolvedOwnerUserSql} AS owner_user_id,`
                    : `NULL::uuid AS owner_user_id,`;

                const venueResult = await pool.query(
                    `
                        SELECT
                            venues.id,
                            venues.name,
                            venues.title,
                            ${ownerSelect}
                            venues.submitted_by_user_id,
                            venues.status::text AS status,
                            venues.metadata
                        FROM venues
                        WHERE venues.id = $1
                        LIMIT 1
                    `,
                    [venueId]
                );

                if (!venueResult.rows.length) {
                    return res.status(404).json({ message: 'Venue not found' });
                }

                const venue = venueResult.rows[0];
                const venueMetadata = normalizeVenueMetadataObject(venue?.metadata);
                if (venueMetadata?.merchantDeleted === true || String(venueMetadata?.merchantDeleted || '').trim().toLowerCase() === 'true') {
                    return res.status(404).json({ message: 'Venue not found' });
                }
                const ownerCandidateIds = extractVenueOwnerCandidateIds(venue);
                const isOwner = Boolean(currentUserId && ownerCandidateIds.includes(String(currentUserId || '').trim()));

                if (!isAdmin && !isOwner) {
                    return res.status(403).json({ message: 'You do not have permission to delete this venue' });
                }

                const hiddenResult = await pool.query(
                    `
                        UPDATE venues
                        SET
                            status = 'hidden',
                            metadata = jsonb_set(
                                jsonb_set(
                                    COALESCE(venues.metadata, '{}'::jsonb),
                                    '{merchantDeleted}',
                                    'true'::jsonb,
                                    true
                                ),
                                '{merchantDeletedAt}',
                                to_jsonb(NOW()::text),
                                true
                            ),
                            updated_at = now()
                        WHERE id = $1
                        RETURNING id
                    `,
                    [venueId]
                );

                if (!hiddenResult.rows.length) {
                    return res.status(404).json({ message: 'Venue not found' });
                }

                try {
                    await pool.query(
                        `
                            UPDATE venue_update_requests
                            SET
                                status = CASE WHEN status = 'pending' THEN 'rejected' ELSE status END,
                                rejection_reason = CASE
                                    WHEN status = 'pending' THEN COALESCE(rejection_reason, 'Deleted by merchant')
                                    ELSE rejection_reason
                                END,
                                reviewed_by = CASE
                                    WHEN status = 'pending' THEN COALESCE($2, 'merchant')
                                    ELSE reviewed_by
                                END,
                                reviewed_at = CASE
                                    WHEN status = 'pending' THEN now()
                                    ELSE reviewed_at
                                END,
                                updated_at = now()
                            WHERE venue_id = $1
                        `,
                        [venueId, currentUserId]
                    );
                } catch (updateRequestError) {
                    if (!isUndefinedTableError(updateRequestError)) {
                        throw updateRequestError;
                    }
                }

                invalidateVenueCommunityBundleCacheByVenueId(venueId);
                publicCompactApprovedVenuesCache = { timestamp: 0, data: null };
                publicVenueDetailCache.delete(`public:${venueId}`);
                publicVenueDetailCache.delete(`admin:${venueId}`);
                publicVenueForDetailCache.delete(`public:${venueId}`);
                publicVenueForDetailCache.delete(`admin:${venueId}`);

                return res.json({
                    message: 'Venue deleted successfully',
                    deletedVenueId: venueId
                });
            } catch (error) {
                return res.status(500).json({ message: error.message });
            }
        }

        async function toggleMerchantVenuePauseStatus(req, res) {
            const venueId = Number(req.params.venueId);

            if (!Number.isFinite(venueId)) {
                return res.status(400).json({ message: 'Invalid venue id' });
            }

            try {
                const currentUserId = await getAuthenticatedChatUserId(req);
                const isAdmin = normalizeRole(req.authUser?.role) === 'admin';

                if (!currentUserId && !isAdmin) {
                    return res.status(401).json({ message: 'Missing authentication token' });
                }

                const venueHasOwnerUserColumn = await hasVenueOwnerUserColumn();
                const resolvedOwnerUserSql = buildResolvedVenueOwnerUserSql('venues');
                const ownerSelect = venueHasOwnerUserColumn
                    ? `${resolvedOwnerUserSql} AS owner_user_id,`
                    : `NULL::uuid AS owner_user_id,`;

                const venueResult = await pool.query(
                    `
                        SELECT
                            venues.id,
                            venues.name,
                            venues.title,
                            ${ownerSelect}
                            venues.submitted_by_user_id,
                            venues.status::text AS status,
                            venues.metadata
                        FROM venues
                        WHERE venues.id = $1
                        LIMIT 1
                    `,
                    [venueId]
                );

                if (!venueResult.rows.length) {
                    return res.status(404).json({ message: 'Venue not found' });
                }

                const venue = venueResult.rows[0];
                const venueMetadata = normalizeVenueMetadataObject(venue?.metadata);
                if (venueMetadata?.merchantDeleted === true || String(venueMetadata?.merchantDeleted || '').trim().toLowerCase() === 'true') {
                    return res.status(404).json({ message: 'Venue not found' });
                }
                const ownerCandidateIds = extractVenueOwnerCandidateIds(venue);
                const isOwner = Boolean(currentUserId && ownerCandidateIds.includes(String(currentUserId || '').trim()));

                if (!isAdmin && !isOwner) {
                    return res.status(403).json({ message: 'You do not have permission to update this venue' });
                }

                const currentStatus = String(venue.status || '').toLowerCase();
                if (!['approved', 'hidden'].includes(currentStatus)) {
                    return res.status(400).json({ message: 'Only approved or paused venues can be toggled' });
                }

                const nextStatus = currentStatus === 'hidden' ? 'approved' : 'hidden';

                const updateResult = await pool.query(
                    `
                        UPDATE venues
                        SET
                            status = $2,
                            updated_at = now()
                        WHERE id = $1
                        RETURNING id, status
                    `,
                    [venueId, nextStatus]
                );

                if (!updateResult.rows.length) {
                    return res.status(404).json({ message: 'Venue not found' });
                }

                invalidateVenueCommunityBundleCacheByVenueId(venueId);
                publicCompactApprovedVenuesCache = { timestamp: 0, data: null };
                publicVenueDetailCache.delete(`public:${venueId}`);
                publicVenueDetailCache.delete(`admin:${venueId}`);
                publicVenueForDetailCache.delete(`public:${venueId}`);
                publicVenueForDetailCache.delete(`admin:${venueId}`);

                const isPaused = nextStatus === 'hidden';

                return res.json({
                    message: isPaused
                        ? 'Venue has been paused and hidden from public pages.'
                        : 'Venue is active again and visible on public pages.',
                    venue: updateResult.rows[0],
                    isPaused,
                });
            } catch (error) {
                return res.status(500).json({ message: error.message });
            }
        }

        async function listAdminVenueUpdateRequests(req, res) {
            try {
                const normalizedStatuses = normalizeVenueUpdateRequestStatusList(req.query.status);
                const statusFilter = normalizedStatuses.length ? normalizedStatuses : ['pending'];

                const result = await pool.query(
                    `
                        SELECT
                            requests.id,
                            requests.venue_id,
                            requests.submitted_by_user_id,
                            requests.old_snapshot,
                            requests.proposed_snapshot,
                            requests.status,
                            requests.rejection_reason,
                            requests.reviewed_by,
                            requests.submitted_at,
                            requests.reviewed_at,
                            requests.created_at,
                            requests.updated_at,
                            submitted_users.email AS submitted_by_email,
                            COALESCE(submitted_users.fullname, submitted_users.username) AS submitted_by_full_name,
                            venues.name AS venue_name,
                            venues.title AS venue_title,
                            venues.address AS venue_address,
                            venues.latitude AS venue_latitude,
                            venues.longitude AS venue_longitude,
                            venues.ward_id AS venue_ward_id,
                            wards.name AS venue_ward_name,
                            venues.category_id AS venue_category_id,
                            place_categories.name AS venue_category_name,
                            venues.status::text AS venue_status
                        FROM venue_update_requests AS requests
                        LEFT JOIN users AS submitted_users ON submitted_users.id::text = requests.submitted_by_user_id
                        LEFT JOIN venues ON venues.id = requests.venue_id
                        LEFT JOIN wards ON wards.ward_id = venues.ward_id
                        LEFT JOIN place_categories ON place_categories.id = venues.category_id
                        WHERE requests.status = ANY($1::text[])
                        ORDER BY COALESCE(requests.submitted_at, requests.created_at) DESC, requests.id DESC
                    `,
                    [statusFilter]
                );

                return res.json(result.rows);
            } catch (error) {
                if (isUndefinedTableError(error)) {
                    return res.json([]);
                }

                return res.status(500).json({ message: error.message });
            }
        }

