        async function checkAdminFeedbackSmtpHealth(req, res) {
            const diagnostics = {
                checkedAt: new Date().toISOString(),
                configured: Boolean(feedbackReplyTransporters.length && feedbackReplySmtpUser),
                smtpUser: maskEmailAddress(feedbackReplySmtpUser),
                fromEmail: feedbackReplyFromEmail || feedbackReplySmtpUser || DEFAULT_FEEDBACK_REPLY_GMAIL
            };

            if (!diagnostics.configured) {
                return res.status(500).json({
                    ok: false,
                    ...diagnostics,
                    message:
                        'SMTP is not configured. Set FEEDBACK_GMAIL_USER and FEEDBACK_GMAIL_APP_PASSWORD, then restart backend.'
                });
            }

            let lastError = null;
            for (const transporter of feedbackReplyTransporters) {
                try {
                    await transporter.verify();
                    return res.json({
                        ok: true,
                        ...diagnostics,
                        message: 'SMTP connection is healthy and ready to send emails.'
                    });
                } catch (error) {
                    lastError = error;
                }
            }

            return res.status(502).json({
                ok: false,
                ...diagnostics,
                errorCode: lastError?.code || null,
                error: lastError?.message || 'SMTP verification failed',
                message:
                    'SMTP authentication failed. Update Gmail App Password (16 chars, no spaces), then restart backend.'
            });
        }

        function replyAdminFeedbackReport(req, res) {
            uploadFeedbackReply.single('attachment')(req, res, async (uploadErr) => {
                if (uploadErr) {
                    return res.status(400).json({ message: uploadErr.message || 'Upload failed' });
                }

                const feedbackId = normalizeNullableNumber(req.params.feedbackId);

                if (Number.isNaN(feedbackId) || feedbackId === null) {
                    return res.status(400).json({ message: 'feedbackId must be a positive integer' });
                }

                const replyMessage = String(req.body.replyMessage || req.body.message || '').trim();

                if (!replyMessage) {
                    if (req.file) {
                        safeDeleteUploadedFile(`/uploads/feedback/admin-replies/${req.file.filename}`);
                    }

                    return res.status(400).json({ message: 'replyMessage is required' });
                }

                const requestedStatus = String(req.body.status || 'replied').trim().toLowerCase();
                const allowedNextStatuses = new Set(['in_progress', 'replied', 'closed']);
                const nextStatus = allowedNextStatuses.has(requestedStatus) ? requestedStatus : 'replied';

                if (!feedbackReplyTransporters.length || !feedbackReplySmtpUser) {
                    if (req.file) {
                        safeDeleteUploadedFile(`/uploads/feedback/admin-replies/${req.file.filename}`);
                    }

                    return res.status(500).json({
                        message:
                            'Gmail configuration is missing. Set FEEDBACK_GMAIL_USER and FEEDBACK_GMAIL_APP_PASSWORD in backend environment.'
                    });
                }

                try {
                    const feedbackResult = await pool.query(
                        `
                            SELECT
                                f.id,
                                f.message,
                                f.created_at,
                                f.contact_email,
                                f.reporter_user_id,
                                reporter.email AS reporter_email,
                                f.admin_reply_attachment_url,
                                COALESCE(ft.name, f.issue_type, f.category, 'Other') AS feedback_type_name
                            FROM feedbacks AS f
                            LEFT JOIN feedback_types AS ft ON ft.id = f.feedback_type_id
                            LEFT JOIN users AS reporter ON reporter.id::text = f.reporter_user_id
                            WHERE f.id = $1
                            LIMIT 1
                        `,
                        [feedbackId]
                    );

                    if (!feedbackResult.rows.length) {
                        if (req.file) {
                            safeDeleteUploadedFile(`/uploads/feedback/admin-replies/${req.file.filename}`);
                        }

                        return res.status(404).json({ message: 'Feedback report not found' });
                    }

                    const feedback = feedbackResult.rows[0];
                    const primaryContactEmail = normalizeNullableText(feedback.contact_email);
                    const reporterEmail = normalizeNullableText(feedback.reporter_email);
                    const recipientEmail = [primaryContactEmail, reporterEmail].find((candidate) =>
                        isValidEmail(candidate)
                    );

                    if (!recipientEmail) {
                        if (req.file) {
                            safeDeleteUploadedFile(`/uploads/feedback/admin-replies/${req.file.filename}`);
                        }

                        return res.status(400).json({
                            message:
                                'This report does not contain a valid recipient email. Please ensure the feedback account uses a real email address.'
                        });
                    }

                    const replyAttachmentUrl = req.file
                        ? `/uploads/feedback/admin-replies/${req.file.filename}`
                        : feedback.admin_reply_attachment_url;

                    const mailFrom = `${feedbackReplyFromName} <${feedbackReplyFromEmail || feedbackReplySmtpUser}>`;
                    const reviewer = req.authUser?.email || req.authUser?.id || 'Support Team';
                    const reviewerLabelForEmail =
                        feedbackReplyFromEmail || feedbackReplySmtpUser || 'smartcity.discovery2026@gmail.com';
                    const reportTypeLabel = escapeHtml(feedback.feedback_type_name || 'Other');
                    const reportCreatedAtLabel = escapeHtml(formatFeedbackTimestamp(feedback.created_at));
                    const nextStatusLabel = escapeHtml(normalizeFeedbackStatusLabel(nextStatus));
                    const reportMessageText = String(feedback.message || '').trim() || 'No report details provided.';
                    const attachmentNoticeText = req.file
                        ? 'An image attachment from our support team is included in this email.'
                        : '';

                    const plainTextBody = [
                        'Smart City Discovery - Feedback Update',
                        '',
                        `Feedback ID: #${feedback.id}`,
                        `Feedback Type: ${feedback.feedback_type_name || 'Other'}`,
                        `Submitted At: ${formatFeedbackTimestamp(feedback.created_at)}`,
                        '',
                        'Original Report:',
                        reportMessageText,
                        '',
                        'Support Team Response:',
                        replyMessage,
                        '',
                        `Current Status: ${normalizeFeedbackStatusLabel(nextStatus)}`,
                        `Handled By: ${reviewerLabelForEmail}`,
                        attachmentNoticeText,
                        '',
                        'If you need further help, please reply to this email.',
                        '',
                        'Best regards,',
                        'Smart City Discovery Support'
                    ]
                        .filter(Boolean)
                        .join('\n');

                    const htmlBody = `
                        <div style="margin:0;padding:0;background:#f4f6fb;font-family:Segoe UI,Arial,sans-serif;color:#1f2937;">
                            <div style="max-width:680px;margin:0 auto;padding:24px 16px;">
                                <div style="background:#ffffff;border:1px solid #e4e8f1;border-radius:14px;overflow:hidden;box-shadow:0 10px 28px rgba(23,33,79,0.08);">
                                    <div style="padding:18px 22px;background:linear-gradient(135deg,#1e3a8a,#2563eb);color:#ffffff;">
                                        <p style="margin:0;font-size:12px;letter-spacing:.08em;text-transform:uppercase;opacity:.88;">Smart City Discovery Support</p>
                                        <h2 style="margin:8px 0 0;font-size:22px;line-height:1.3;">Update on your feedback report #${feedback.id}</h2>
                                    </div>
                                    <div style="padding:20px 22px 24px;">
                                        <p style="margin:0 0 14px;font-size:14px;color:#334155;">Hello,</p>
                                        <p style="margin:0 0 18px;font-size:14px;line-height:1.7;color:#334155;">Thank you for contacting Smart City Discovery. Our support team has reviewed your report and provided an update below.</p>

                                        <div style="margin:0 0 18px;padding:14px;border:1px solid #e4e8f1;border-radius:10px;background:#f8faff;">
                                            <p style="margin:0 0 8px;font-size:13px;color:#475569;"><strong>Feedback ID:</strong> #${feedback.id}</p>
                                            <p style="margin:0 0 8px;font-size:13px;color:#475569;"><strong>Feedback Type:</strong> ${reportTypeLabel}</p>
                                            <p style="margin:0 0 8px;font-size:13px;color:#475569;"><strong>Submitted At:</strong> ${reportCreatedAtLabel}</p>
                                            <p style="margin:0;font-size:13px;color:#475569;"><strong>Current Status:</strong> ${nextStatusLabel}</p>
                                        </div>

                                        <h3 style="margin:0 0 8px;font-size:15px;color:#1e293b;">Original report</h3>
                                        <div style="margin:0 0 18px;padding:12px;border-radius:10px;background:#f9fafb;border:1px solid #eceff5;font-size:14px;line-height:1.65;color:#334155;">${formatMultilineHtml(reportMessageText)}</div>

                                        <h3 style="margin:0 0 8px;font-size:15px;color:#1e293b;">Support team response</h3>
                                        <div style="margin:0 0 8px;padding:12px;border-radius:10px;background:#eff6ff;border:1px solid #dbeafe;font-size:14px;line-height:1.65;color:#1e3a8a;">${formatMultilineHtml(replyMessage)}</div>
                                        <p style="margin:0 0 18px;font-size:12px;color:#64748b;"><strong>Handled by:</strong> ${escapeHtml(reviewerLabelForEmail)}</p>

                                        ${req.file ? '<p style="margin:0 0 18px;font-size:13px;color:#0f766e;">An image attachment from our support team is included in this email.</p>' : ''}

                                        <div style="margin:0;padding:14px;border-radius:10px;background:#f8fafc;border:1px dashed #d3dae8;">
                                            <p style="margin:0;font-size:13px;line-height:1.6;color:#475569;">If you need further assistance, please reply directly to this email and we will continue supporting your request.</p>
                                        </div>

                                        <p style="margin:18px 0 0;font-size:13px;color:#64748b;">Best regards,<br /><strong>Smart City Discovery Support</strong></p>
                                    </div>
                                </div>
                            </div>
                        </div>
                    `;

                    let mailResult = null;
                    let emailSent = false;
                    let emailErrorCode = '';

                    try {
                        mailResult = await sendFeedbackReplyEmail({
                            from: mailFrom,
                            to: recipientEmail,
                            subject: `[Smart City Discovery] Update on your feedback #${feedback.id}`,
                            text: plainTextBody,
                            html: htmlBody,
                            attachments: req.file
                                ? [
                                    {
                                        filename: req.file.originalname,
                                        path: req.file.path,
                                        contentType: req.file.mimetype
                                    }
                                ]
                                : []
                        });
                        emailSent = true;
                    } catch (mailError) {
                        emailErrorCode = String(mailError?.code || '').trim();

                        if (mailError?.code !== 'EAUTH' && mailError?.responseCode !== 535) {
                            if (mailError?.code === 'EENVELOPE') {
                                if (req.file) {
                                    safeDeleteUploadedFile(`/uploads/feedback/admin-replies/${req.file.filename}`);
                                }

                                return res.status(400).json({
                                    message: 'Recipient email is invalid or rejected by SMTP provider.'
                                });
                            }

                            throw mailError;
                        }
                    }

                    const updateResult = await pool.query(
                        `
                            UPDATE feedbacks
                            SET
                                admin_reply_message = $2,
                                admin_reply_attachment_url = $3,
                                admin_replied_at = now(),
                                admin_replied_by = $4,
                                status = $5,
                                updated_at = now()
                            WHERE id = $1
                            RETURNING id, status, admin_reply_message, admin_reply_attachment_url, admin_replied_at, admin_replied_by, updated_at
                        `,
                        [feedbackId, replyMessage, replyAttachmentUrl, reviewer, nextStatus]
                    );

                    const reporterUserId = String(feedback.reporter_user_id || '').trim();
                    if (reporterUserId) {
                        await createUserNotification({
                            userId: reporterUserId,
                            type: 'feedback',
                            title: 'Báo cáo của bạn đã có phản hồi từ quản trị viên',
                            content: `Báo cáo #${feedback.id} đã được cập nhật trạng thái ${normalizeFeedbackStatusLabel(nextStatus)}.`,
                            metadata: {
                                feedbackId: feedback.id,
                                nextStatus,
                                hasAttachment: Boolean(replyAttachmentUrl)
                            }
                        });
                    }

                    if (
                        req.file &&
                        feedback.admin_reply_attachment_url &&
                        feedback.admin_reply_attachment_url !== replyAttachmentUrl
                    ) {
                        safeDeleteUploadedFile(feedback.admin_reply_attachment_url);
                    }

                    return res.json({
                        message: emailSent
                            ? 'Reply sent successfully via Gmail'
                            : 'Reply saved successfully, but email delivery failed due Gmail authentication.',
                        deliveredTo: recipientEmail,
                        messageId: mailResult?.messageId || null,
                        emailSent,
                        emailErrorCode: emailSent ? null : emailErrorCode || 'EAUTH',
                        feedback: updateResult.rows[0]
                    });
                } catch (error) {
                    if (req.file) {
                        safeDeleteUploadedFile(`/uploads/feedback/admin-replies/${req.file.filename}`);
                    }

                    if (isFeedbackSchemaMissingError(error)) {
                        return res.status(500).json({
                            message: 'Feedback management schema is missing. Please run backend migrations.'
                        });
                    }

                    if (error?.code === 'EAUTH' || error?.responseCode === 535) {
                        return res.status(500).json({
                            message:
                                'Gmail authentication failed. Please re-check FEEDBACK_GMAIL_USER and FEEDBACK_GMAIL_APP_PASSWORD.'
                        });
                    }

                    if (error?.code === 'EENVELOPE') {
                        return res.status(400).json({
                            message: 'Recipient email is invalid or rejected by SMTP provider.'
                        });
                    }

                    return res.status(500).json({ message: error.message });
                }
            });
        }

        async function deleteAdminFeedbackReport(req, res) {
            const feedbackId = normalizeNullableNumber(req.params.feedbackId);
            const shouldDeleteTarget = String(req.query.deleteTarget || '').trim().toLowerCase() === 'true';

            if (Number.isNaN(feedbackId) || feedbackId === null) {
                return res.status(400).json({ message: 'feedbackId must be a positive integer' });
            }

            const parsePositiveInteger = (value) => {
                const normalized = Number(String(value ?? '').trim());
                if (!Number.isFinite(normalized) || normalized <= 0) {
                    return null;
                }

                return Math.trunc(normalized);
            };

            const parseFeedbackMetadataMap = (rawMessage) => {
                const text = String(rawMessage || '');
                const metadataSectionMatch = text.match(/\[metadata\]([\s\S]*?)(?:\n\n|$)/i);
                if (!metadataSectionMatch) {
                    return {};
                }

                const lines = String(metadataSectionMatch[1] || '').split(/\r?\n/);

                return lines.reduce((accumulator, line) => {
                    const pair = String(line || '').match(/^\s*([a-zA-Z0-9_]+)\s*:\s*(.+?)\s*$/);
                    if (!pair) {
                        return accumulator;
                    }

                    const key = String(pair[1] || '').trim().toLowerCase();
                    const value = String(pair[2] || '').trim();
                    if (key && value) {
                        accumulator[key] = value;
                    }

                    return accumulator;
                }, {});
            };

            try {
                const client = await pool.connect();

                try {
                    await client.query('BEGIN');

                    const feedbackResult = await client.query(
                        `
                            SELECT
                                f.id,
                                f.message,
                                f.attachment_url,
                                f.admin_reply_attachment_url,
                                f.reporter_user_id,
                                COALESCE(ft.code, f.category, f.issue_type, 'other') AS feedback_type_code
                            FROM feedbacks AS f
                            LEFT JOIN feedback_types AS ft ON ft.id = f.feedback_type_id
                            WHERE f.id = $1
                            LIMIT 1
                        `,
                        [feedbackId]
                    );

                    if (!feedbackResult.rows.length) {
                        await client.query('ROLLBACK');
                        return res.status(404).json({ message: 'Feedback report not found' });
                    }

                    const report = feedbackResult.rows[0];
                    const reportTypeCode = String(report.feedback_type_code || '').trim().toLowerCase();
                    const metadataMap = parseFeedbackMetadataMap(report.message);
                    const reporterUserId = String(report.reporter_user_id || '').trim();

                    let deletedTarget = false;
                    let deletedTargetId = null;
                    let deletedTargetType = '';

                    if (shouldDeleteTarget && reportTypeCode === 'review_report') {
                        const inferredReviewId =
                            parsePositiveInteger(metadataMap.contextid)
                            || parsePositiveInteger(metadataMap.reviewid)
                            || parsePositiveInteger(String(report.message || '').match(/bình\s*luận\s*#(\d+)/i)?.[1]);

                        const inferredVenueId = parsePositiveInteger(metadataMap.venueid);

                        if (inferredReviewId) {
                            const reviewDeleteResult = inferredVenueId
                                ? await client.query(
                                    `
                                        DELETE FROM venue_public_reviews
                                        WHERE id = $1 AND venue_id = $2
                                        RETURNING id, venue_id
                                    `,
                                    [inferredReviewId, inferredVenueId]
                                )
                                : await client.query(
                                    `
                                        DELETE FROM venue_public_reviews
                                        WHERE id = $1
                                        RETURNING id, venue_id
                                    `,
                                    [inferredReviewId]
                                );

                            if (reviewDeleteResult.rows.length) {
                                deletedTarget = true;
                                deletedTargetType = 'review';
                                deletedTargetId = reviewDeleteResult.rows[0].id;
                                invalidateVenueCommunityBundleCacheByVenueId(reviewDeleteResult.rows[0].venue_id);
                            }
                        }
                    }

                    if (shouldDeleteTarget && reportTypeCode === 'venue_report') {
                        const inferredVenueId =
                            parsePositiveInteger(metadataMap.venueid)
                            || parsePositiveInteger(metadataMap.contextid)
                            || parsePositiveInteger(String(report.message || '').match(/venue\s*#(\d+)/i)?.[1]);

                        if (inferredVenueId) {
                            const venueDeleteResult = await client.query(
                                `
                                    DELETE FROM venues
                                    WHERE id = $1
                                    RETURNING id
                                `,
                                [inferredVenueId]
                            );

                            if (venueDeleteResult.rows.length) {
                                deletedTarget = true;
                                deletedTargetType = 'venue';
                                deletedTargetId = venueDeleteResult.rows[0].id;
                                invalidateVenueCommunityBundleCacheByVenueId(venueDeleteResult.rows[0].id);
                            }
                        }
                    }

                    const deleteResult = await client.query(
                        `
                            DELETE FROM feedbacks
                            WHERE id = $1
                            RETURNING id, attachment_url, admin_reply_attachment_url
                        `,
                        [feedbackId]
                    );

                    await client.query('COMMIT');

                    const deletedReport = deleteResult.rows[0];

                    safeDeleteUploadedFile(deletedReport.attachment_url);
                    safeDeleteUploadedFile(deletedReport.admin_reply_attachment_url);

                    if (reporterUserId) {
                        await createUserNotification({
                            userId: reporterUserId,
                            type: 'feedback',
                            title: deletedTarget
                                ? 'Báo cáo của bạn đã được xử lý'
                                : 'Báo cáo của bạn đã được tiếp nhận và đóng',
                            content: deletedTarget
                                ? `Quản trị viên đã xử lý báo cáo #${deletedReport.id} và áp dụng hành động với nội dung bị báo cáo.`
                                : `Quản trị viên đã xử lý báo cáo #${deletedReport.id}.`,
                            metadata: {
                                feedbackId: deletedReport.id,
                                reportTypeCode,
                                deletedTarget,
                                deletedTargetType,
                                deletedTargetId
                            }
                        });
                    }

                    return res.json({
                        message: deletedTarget
                            ? 'Feedback report and reported target deleted successfully'
                            : 'Feedback report deleted successfully',
                        deletedFeedbackId: deletedReport.id,
                        deletedTarget,
                        deletedTargetType,
                        deletedTargetId
                    });
                } catch (error) {
                    await client.query('ROLLBACK');
                    throw error;
                } finally {
                    client.release();
                }
            } catch (error) {
                if (isFeedbackSchemaMissingError(error)) {
                    return res.status(500).json({
                        message: 'Feedback management schema is missing. Please run backend migrations.'
                    });
                }

                return res.status(500).json({ message: error.message });
            }
        }

        async function getAuthenticatedChatUserId(req) {
            const rawUserId = req.authUser?.id ?? req.user?.id ?? null;
            const normalizedUserId = rawUserId === null || rawUserId === undefined ? '' : String(rawUserId).trim();

            if (normalizedUserId) {
                return normalizedUserId;
            }

            const authEmail = String(req.authUser?.email || req.user?.email || '').trim().toLowerCase();
            if (!authEmail) {
                return null;
            }

            try {
                const userResult = await pool.query(
                    `
                        SELECT id
                        FROM users
                        WHERE LOWER(email) = $1
                        LIMIT 1
                    `,
                    [authEmail]
                );

                const fallbackUserId = String(userResult.rows[0]?.id || '').trim();
                return fallbackUserId || null;
            } catch {
                return null;
            }
        }

        async function getVenueChatOwnerContext(venueId) {
            const venueHasOwnerUserColumn = await hasVenueOwnerUserColumn();
            const resolvedOwnerUserSql = buildResolvedVenueOwnerUserSql('venues');
            const ownerSelect = venueHasOwnerUserColumn
                ? `
                        ${resolvedOwnerUserSql} AS owner_user_id,
                        owner_users.fullname AS owner_name,
                    `
                : `
                        NULL::uuid AS owner_user_id,
                        NULL::text AS owner_name,
                    `;
            const ownerJoin = venueHasOwnerUserColumn
                ? `LEFT JOIN users AS owner_users ON owner_users.id = ${resolvedOwnerUserSql}`
                : '';
            const result = await pool.query(
                `
                    SELECT
                        venues.id,
                        venues.name,
                        venues.title,
                        venues.address,
                        venues.cover_image_url,
                        venues.phone,
                        venues.metadata,
                        ${ownerSelect}
                        wards.name AS ward_name
                    FROM venues
                    ${ownerJoin}
                    LEFT JOIN wards ON wards.ward_id = venues.ward_id
                    WHERE venues.id = $1
                    LIMIT 1
                `,
                [venueId]
            );

            return result.rows[0] || null;
        }

        async function listOwnerChatVenues(ownerUserId) {
            const normalizedOwnerUserId = String(ownerUserId || '').trim();
            if (!normalizedOwnerUserId) {
                return [];
            }

            const result = await pool.query(
                `
                    SELECT
                        venues.id,
                        venues.name,
                        venues.title,
                        venues.address,
                        venues.cover_image_url,
                        wards.name AS ward_name
                    FROM venues
                    LEFT JOIN wards ON wards.ward_id = venues.ward_id
                    WHERE ${buildResolvedVenueOwnerUserSql('venues')} = $1
                    ORDER BY LOWER(COALESCE(venues.name, venues.title, '')) ASC, venues.id ASC
                `,
                [normalizedOwnerUserId]
            );

            return result.rows.map((row) => ({
                id: row.id,
                name: row.name || row.title || 'Quán chưa đặt tên',
                address: row.address || '',
                coverImageUrl: row.cover_image_url || '',
                wardName: row.ward_name || ''
            }));
        }

        async function findOrCreateChatThread(ownerUserId, customerUserId) {
            const result = await pool.query(
                `
                    INSERT INTO chat_threads (owner_user_id, customer_user_id, created_at, updated_at)
                    VALUES ($1, $2, NOW(), NOW())
                    ON CONFLICT (owner_user_id, customer_user_id)
                    DO UPDATE SET updated_at = NOW()
                    RETURNING id, owner_user_id, customer_user_id, created_at, updated_at, last_message_at
                `,
                [ownerUserId, customerUserId]
            );

            return result.rows[0] || null;
        }

        async function buildChatThreadPayload(threadId, currentUserId) {
            const threadResult = await pool.query(
                `
                    SELECT
                        t.id,
                        t.owner_user_id,
                        t.customer_user_id,
                        t.created_at,
                        t.updated_at,
                        t.last_message_at,
                        owner_user.fullname AS owner_name,
                        owner_user.username AS owner_username,
                        customer_user.fullname AS customer_name,
                        customer_user.username AS customer_username,
                        COALESCE(unread.unread_count, 0)::int AS unread_count
                    FROM chat_threads AS t
                    JOIN users AS owner_user ON owner_user.id = t.owner_user_id
                    JOIN users AS customer_user ON customer_user.id = t.customer_user_id
                    LEFT JOIN LATERAL (
                        SELECT COUNT(*)::int AS unread_count
                        FROM chat_messages AS m
                        LEFT JOIN chat_thread_reads AS r
                          ON r.thread_id = t.id
                         AND r.user_id = $2
                        WHERE m.thread_id = t.id
                          AND m.recipient_user_id = $2
                          AND (r.last_read_at IS NULL OR m.created_at > r.last_read_at)
                    ) AS unread ON TRUE
                    LEFT JOIN chat_thread_hidden AS hidden
                      ON hidden.thread_id = t.id
                     AND hidden.user_id = $2
                    WHERE t.id = $1
                      AND ($2 = t.owner_user_id OR $2 = t.customer_user_id)
                      AND (
                        hidden.hidden_at IS NULL
                        OR COALESCE(t.last_message_at, t.updated_at, t.created_at) > hidden.hidden_at
                      )
                    LIMIT 1
                `,
                [threadId, currentUserId]
            );

            if (!threadResult.rows.length) {
                return null;
            }

            const thread = threadResult.rows[0];
            const messagesResult = await pool.query(
                `
                    SELECT
                        m.id,
                        m.thread_id,
                        m.sender_user_id,
                        m.recipient_user_id,
                        m.venue_id,
                        m.context_label,
                        m.content,
                        m.created_at,
                        m.updated_at,
                        sender_user.fullname AS sender_name,
                        recipient_user.fullname AS recipient_name,
                        venues.name AS venue_name,
                        venues.title AS venue_title,
                        venues.address AS venue_address,
                        venues.cover_image_url AS venue_image,
                        wards.name AS venue_ward_name
                    FROM chat_messages AS m
                    JOIN users AS sender_user ON sender_user.id = m.sender_user_id
                    JOIN users AS recipient_user ON recipient_user.id = m.recipient_user_id
                    LEFT JOIN venues ON venues.id = m.venue_id
                    LEFT JOIN wards ON wards.ward_id = venues.ward_id
                    WHERE m.thread_id = $1
                    ORDER BY m.created_at ASC, m.id ASC
                `,
                [threadId]
            );

            return {
                id: thread.id,
                ownerUserId: thread.owner_user_id,
                customerUserId: thread.customer_user_id,
                ownerName: thread.owner_name || thread.owner_username || 'Chủ quán',
                customerName: thread.customer_name || thread.customer_username || 'Khách hàng',
                unreadCount: Number(thread.unread_count || 0),
                lastMessageAt: thread.last_message_at || null,
                createdAt: thread.created_at,
                updatedAt: thread.updated_at,
                messages: messagesResult.rows.map((message) => ({
                    id: message.id,
                    threadId: message.thread_id,
                    senderUserId: message.sender_user_id,
                    recipientUserId: message.recipient_user_id,
                    venueId: message.venue_id,
                    contextLabel: message.context_label || '',
                    senderName: message.sender_name || 'Người dùng',
                    recipientName: message.recipient_name || 'Người dùng',
                    content: message.content || '',
                    createdAt: message.created_at,
                    updatedAt: message.updated_at,
                    venueName: message.venue_name || message.venue_title || '',
                    venueAddress: message.venue_address || '',
                    venueImage: message.venue_image || '',
                    venueWardName: message.venue_ward_name || ''
                }))
            };
        }

        async function listChatThreads(req, res) {
            const currentUserId = await getAuthenticatedChatUserId(req);

            if (!currentUserId) {
                return res.status(401).json({ message: 'Bạn cần đăng nhập để xem tin nhắn.' });
            }

            const limit = Math.min(20, Math.max(1, Number(req.query.limit || 10)));

            try {
                const result = await pool.query(
                    `
                        SELECT
                            t.id,
                            t.owner_user_id,
                            t.customer_user_id,
                            t.created_at,
                            t.updated_at,
                            t.last_message_at,
                            owner_user.fullname AS owner_name,
                            owner_user.username AS owner_username,
                            customer_user.fullname AS customer_name,
                            customer_user.username AS customer_username,
                            latest_message.id AS last_message_id,
                            latest_message.content AS last_message_content,
                            latest_message.created_at AS last_message_created_at,
                            latest_message.venue_id AS last_message_venue_id,
                            venues.name AS venue_name,
                            venues.title AS venue_title,
                            venues.address AS venue_address,
                            venues.cover_image_url AS venue_image,
                            wards.name AS venue_ward_name,
                            fallback_venue.id AS fallback_venue_id,
                            fallback_venue.name AS fallback_venue_name,
                            fallback_venue.title AS fallback_venue_title,
                            fallback_venue.address AS fallback_venue_address,
                            fallback_venue.cover_image_url AS fallback_venue_image,
                            fallback_venue.ward_name AS fallback_venue_ward_name,
                            COALESCE(unread.unread_count, 0)::int AS unread_count
                        FROM chat_threads AS t
                        JOIN users AS owner_user ON owner_user.id = t.owner_user_id
                        JOIN users AS customer_user ON customer_user.id = t.customer_user_id
                        LEFT JOIN LATERAL (
                            SELECT m.id, m.content, m.created_at, m.venue_id
                            FROM chat_messages AS m
                            WHERE m.thread_id = t.id
                            ORDER BY m.created_at DESC, m.id DESC
                            LIMIT 1
                        ) AS latest_message ON TRUE
                        LEFT JOIN venues ON venues.id = latest_message.venue_id
                        LEFT JOIN wards ON wards.ward_id = venues.ward_id
                        LEFT JOIN LATERAL (
                            SELECT
                                owner_venues.id,
                                owner_venues.name,
                                owner_venues.title,
                                owner_venues.address,
                                owner_venues.cover_image_url,
                                owner_wards.name AS ward_name
                            FROM venues AS owner_venues
                            LEFT JOIN wards AS owner_wards ON owner_wards.ward_id = owner_venues.ward_id
                            WHERE ${buildResolvedVenueOwnerUserSql('owner_venues')} = t.owner_user_id
                            ORDER BY owner_venues.id ASC
                            LIMIT 1
                        ) AS fallback_venue ON TRUE
                        LEFT JOIN chat_thread_hidden AS hidden
                          ON hidden.thread_id = t.id
                         AND hidden.user_id = $1
                        LEFT JOIN LATERAL (
                            SELECT COUNT(*)::int AS unread_count
                            FROM chat_messages AS m
                            LEFT JOIN chat_thread_reads AS r
                              ON r.thread_id = t.id
                             AND r.user_id = $1
                            WHERE m.thread_id = t.id
                              AND m.recipient_user_id = $1
                              AND (r.last_read_at IS NULL OR m.created_at > r.last_read_at)
                        ) AS unread ON TRUE
                        WHERE t.owner_user_id = $1 OR t.customer_user_id = $1
                          AND (
                            hidden.hidden_at IS NULL
                            OR COALESCE(latest_message.created_at, t.last_message_at, t.updated_at, t.created_at) > hidden.hidden_at
                          )
                        ORDER BY COALESCE(t.last_message_at, t.updated_at, t.created_at) DESC
                        LIMIT $2
                    `,
                    [currentUserId, limit]
                );

                return res.json({
                    threads: result.rows.map((row) => ({
                        id: row.id,
                        ownerUserId: row.owner_user_id,
                        customerUserId: row.customer_user_id,
                        ownerName: row.owner_name || row.owner_username || 'Chủ quán',
                        customerName: row.customer_name || row.customer_username || 'Khách hàng',
                        counterpartName:
                            currentUserId === String(row.owner_user_id || '')
                                ? row.customer_name || row.customer_username || 'Khách hàng'
                                : row.owner_name || row.owner_username || 'Chủ quán',
                        unreadCount: Number(row.unread_count || 0),
                        lastMessage: row.last_message_id
                            ? {
                                  id: row.last_message_id,
                                  content: row.last_message_content || '',
                                  createdAt: row.last_message_created_at,
                                  venueId: row.last_message_venue_id
                              }
                            : null,
                        venueId: row.last_message_venue_id || row.fallback_venue_id || null,
                        venueName: row.venue_name || row.venue_title || row.fallback_venue_name || row.fallback_venue_title || '',
                        venueAddress: row.venue_address || row.fallback_venue_address || '',
                        venueImage: row.venue_image || row.fallback_venue_image || '',
                        venueWardName: row.venue_ward_name || row.fallback_venue_ward_name || ''
                    }))
                });
            } catch (error) {
                return res.status(500).json({ message: error.message });
            }
        }

        async function getVenueChatThread(req, res) {
            const currentUserId = await getAuthenticatedChatUserId(req);
            const venueId = Number(req.params.venueId);
            const selectedThreadId = Number(req.query.threadId || '');

            if (!currentUserId) {
                return res.status(401).json({ message: 'Bạn cần đăng nhập để xem tin nhắn.' });
            }

            if (!Number.isFinite(venueId)) {
                return res.status(400).json({ message: 'Invalid venue id' });
            }

            try {
                const venue = await getVenueChatOwnerContext(venueId);

                if (!venue) {
                    return res.status(404).json({ message: 'Venue not found' });
                }

                let threadId = null;
                const ownerUserId = String(venue.owner_user_id || '').trim();

                if (ownerUserId && currentUserId === ownerUserId && Number.isFinite(selectedThreadId) && selectedThreadId > 0) {
                    threadId = selectedThreadId;
                } else if (ownerUserId && currentUserId !== ownerUserId) {
                    const existingThreadResult = await pool.query(
                        `
                            SELECT id
                            FROM chat_threads
                            WHERE owner_user_id = $1
                              AND customer_user_id = $2
                            LIMIT 1
                        `,
                        [ownerUserId, currentUserId]
                    );

                    threadId = existingThreadResult.rows[0]?.id || null;
                }

                const thread = threadId ? await buildChatThreadPayload(threadId, currentUserId) : null;
                const contextOptions = ownerUserId ? await listOwnerChatVenues(ownerUserId) : [];

                return res.json({
                    venueContext: {
                        id: venue.id,
                        ownerUserId: venue.owner_user_id,
                        ownerName: venue.owner_name || 'Chủ quán',
                        name: venue.name || venue.title || 'Quán chưa đặt tên',
                        address: venue.address || '',
                        coverImageUrl: venue.cover_image_url || '',
                        wardName: venue.ward_name || '',
                        phone: venue.phone || '',
                        metadata: venue.metadata || {}
                    },
                    contextOptions,
                    thread
                });
            } catch (error) {
                return res.status(500).json({ message: error.message });
            }
        }

        async function sendVenueChatMessage(req, res) {
            const currentUserId = await getAuthenticatedChatUserId(req);
            const venueId = Number(req.params.venueId);
            const threadId = Number(req.body.threadId || '');
            const content = String(req.body.content || '').trim();
            const requestedContextVenueId = Number(req.body.contextVenueId || '');
            const requestedContextLabel = String(req.body.contextLabel || '').trim();

            if (!currentUserId) {
                return res.status(401).json({ message: 'Bạn cần đăng nhập để nhắn tin.' });
            }

            if (!Number.isFinite(venueId)) {
                return res.status(400).json({ message: 'Invalid venue id' });
            }

            if (!content) {
                return res.status(400).json({ message: 'Nội dung tin nhắn không được để trống.' });
            }

            try {
                const venue = await getVenueChatOwnerContext(venueId);

                if (!venue) {
                    return res.status(404).json({ message: 'Venue not found' });
                }

                const ownerUserId = String(venue.owner_user_id || '').trim();

                if (!ownerUserId) {
                    return res.status(400).json({ message: 'Quán này chưa được gắn chủ sở hữu để sử dụng chat.' });
                }

                let resolvedThreadId = null;
                let recipientUserId = null;

                if (currentUserId === ownerUserId) {
                    if (!Number.isFinite(threadId) || threadId <= 0) {
                        return res.status(400).json({ message: 'Chủ quán cần chọn đúng cuộc trò chuyện để trả lời.' });
                    }

                    const threadResult = await pool.query(
                        `
                            SELECT id, customer_user_id
                            FROM chat_threads
                            WHERE id = $1
                              AND owner_user_id = $2
                            LIMIT 1
                        `,
                        [threadId, currentUserId]
                    );

                    if (!threadResult.rows.length) {
                        return res.status(404).json({ message: 'Không tìm thấy cuộc trò chuyện.' });
                    }

                    resolvedThreadId = threadResult.rows[0].id;
                    recipientUserId = String(threadResult.rows[0].customer_user_id || '').trim();
                } else {
                    const thread = await findOrCreateChatThread(ownerUserId, currentUserId);
                    resolvedThreadId = thread?.id || null;
                    recipientUserId = ownerUserId;
                }

                if (!resolvedThreadId || !recipientUserId) {
                    return res.status(400).json({ message: 'Không thể xác định người nhận tin nhắn.' });
                }

                const customerUserId = currentUserId === ownerUserId ? recipientUserId : currentUserId;
                let messageVenueId = venueId;
                let messageContextLabel = venue.name || venue.title || '';

                if (requestedContextLabel.toLowerCase() === 'other') {
                    messageVenueId = null;
                    messageContextLabel = 'Other';
                } else if (Number.isFinite(requestedContextVenueId) && requestedContextVenueId > 0) {
                    const selectedVenueContext = await getVenueChatOwnerContext(requestedContextVenueId);
                    const selectedVenueOwnerUserId = String(selectedVenueContext?.owner_user_id || '').trim();

                    if (!selectedVenueContext || selectedVenueOwnerUserId !== ownerUserId) {
                        return res.status(400).json({ message: 'QuÃ¡n Ä‘Æ°á»£c chá»n khÃ´ng há»£p lá»‡ cho Ä‘oáº¡n chat nÃ y.' });
                    }

                    messageVenueId = requestedContextVenueId;
                    messageContextLabel = selectedVenueContext.name || selectedVenueContext.title || '';
                }

                const insertMessageResult = await pool.query(
                    `
                        INSERT INTO chat_messages (
                            thread_id,
                            sender_user_id,
                            recipient_user_id,
                            venue_id,
                            context_label,
                            content,
                            created_at,
                            updated_at
                        )
                        VALUES ($1, $2, $3, $4, $5, $6, NOW(), NOW())
                        RETURNING id, created_at
                    `,
                    [resolvedThreadId, currentUserId, recipientUserId, messageVenueId, messageContextLabel, content]
                );

                await pool.query(
                    `
                        DELETE FROM chat_thread_hidden
                        WHERE thread_id IN (
                            SELECT id
                            FROM chat_threads
                            WHERE owner_user_id = $1
                              AND customer_user_id = $2
                        )
                          AND user_id IN ($1, $2)
                    `,
                    [ownerUserId, customerUserId]
                );

                await pool.query(
                    `
                        UPDATE chat_threads
                        SET updated_at = NOW(),
                            last_message_at = $2
                        WHERE id = $1
                    `,
                    [resolvedThreadId, insertMessageResult.rows[0]?.created_at || new Date().toISOString()]
                );

                if (recipientUserId && recipientUserId !== currentUserId) {
                    const senderDisplayName = String(
                        req.authUser?.fullname
                        || req.authUser?.username
                        || req.authUser?.email
                        || 'Người dùng'
                    ).trim();
                    const venueLabel = String(
                        venue.name
                        || venue.title
                        || messageContextLabel
                        || 'quán'
                    ).trim();

                    await createUserNotification({
                        userId: recipientUserId,
                        type: 'general',
                        title: 'Bạn có tin nhắn mới',
                        content: `${senderDisplayName} vừa gửi tin nhắn về ${venueLabel}.`,
                        metadata: {
                            threadId: resolvedThreadId,
                            venueId: messageVenueId || venueId,
                            contextLabel: messageContextLabel || null,
                            senderUserId: currentUserId
                        }
                    });
                }

                const threadPayload = await buildChatThreadPayload(resolvedThreadId, currentUserId);
                return res.status(201).json({
                    message: 'Chat message sent successfully',
                    thread: threadPayload
                });
            } catch (error) {
                return res.status(500).json({ message: error.message });
            }
        }

        async function markChatThreadRead(req, res) {
            const currentUserId = await getAuthenticatedChatUserId(req);
            const threadId = Number(req.params.threadId);

            if (!currentUserId) {
                return res.status(401).json({ message: 'Bạn cần đăng nhập để đọc tin nhắn.' });
            }

            if (!Number.isFinite(threadId)) {
                return res.status(400).json({ message: 'Invalid thread id' });
            }

            try {
                const participantCheck = await pool.query(
                    `
                        SELECT id, owner_user_id, customer_user_id
                        FROM chat_threads
                        WHERE id = $1
                          AND ($2 = owner_user_id OR $2 = customer_user_id)
                        LIMIT 1
                    `,
                    [threadId, currentUserId]
                );

                if (!participantCheck.rows.length) {
                    return res.status(404).json({ message: 'Không tìm thấy cuộc trò chuyện.' });
                }

                const ownerUserId = String(participantCheck.rows[0].owner_user_id || '').trim();
                const customerUserId = String(participantCheck.rows[0].customer_user_id || '').trim();

                const relatedThreadsResult = await pool.query(
                    `
                        SELECT id
                        FROM chat_threads
                        WHERE owner_user_id = $1
                          AND customer_user_id = $2
                        ORDER BY id ASC
                    `,
                    [ownerUserId, customerUserId]
                );

                const threadIds = relatedThreadsResult.rows.map((row) => Number(row.id)).filter((value) => Number.isFinite(value));

                if (threadIds.length) {
                    await pool.query(
                        `
                            WITH related_threads AS (
                                SELECT UNNEST($1::bigint[]) AS thread_id
                            ),
                            latest_messages AS (
                                SELECT
                                    rt.thread_id,
                                    latest_message.id AS last_read_message_id,
                                    COALESCE(latest_message.created_at, NOW()) AS last_read_at
                                FROM related_threads AS rt
                                LEFT JOIN LATERAL (
                                    SELECT m.id, m.created_at
                                    FROM chat_messages AS m
                                    WHERE m.thread_id = rt.thread_id
                                      AND m.recipient_user_id = $2
                                    ORDER BY m.created_at DESC, m.id DESC
                                    LIMIT 1
                                ) AS latest_message ON TRUE
                            )
                            INSERT INTO chat_thread_reads (thread_id, user_id, last_read_message_id, last_read_at, updated_at)
                            SELECT
                                latest_messages.thread_id,
                                $2,
                                latest_messages.last_read_message_id,
                                latest_messages.last_read_at,
                                NOW()
                            FROM latest_messages
                            ON CONFLICT (thread_id, user_id)
                            DO UPDATE
                            SET last_read_message_id = EXCLUDED.last_read_message_id,
                                last_read_at = EXCLUDED.last_read_at,
                                updated_at = NOW()
                        `,
                        [threadIds, currentUserId]
                    );
                }

                return res.json({ message: 'Chat thread marked as read', threadId, threadIds });
            } catch (error) {
                return res.status(500).json({ message: error.message });
            }
        }

        async function deleteChatThread(req, res) {
            const currentUserId = await getAuthenticatedChatUserId(req);
            const threadId = Number(req.params.threadId);

            if (!currentUserId) {
                return res.status(401).json({ message: 'Báº¡n cáº§n Ä‘Äƒng nháº­p Ä‘á»ƒ xÃ³a tin nháº¯n.' });
            }

            if (!Number.isFinite(threadId)) {
                return res.status(400).json({ message: 'Invalid thread id' });
            }

            try {
                const participantCheck = await pool.query(
                    `
                        SELECT id, owner_user_id, customer_user_id
                        FROM chat_threads
                        WHERE id = $1
                          AND ($2 = owner_user_id OR $2 = customer_user_id)
                        LIMIT 1
                    `,
                    [threadId, currentUserId]
                );

                if (!participantCheck.rows.length) {
                    return res.status(404).json({ message: 'KhÃ´ng tÃ¬m tháº¥y cuá»™c trÃ² chuyá»‡n.' });
                }

                const ownerUserId = String(participantCheck.rows[0].owner_user_id || '').trim();
                const customerUserId = String(participantCheck.rows[0].customer_user_id || '').trim();

                const relatedThreadsResult = await pool.query(
                    `
                        SELECT id
                        FROM chat_threads
                        WHERE owner_user_id = $1
                          AND customer_user_id = $2
                        ORDER BY id ASC
                    `,
                    [ownerUserId, customerUserId]
                );

                const relatedThreadIds = relatedThreadsResult.rows.map((row) => Number(row.id)).filter((value) => Number.isFinite(value));

                if (relatedThreadIds.length) {
                    await pool.query(
                        `
                            INSERT INTO chat_thread_hidden (thread_id, user_id, hidden_at, updated_at)
                            SELECT thread_id, $2, NOW(), NOW()
                            FROM UNNEST($1::bigint[]) AS hidden_threads(thread_id)
                            ON CONFLICT (thread_id, user_id)
                            DO UPDATE
                            SET hidden_at = EXCLUDED.hidden_at,
                                updated_at = NOW()
                        `,
                        [relatedThreadIds, currentUserId]
                    );
                }

                return res.json({
                    message: 'Chat thread hidden',
                    threadId,
                    deletedThreadIds: relatedThreadIds
                });
            } catch (error) {
                return res.status(500).json({ message: error.message });
            }
        }

        registerVersionedRoute('get', '/chat/threads', authenticateRequest, checkUserStatus, listChatThreads);
        registerVersionedRoute('get', '/chat/venues/:venueId', authenticateRequest, checkUserStatus, getVenueChatThread);
        registerVersionedRoute('post', '/chat/venues/:venueId/messages', authenticateRequest, checkUserStatus, sendVenueChatMessage);
        registerVersionedRoute('post', '/chat/threads/:threadId/read', authenticateRequest, checkUserStatus, markChatThreadRead);
        registerVersionedRoute('delete', '/chat/threads/:threadId', authenticateRequest, checkUserStatus, deleteChatThread);

        const USER_NOTIFICATION_TYPES = new Set([
            'general',
            'forum_post',
            'forum_comment',
            'favorite',
            'feedback',
            'venue_submission',
            'venue_favorite',
            'venue_review',
            'venue_reply'
        ]);

        const notificationRealtimeChannels = new Map();
        const USER_NOTIFICATION_SCHEMA_ERROR_CODES = new Set(['22P02', '23503', '42P01', '42703', '42804']);

        function normalizeNotificationType(value) {
            const normalized = String(value || '').trim().toLowerCase();
            return USER_NOTIFICATION_TYPES.has(normalized) ? normalized : 'general';
        }

        function normalizeNotificationUserId(value) {
            return String(value || '').trim();
        }

        function getNotificationRealtimeChannel(userId) {
            const normalizedUserId = normalizeNotificationUserId(userId);

            if (!normalizedUserId) {
                return null;
            }

            let channel = notificationRealtimeChannels.get(normalizedUserId);
            if (!channel) {
                channel = new EventEmitter();
                channel.setMaxListeners(0);
                notificationRealtimeChannels.set(normalizedUserId, channel);
            }

            return channel;
        }

        async function runUserNotificationsQuery(task) {
            try {
                return await task();
            } catch (error) {
                if (!USER_NOTIFICATION_SCHEMA_ERROR_CODES.has(error?.code)) {
                    throw error;
                }

                await ensureUserNotificationsSchema();
                return task();
            }
        }

        async function loadUserNotificationsPayload(userId, limit = 20) {
            const normalizedUserId = normalizeNotificationUserId(userId);
            const normalizedLimit = Math.min(Math.max(Number(limit) || 20, 1), 50);

            if (!normalizedUserId) {
                return {
                    success: true,
                    notifications: [],
                    unreadCount: 0
                };
            }

            const [notificationsResult, unreadCountResult] = await runUserNotificationsQuery(async () => Promise.all([
                pool.query(
                    `
                        SELECT id,
                               user_id AS "userId",
                               type,
                               title,
                               content,
                               metadata,
                               is_read AS "isRead",
                               created_at AS "createdAt",
                               read_at AS "readAt"
                        FROM user_notifications
                        WHERE user_id = $1
                        ORDER BY created_at DESC
                        LIMIT $2
                    `,
                    [normalizedUserId, normalizedLimit]
                ),
                pool.query(
                    `
                        SELECT COUNT(*)::int AS unread_count
                        FROM user_notifications
                        WHERE user_id = $1
                          AND is_read = false
                    `,
                    [normalizedUserId]
                )
            ]));

            return {
                success: true,
                notifications: notificationsResult.rows,
                unreadCount: Number(unreadCountResult.rows?.[0]?.unread_count || 0)
            };
        }

        async function emitUserNotificationsPayload(userId, limit = 20) {
            const normalizedUserId = normalizeNotificationUserId(userId);
            const channel = getNotificationRealtimeChannel(normalizedUserId);

            if (!normalizedUserId || !channel) {
                return null;
            }

            try {
                const payload = await loadUserNotificationsPayload(normalizedUserId, limit);
                channel.emit('change', payload);
                return payload;
            } catch (error) {
                if (error?.code === '42P01') {
                    const emptyPayload = { success: true, notifications: [], unreadCount: 0 };
                    channel.emit('change', emptyPayload);
                    return emptyPayload;
                }

                console.warn('emitUserNotificationsPayload warning:', error.message);
                return null;
            }
        }

        function scheduleUserNotificationsRefresh(userId, limit = 20) {
            const normalizedUserId = normalizeNotificationUserId(userId);
            if (!normalizedUserId) {
                return;
            }

            setTimeout(() => {
                emitUserNotificationsPayload(normalizedUserId, limit).catch(() => {});
            }, 0);
        }

        async function createUserNotification({ userId, type = 'general', title, content = null, metadata = {} }) {
            const normalizedUserId = normalizeNotificationUserId(userId);
            const normalizedTitle = String(title || '').trim();

            if (!normalizedUserId || !normalizedTitle) {
                return null;
            }

            try {
                const insertResult = await runUserNotificationsQuery(() => pool.query(
                    `
                        INSERT INTO user_notifications (user_id, type, title, content, metadata)
                        VALUES ($1, $2, $3, $4, $5::jsonb)
                        RETURNING id, user_id, type, title, content, metadata, is_read, created_at, read_at
                    `,
                    [
                        normalizedUserId,
                        normalizeNotificationType(type),
                        normalizedTitle,
                        content ? String(content).trim() : null,
                        JSON.stringify(metadata && typeof metadata === 'object' ? metadata : {})
                    ]
                ));

                const createdNotification = insertResult.rows[0] || null;
                scheduleUserNotificationsRefresh(normalizedUserId);
                return createdNotification;
            } catch (error) {
                console.warn('createUserNotification warning:', error.message);
                return null;
            }
        }

        async function listUserNotificationsHandler(req, res) {
            const userId = req.user.id;
            const limit = Math.min(
                Math.max(Number.parseInt(String(req.query?.limit || '20'), 10) || 20, 1),
                50
            );

            try {
                return res.json(await loadUserNotificationsPayload(userId, limit));
            } catch (error) {
                if (error?.code === '42P01') {
                    return res.json({ success: true, notifications: [], unreadCount: 0 });
                }
                console.error('listUserNotificationsHandler error:', error);
                return res.status(500).json({ message: 'Không thể tải thông báo lúc này.' });
            }
        }

        async function streamUserNotificationsHandler(req, res) {
            const userId = normalizeNotificationUserId(req.user?.id);

            if (!userId) {
                return res.status(401).json({ message: 'Thiếu thông tin người dùng.' });
            }

            res.setHeader('Content-Type', 'text/event-stream; charset=utf-8');
            res.setHeader('Cache-Control', 'no-cache, no-transform');
            res.setHeader('Connection', 'keep-alive');
            res.flushHeaders?.();

            const channel = getNotificationRealtimeChannel(userId);
            const writeEvent = (payload) => {
                res.write(`event: notifications\n`);
                res.write(`data: ${JSON.stringify(payload)}\n\n`);
            };

            try {
                writeEvent(await loadUserNotificationsPayload(userId, Number(req.query?.limit || 20)));
            } catch (error) {
                if (error?.code === '42P01') {
                    writeEvent({ success: true, notifications: [], unreadCount: 0 });
                } else {
                    console.error('streamUserNotificationsHandler init error:', error);
                    writeEvent({ success: false, notifications: [], unreadCount: 0 });
                }
            }

            const keepAliveId = setInterval(() => {
                res.write(`: ping\n\n`);
            }, 25000);

            const handleChange = (payload) => {
                writeEvent(payload);
            };

            channel?.on('change', handleChange);

            req.on('close', () => {
                clearInterval(keepAliveId);
                channel?.off('change', handleChange);
            });
        }

        async function markUserNotificationsReadHandler(req, res) {
            const userId = req.user.id;
            const rawIds = Array.isArray(req.body?.ids) ? req.body.ids : [];
            const notificationIds = rawIds
                .map((value) => Number(value))
                .filter((value) => Number.isFinite(value) && value > 0);

            try {
                let updatedCount = 0;

                if (notificationIds.length) {
                    const updateResult = await runUserNotificationsQuery(() => pool.query(
                        `
                            UPDATE user_notifications
                            SET is_read = true,
                                read_at = COALESCE(read_at, NOW())
                            WHERE user_id = $1
                              AND id = ANY($2::bigint[])
                              AND is_read = false
                        `,
                        [userId, notificationIds]
                    ));
                    updatedCount = Number(updateResult.rowCount || 0);
                } else {
                    const updateAllResult = await runUserNotificationsQuery(() => pool.query(
                        `
                            UPDATE user_notifications
                            SET is_read = true,
                                read_at = COALESCE(read_at, NOW())
                            WHERE user_id = $1
                              AND is_read = false
                        `,
                        [userId]
                    ));
                    updatedCount = Number(updateAllResult.rowCount || 0);
                }

                if (updatedCount > 0) {
                    scheduleUserNotificationsRefresh(userId);
                }

                return res.json({ success: true, updatedCount });
            } catch (error) {
                console.error('markUserNotificationsReadHandler error:', error);
                return res.status(500).json({ message: 'Không thể cập nhật thông báo lúc này.' });
            }
        }

        const FORUM_PROFANITY_PATTERNS = [
            'dit me', 'ditme', 'dit bo', 'ditba', 'dit', 'dm ', 'vcl', 'vl', 'cc', 'cmm', 'dmm',
            'địt', 'đụ', 'đéo', 'deo', 'lon', 'cac', 'cặc', 'lồn', 'ngu', 'oc cho', 'occho',
            'do ngu', 'mat day', 'hon lao', 'vo hoc', 'cho chet', 'chó chết'
        ];
        const FORUM_BANNED_KEYWORD_CACHE_TTL_MS = 30000;
        const forumBannedKeywordCache = {
            loadedAt: 0,
            patterns: []
        };

        function normalizeForumText(value) {
            return String(value || '')
                .normalize('NFD')
                .replace(/[\u0300-\u036f]/g, '')
                .toLowerCase()
                .replace(/[^a-z0-9\s]/g, ' ')
                .replace(/\s+/g, ' ')
                .trim();
        }

        async function getForumBannedKeywordPatterns() {
            const now = Date.now();
            if (
                Array.isArray(forumBannedKeywordCache.patterns)
                && now - Number(forumBannedKeywordCache.loadedAt || 0) < FORUM_BANNED_KEYWORD_CACHE_TTL_MS
            ) {
                return forumBannedKeywordCache.patterns;
            }

            const result = await pool.query(
                'SELECT normalized_keyword FROM forum_banned_keywords ORDER BY created_at DESC'
            );

            forumBannedKeywordCache.patterns = result.rows
                .map((row) => String(row.normalized_keyword || '').trim())
                .filter(Boolean);
            forumBannedKeywordCache.loadedAt = now;

            return forumBannedKeywordCache.patterns;
        }

        function resetForumBannedKeywordCache() {
            forumBannedKeywordCache.loadedAt = 0;
            forumBannedKeywordCache.patterns = [];
        }

        async function forumContainsProfanity(text) {
            const normalized = normalizeForumText(text);
            if (!normalized) {
                return false;
            }

            if (FORUM_PROFANITY_PATTERNS.some((pattern) => normalized.includes(pattern))) {
                return true;
            }

            const dynamicPatterns = await getForumBannedKeywordPatterns();
            return dynamicPatterns.some((pattern) => normalized.includes(pattern));
        }

        async function listAdminForumBannedKeywords(_req, res) {
            try {
                const result = await pool.query(
                    `
                        SELECT id, keyword, normalized_keyword, created_at
                        FROM forum_banned_keywords
                        ORDER BY created_at DESC
                    `
                );

                return res.json({ data: result.rows });
            } catch (error) {
                console.error('listAdminForumBannedKeywords error:', error);
                return res.status(500).json({ message: 'Không thể tải danh sách từ khóa cấm.' });
            }
        }

        async function createAdminForumBannedKeyword(req, res) {
            try {
                const keyword = String(req.body?.keyword || '').trim();
                const normalizedKeyword = normalizeForumText(keyword);

                if (!normalizedKeyword || normalizedKeyword.length < 2) {
                    return res.status(400).json({ message: 'Từ khóa cấm cần ít nhất 2 ký tự.' });
                }

                const result = await pool.query(
                    `
                        INSERT INTO forum_banned_keywords (keyword, normalized_keyword)
                        VALUES ($1, $2)
                        ON CONFLICT (normalized_keyword)
                        DO UPDATE SET keyword = EXCLUDED.keyword, updated_at = NOW()
                        RETURNING id, keyword, normalized_keyword, created_at
                    `,
                    [keyword, normalizedKeyword]
                );

                resetForumBannedKeywordCache();
                return res.status(201).json({ data: result.rows[0] });
            } catch (error) {
                console.error('createAdminForumBannedKeyword error:', error);
                return res.status(500).json({ message: 'Không thể thêm từ khóa cấm lúc này.' });
            }
        }

        async function deleteAdminForumBannedKeyword(req, res) {
            try {
                const keywordId = Number(req.params?.keywordId);

                if (!Number.isFinite(keywordId) || keywordId <= 0) {
                    return res.status(400).json({ message: 'Từ khóa cấm không hợp lệ.' });
                }

                const deleteResult = await pool.query(
                    'DELETE FROM forum_banned_keywords WHERE id = $1',
                    [keywordId]
                );

                if (!deleteResult.rowCount) {
                    return res.status(404).json({ message: 'Không tìm thấy từ khóa cấm.' });
                }

                resetForumBannedKeywordCache();
                return res.json({ data: { keywordId } });
            } catch (error) {
                console.error('deleteAdminForumBannedKeyword error:', error);
                return res.status(500).json({ message: 'Không thể gỡ từ khóa cấm lúc này.' });
            }
        }

        function sanitizeForumImageList(input, maxImages = 3) {
            if (!Array.isArray(input)) {
                return [];
            }

            const images = input
                .map((item) => String(item || '').trim())
                .filter(Boolean)
                .filter((item) => /^data:image\//i.test(item) || /^https?:\/\//i.test(item));

            const uniqueImages = [...new Set(images)];
            return uniqueImages.slice(0, maxImages);
        }

        function normalizeActorKey(value) {
            return String(value || '')
                .trim()
                .replace(/[^a-zA-Z0-9_-]/g, '')
                .slice(0, 80);
        }

        function isGenericForumAuthorName(value) {
            const normalized = normalizeForumText(value);
            return normalized === 'nguoi dung' || normalized === 'user';
        }

        async function resolveForumAuthorName(req, requestedAuthorName) {
            const trimmedRequestedName = String(requestedAuthorName || '').trim();
            if (trimmedRequestedName && !isGenericForumAuthorName(trimmedRequestedName)) {
                return trimmedRequestedName;
            }

            const authUserId = String(req.authUser?.id || '').trim();
            if (authUserId) {
                try {
                    const userResult = await pool.query(
                        'SELECT fullname, username, email FROM users WHERE id = $1 LIMIT 1',
                        [authUserId]
                    );

                    if (userResult.rows.length) {
                        const userRow = userResult.rows[0];
                        const candidates = [
                            String(userRow.fullname || '').trim(),
                            String(userRow.username || '').trim(),
                            String(userRow.email || '').trim()
                        ];

                        for (const candidate of candidates) {
                            if (!candidate) {
                                continue;
                            }

                            const derived = candidate.includes('@')
                                ? String(candidate).split('@')[0].trim()
                                : candidate;

                            if (derived && !isGenericForumAuthorName(derived)) {
                                return derived;
                            }
                        }
                    }
                } catch (error) {
                    console.warn('resolveForumAuthorName lookup error:', error.message);
                }
            }

            const authEmail = String(req.authUser?.email || '').trim();
            if (authEmail) {
                const emailName = authEmail.split('@')[0].trim();
                if (emailName && !isGenericForumAuthorName(emailName)) {
                    return emailName;
                }
            }

            return 'Người dùng';
        }

        function mapForumComment(row) {
            const isAnonymous = Boolean(row.is_anonymous);
            const alias = String(row.anonymous_alias || '').trim();
            const author = isAnonymous
                ? alias || 'Người dùng ẩn danh'
                : String(row.author_name || '').trim() || 'Người dùng';
            const rawParentId = row.parent_comment_id;
            const parentCommentId = rawParentId === null || rawParentId === undefined
                ? null
                : Number(rawParentId) || null;
            const creatorUserId = row.creator_user_id ? String(row.creator_user_id) : null;
            const authorActorKey = row.author_actor_key ? String(row.author_actor_key) : null;
            const reportCount = Number(row.report_count || row.comment_report_count || 0);
            const lastReportedAt = row.last_reported_at || null;
            const reportReasons = Array.isArray(row.comment_report_reasons)
                ? row.comment_report_reasons
                : (Array.isArray(row.report_reasons) ? row.report_reasons : []);

            return {
                id: row.id,
                postId: row.post_id,
                parentCommentId,
                content: row.content,
                author,
                isAnonymous,
                anonymousAlias: alias || null,
                images: Array.isArray(row.comment_images) ? row.comment_images : [],
                creatorUserId,
                authorActorKey,
                reportCount,
                isReported: reportCount > 0,
                lastReportedAt,
                reportReasons,
                createdAt: row.created_at,
                time: row.created_at
            };
        }

        function mapForumPost(row) {
            const isAnonymous = Boolean(row.is_anonymous);
            const alias = String(row.anonymous_alias || '').trim();
            const author = isAnonymous
                ? alias || 'Người dùng ẩn danh'
                : String(row.author_name || '').trim() || 'Người dùng';
            const creatorUserId = row.creator_user_id ? String(row.creator_user_id) : null;
            const authorActorKey = row.author_actor_key ? String(row.author_actor_key) : null;
            const reportCount = Number(row.post_report_count || row.report_count || 0);
            const commentReportCount = Number(row.comment_report_count || 0);
            const hasReportedContent = Boolean(reportCount > 0 || commentReportCount > 0);
            const postReportReasons = Array.isArray(row.post_report_reasons) ? row.post_report_reasons : [];

            return {
                id: row.id,
                title: row.title,
                category: row.category,
                content: row.content,
                excerpt: row.content,
                author,
                comments: Number(row.comments_count || 0),
                likesCount: Number(row.likes_count || 0),
                images: Array.isArray(row.post_images) ? row.post_images : [],
                createdAt: row.created_at,
                time: row.created_at,
                isAnonymous,
                anonymousAlias: alias || null,
                creatorUserId,
                authorActorKey,
                reportCount,
                commentReportCount,
                hasReportedContent,
                lastReportedAt: row.last_reported_at || null,
                postReportReasons,
                commentsList: Array.isArray(row.comments_list) ? row.comments_list.map(mapForumComment) : []
            };
        }

        async function listAdminForumPosts(req, res) {
            try {
                const search = String(req.query?.search || '').trim();
                const queryParams = [];
                let whereClause = '';

                if (search) {
                    queryParams.push(`%${search}%`);
                    whereClause = `
                        WHERE (
                            p.title ILIKE $${queryParams.length}
                            OR p.content ILIKE $${queryParams.length}
                            OR p.category ILIKE $${queryParams.length}
                            OR COALESCE(p.author_name, '') ILIKE $${queryParams.length}
                            OR EXISTS (
                                SELECT 1
                                FROM forum_comments fc_search
                                WHERE fc_search.post_id = p.id
                                  AND (
                                      fc_search.content ILIKE $${queryParams.length}
                                      OR COALESCE(fc_search.author_name, '') ILIKE $${queryParams.length}
                                      OR COALESCE(fc_search.anonymous_alias, '') ILIKE $${queryParams.length}
                                  )
                            )
                        )
                    `;
                }

                const result = await pool.query(
                    `
                        SELECT
                            p.id,
                            p.title,
                            p.category,
                            p.content,
                            p.author_name,
                            p.creator_user_id,
                            p.author_actor_key,
                            p.is_anonymous,
                            p.anonymous_alias,
                            p.comments_count,
                            p.likes_count,
                            p.post_images,
                            p.created_at,
                            COALESCE(post_reports.report_count, 0) AS post_report_count,
                            COALESCE(comment_reports.report_count, 0) AS comment_report_count,
                            COALESCE(
                                (
                                    SELECT json_agg(report_item ORDER BY report_item.created_at DESC)
                                    FROM (
                                        SELECT
                                            fpr.id,
                                            fpr.actor_key,
                                            fpr.reason,
                                            fpr.created_at
                                        FROM forum_post_reports fpr
                                        WHERE fpr.post_id = p.id
                                        ORDER BY fpr.created_at DESC
                                        LIMIT 20
                                    ) report_item
                                ),
                                '[]'::json
                            ) AS post_report_reasons,
                            GREATEST(
                                COALESCE(post_reports.last_reported_at, 'epoch'::timestamptz),
                                COALESCE(comment_reports.last_reported_at, 'epoch'::timestamptz)
                            ) AS last_reported_at,
                            COALESCE(
                                (
                                    SELECT json_agg(c ORDER BY c.is_reported DESC, c.last_reported_at DESC NULLS LAST, c.created_at DESC)
                                    FROM (
                                        SELECT
                                            fc.id,
                                            fc.post_id,
                                            fc.parent_comment_id,
                                            fc.content,
                                            fc.author_name,
                                            fc.creator_user_id,
                                            fc.author_actor_key,
                                            fc.is_anonymous,
                                            fc.anonymous_alias,
                                            fc.comment_images,
                                            fc.created_at,
                                            COALESCE(fcr.report_count, 0) AS report_count,
                                            COALESCE(
                                                (
                                                    SELECT json_agg(comment_report_item ORDER BY comment_report_item.created_at DESC)
                                                    FROM (
                                                        SELECT
                                                            report.id,
                                                            report.actor_key,
                                                            report.reason,
                                                            report.created_at
                                                        FROM forum_comment_reports report
                                                        WHERE report.comment_id = fc.id
                                                        ORDER BY report.created_at DESC
                                                        LIMIT 20
                                                    ) comment_report_item
                                                ),
                                                '[]'::json
                                            ) AS comment_report_reasons,
                                            fcr.last_reported_at,
                                            (COALESCE(fcr.report_count, 0) > 0) AS is_reported
                                        FROM forum_comments fc
                                        LEFT JOIN (
                                            SELECT
                                                comment_id,
                                                COUNT(*)::int AS report_count,
                                                MAX(created_at) AS last_reported_at
                                            FROM forum_comment_reports
                                            GROUP BY comment_id
                                        ) fcr ON fcr.comment_id = fc.id
                                        WHERE fc.post_id = p.id
                                        ORDER BY fc.created_at DESC
                                        LIMIT 200
                                    ) c
                                ),
                                '[]'::json
                            ) AS comments_list
                        FROM forum_posts p
                        LEFT JOIN (
                            SELECT
                                post_id,
                                COUNT(*)::int AS report_count,
                                MAX(created_at) AS last_reported_at
                            FROM forum_post_reports
                            GROUP BY post_id
                        ) post_reports ON post_reports.post_id = p.id
                        LEFT JOIN (
                            SELECT
                                fc.post_id,
                                COUNT(*)::int AS report_count,
                                MAX(fcr.created_at) AS last_reported_at
                            FROM forum_comment_reports fcr
                            INNER JOIN forum_comments fc ON fc.id = fcr.comment_id
                            GROUP BY fc.post_id
                        ) comment_reports ON comment_reports.post_id = p.id
                        ${whereClause}
                        ORDER BY
                            (COALESCE(post_reports.report_count, 0) > 0 OR COALESCE(comment_reports.report_count, 0) > 0) DESC,
                            GREATEST(
                                COALESCE(post_reports.last_reported_at, 'epoch'::timestamptz),
                                COALESCE(comment_reports.last_reported_at, 'epoch'::timestamptz)
                            ) DESC,
                            p.created_at DESC
                        LIMIT 200
                    `,
                    queryParams
                );

                return res.json({ data: result.rows.map(mapForumPost) });
            } catch (error) {
                console.error('listAdminForumPosts error:', error);
                return res.status(500).json({ message: 'Không thể tải dữ liệu diễn đàn cho quản trị viên.' });
            }
        }

        async function listForumPosts(req, res) {
            try {
                const result = await pool.query(
                    `
                        SELECT
                            p.id,
                            p.title,
                            p.category,
                            p.content,
                            p.author_name,
                            p.creator_user_id,
                            p.author_actor_key,
                            p.is_anonymous,
                            p.anonymous_alias,
                            p.comments_count,
                            p.likes_count,
                            p.post_images,
                            p.created_at,
                            COALESCE(
                                (
                                    SELECT json_agg(c ORDER BY c.created_at DESC)
                                    FROM (
                                        SELECT
                                            fc.id,
                                            fc.post_id,
                                            fc.parent_comment_id,
                                            fc.content,
                                            fc.author_name,
                                            fc.creator_user_id,
                                            fc.author_actor_key,
                                            fc.is_anonymous,
                                            fc.anonymous_alias,
                                            fc.comment_images,
                                            fc.created_at
                                        FROM forum_comments fc
                                        WHERE fc.post_id = p.id
                                        ORDER BY fc.created_at DESC
                                        LIMIT 100
                                    ) c
                                ),
                                '[]'::json
                            ) AS comments_list
                        FROM forum_posts p
                        ORDER BY p.created_at DESC
                        LIMIT 100
                    `
                );

                return res.json({ data: result.rows.map(mapForumPost) });
            } catch (error) {
                console.error('listForumPosts error:', error);
                return res.status(500).json({ message: 'Không thể tải bài viết diễn đàn.' });
            }
        }

        async function createForumPost(req, res) {
            try {
                const title = String(req.body?.title || '').trim();
                const category = String(req.body?.category || '').trim();
                const content = String(req.body?.content || '').trim();
                const isAnonymous = Boolean(req.body?.isAnonymous);
                const anonymousAlias = String(req.body?.anonymousAlias || '').trim();
                const authorName = await resolveForumAuthorName(req, req.body?.authorName);
                const actorKey = normalizeActorKey(req.body?.actorKey);
                const creatorUserId = req.authUser?.id || null;
                const postImages = sanitizeForumImageList(req.body?.images, 3);

                if (!title || !category || !content) {
                    return res.status(400).json({ message: 'Vui lòng nhập đầy đủ tiêu đề, chủ đề và nội dung.' });
                }

                if (content.length > 499) {
                    return res.status(400).json({ message: 'Nội dung dài tối đa 499 ký tự.' });
                }

                if (isAnonymous && anonymousAlias.length < 2) {
                    return res.status(400).json({ message: 'Vui lòng nhập biệt danh tối thiểu 2 ký tự khi đăng ẩn danh.' });
                }

                if (await forumContainsProfanity(`${title} ${category} ${content} ${anonymousAlias}`)) {
                    return res.status(400).json({ message: 'Nội dung chứa từ ngữ không phù hợp. Vui lòng chỉnh sửa trước khi đăng.' });
                }

                const insertResult = await pool.query(
                    `
                        INSERT INTO forum_posts (
                            title, category, content, author_name, creator_user_id, author_actor_key, is_anonymous, anonymous_alias, post_images
                        )
                        VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9::jsonb)
                        RETURNING id, title, category, content, author_name, creator_user_id, author_actor_key, is_anonymous, anonymous_alias, comments_count, likes_count, post_images, created_at
                    `,
                    [
                        title,
                        category,
                        content,
                        isAnonymous ? null : authorName,
                        creatorUserId,
                        actorKey || null,
                        isAnonymous,
                        isAnonymous ? anonymousAlias : null,
                        JSON.stringify(postImages)
                    ]
                );

                if (creatorUserId) {
                    await createUserNotification({
                        userId: creatorUserId,
                        type: 'forum_post',
                        title: 'Đăng bài diễn đàn thành công',
                        content: title,
                        metadata: {
                            postId: Number(insertResult.rows?.[0]?.id || 0) || null,
                            category
                        }
                    });
                }

                return res.status(201).json({ data: mapForumPost(insertResult.rows[0]) });
            } catch (error) {
                console.error('createForumPost error:', error);
                return res.status(500).json({ message: 'Không thể đăng bài lúc này. Vui lòng thử lại.' });
            }
        }

        async function createForumComment(req, res) {
            try {
                const postId = Number(req.params?.postId);
                const authUserId = String(req.authUser?.id || '').trim();
                const rawParentCommentId = req.body?.parentCommentId;
                const parentCommentId =
                    rawParentCommentId === null || rawParentCommentId === undefined || rawParentCommentId === ''
                        ? null
                        : Number(rawParentCommentId);
                const content = String(req.body?.content || '').trim();
                const isAnonymous = Boolean(req.body?.isAnonymous);
                const anonymousAlias = String(req.body?.anonymousAlias || '').trim();
                const authorName = await resolveForumAuthorName(req, req.body?.authorName);
                const actorKey = normalizeActorKey(req.body?.actorKey);
                const creatorUserId = authUserId || null;
                const commentImages = sanitizeForumImageList(req.body?.images, 3);

                if (!authUserId) {
                    return res.status(401).json({ message: 'Bạn cần đăng nhập để bình luận.' });
                }

                if (!Number.isFinite(postId) || postId <= 0) {
                    return res.status(400).json({ message: 'Bài viết không hợp lệ.' });
                }

                if (!content) {
                    return res.status(400).json({ message: 'Vui lòng nhập nội dung bình luận.' });
                }

                if (parentCommentId !== null && (!Number.isFinite(parentCommentId) || parentCommentId <= 0)) {
                    return res.status(400).json({ message: 'Phản hồi bình luận không hợp lệ.' });
                }

                if (content.length > 499) {
                    return res.status(400).json({ message: 'Nội dung bình luận tối đa 499 ký tự.' });
                }

                if (isAnonymous && anonymousAlias.length < 2) {
                    return res.status(400).json({ message: 'Vui lòng nhập biệt danh tối thiểu 2 ký tự khi bình luận ẩn danh.' });
                }

                if (await forumContainsProfanity(`${content} ${anonymousAlias}`)) {
                    return res.status(400).json({ message: 'Bình luận chứa từ ngữ không phù hợp. Vui lòng chỉnh sửa trước khi đăng.' });
                }

                const postCheck = await pool.query(
                    'SELECT id, title, creator_user_id FROM forum_posts WHERE id = $1 LIMIT 1',
                    [postId]
                );
                if (!postCheck.rows.length) {
                    return res.status(404).json({ message: 'Không tìm thấy bài viết.' });
                }

                if (parentCommentId !== null) {
                    const parentCheck = await pool.query(
                        'SELECT id FROM forum_comments WHERE id = $1 AND post_id = $2 LIMIT 1',
                        [parentCommentId, postId]
                    );

                    if (!parentCheck.rows.length) {
                        return res.status(404).json({ message: 'Không tìm thấy bình luận gốc để phản hồi.' });
                    }
                }

                const insertResult = await pool.query(
                    `
                        INSERT INTO forum_comments (
                            post_id, parent_comment_id, content, author_name, creator_user_id, author_actor_key, is_anonymous, anonymous_alias, comment_images
                        )
                        VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9::jsonb)
                        RETURNING id, post_id, parent_comment_id, content, author_name, creator_user_id, author_actor_key, is_anonymous, anonymous_alias, comment_images, created_at
                    `,
                    [
                        postId,
                        parentCommentId,
                        content,
                        isAnonymous ? null : authorName,
                        creatorUserId,
                        actorKey || null,
                        isAnonymous,
                        isAnonymous ? anonymousAlias : null,
                        JSON.stringify(commentImages)
                    ]
                );

                await pool.query(
                    'UPDATE forum_posts SET comments_count = comments_count + 1, updated_at = NOW() WHERE id = $1',
                    [postId]
                );

                if (creatorUserId) {
                    await createUserNotification({
                        userId: creatorUserId,
                        type: 'forum_comment',
                        title: 'Bình luận diễn đàn đã được đăng',
                        content: content.slice(0, 140),
                        metadata: {
                            postId,
                            commentId: Number(insertResult.rows?.[0]?.id || 0) || null,
                            parentCommentId
                        }
                    });
                }

                const postCreatorUserId = String(postCheck.rows[0]?.creator_user_id || '').trim();
                if (postCreatorUserId && postCreatorUserId !== creatorUserId) {
                    await createUserNotification({
                        userId: postCreatorUserId,
                        type: 'forum_comment',
                        title: 'Bài viết diễn đàn của bạn có bình luận mới',
                        content: content.slice(0, 140),
                        metadata: {
                            postId,
                            commentId: Number(insertResult.rows?.[0]?.id || 0) || null,
                            parentCommentId
                        }
                    });
                }

                return res.status(201).json({ data: mapForumComment(insertResult.rows[0]) });
            } catch (error) {
                console.error('createForumComment error:', error);
                return res.status(500).json({ message: 'Không thể đăng bình luận lúc này. Vui lòng thử lại.' });
            }
        }

        async function toggleForumPostLike(req, res) {
            try {
                const postId = Number(req.params?.postId);
                const actorKey = normalizeActorKey(req.body?.actorKey);

                if (!Number.isFinite(postId) || postId <= 0) {
                    return res.status(400).json({ message: 'Bài viết không hợp lệ.' });
                }

                if (!actorKey) {
                    return res.status(400).json({ message: 'Thiếu thông tin người dùng để thực hiện thao tác thích.' });
                }

                const postCheck = await pool.query(
                    'SELECT id, title, creator_user_id, author_actor_key FROM forum_posts WHERE id = $1 LIMIT 1',
                    [postId]
                );
                if (!postCheck.rows.length) {
                    return res.status(404).json({ message: 'Không tìm thấy bài viết.' });
                }

                const existing = await pool.query(
                    'SELECT id FROM forum_post_likes WHERE post_id = $1 AND actor_key = $2 LIMIT 1',
                    [postId, actorKey]
                );

                let liked = false;
                if (existing.rows.length) {
                    await pool.query('DELETE FROM forum_post_likes WHERE post_id = $1 AND actor_key = $2', [postId, actorKey]);
                    await pool.query(
                        'UPDATE forum_posts SET likes_count = GREATEST(likes_count - 1, 0), updated_at = NOW() WHERE id = $1',
                        [postId]
                    );
                } else {
                    await pool.query(
                        'INSERT INTO forum_post_likes (post_id, actor_key) VALUES ($1, $2) ON CONFLICT (post_id, actor_key) DO NOTHING',
                        [postId, actorKey]
                    );
                    await pool.query(
                        'UPDATE forum_posts SET likes_count = likes_count + 1, updated_at = NOW() WHERE id = $1',
                        [postId]
                    );
                    liked = true;
                }

                const likesResult = await pool.query('SELECT likes_count FROM forum_posts WHERE id = $1', [postId]);
                const likesCount = Number(likesResult.rows?.[0]?.likes_count || 0);

                const postCreatorUserId = String(postCheck.rows[0]?.creator_user_id || '').trim();
                const postActorKey = String(postCheck.rows[0]?.author_actor_key || '').trim();
                if (liked && postCreatorUserId && postActorKey !== actorKey) {
                    await createUserNotification({
                        userId: postCreatorUserId,
                        type: 'forum_post',
                        title: 'Bài viết diễn đàn của bạn có lượt thích mới',
                        content: String(postCheck.rows[0]?.title || '').trim() || `Bài viết #${postId}`,
                        metadata: {
                            postId,
                            actorKey
                        }
                    });
                }

                return res.json({ data: { postId, liked, likesCount } });
            } catch (error) {
                console.error('toggleForumPostLike error:', error);
                return res.status(500).json({ message: 'Không thể cập nhật lượt thích lúc này. Vui lòng thử lại.' });
            }
        }

        async function reportForumPost(req, res) {
            try {
                const postId = Number(req.params?.postId);
                const actorKey = normalizeActorKey(req.body?.actorKey);
                const reason = String(req.body?.reason || '').trim();

                if (!Number.isFinite(postId) || postId <= 0) {
                    return res.status(400).json({ message: 'Bài viết không hợp lệ.' });
                }

                if (!actorKey) {
                    return res.status(400).json({ message: 'Thiếu thông tin người dùng để báo cáo.' });
                }

                if (reason.length < 3) {
                    return res.status(400).json({ message: 'Lý do báo cáo cần ít nhất 3 ký tự.' });
                }

                if (await forumContainsProfanity(reason)) {
                    return res.status(400).json({ message: 'Lý do báo cáo chứa từ ngữ không phù hợp.' });
                }

                const postCheck = await pool.query('SELECT id FROM forum_posts WHERE id = $1 LIMIT 1', [postId]);
                if (!postCheck.rows.length) {
                    return res.status(404).json({ message: 'Không tìm thấy bài viết.' });
                }

                await pool.query(
                    `
                        INSERT INTO forum_post_reports (post_id, actor_key, reason)
                        VALUES ($1, $2, $3)
                    `,
                    [postId, actorKey, reason]
                );

                return res.status(201).json({ data: { postId, actorKey } });
            } catch (error) {
                console.error('reportForumPost error:', error);
                return res.status(500).json({ message: 'Không thể gửi báo cáo lúc này. Vui lòng thử lại.' });
            }
        }

