        const getUserPreferenceHandler = async (req, res) => {
            const userId = String(req.user?.id || '').trim();

            if (!userId) {
                return res.status(401).json({ message: 'Unauthorized' });
            }

            try {
                const preference = await getUserPreferenceRecordByUserId(userId);

                return res.json({
                    success: true,
                    preference,
                    preferencesCompleted: Boolean(preference?.onboardingCompleted),
                    options: buildUserPreferenceOptionsPayload()
                });
            } catch (error) {
                if (isUndefinedTableError(error)) {
                    return res.status(500).json({
                        message: 'User preference schema is missing. Please run backend migrations.'
                    });
                }

                return res.status(500).json({ message: error.message });
            }
        };

        const saveUserPreferenceHandler = async (req, res) => {
            const userId = String(req.user?.id || '').trim();
            const ageRangeKey = String(req.body?.ageRangeKey || '').trim();
            const preferredGender = String(req.body?.preferredGender || '').trim();
            const preferredTimes = normalizePreferenceStringList(req.body?.preferredTimes);
            const interests = normalizePreferenceStringList(req.body?.interests);
            const latitudeInput = req.body?.latitude;
            const longitudeInput = req.body?.longitude;

            if (!userId) {
                return res.status(401).json({ message: 'Unauthorized' });
            }

            if (!USER_PREFERENCE_AGE_RANGE_SET.has(ageRangeKey)) {
                return res.status(400).json({ message: 'Invalid age range.' });
            }

            if (!USER_PREFERENCE_GENDER_SET.has(preferredGender)) {
                return res.status(400).json({ message: 'Invalid preferred gender.' });
            }

            if (!preferredTimes.length || preferredTimes.some((item) => !USER_PREFERENCE_TIME_WINDOW_SET.has(item))) {
                return res.status(400).json({ message: 'Please select at least one valid preferred time.' });
            }

            const allowedInterestSet = USER_PREFERENCE_INTEREST_SET_BY_AGE[ageRangeKey] || new Set();
            if (!interests.length || interests.some((item) => !allowedInterestSet.has(item))) {
                return res.status(400).json({ message: 'Selected interests are not valid for the chosen age range.' });
            }

            let latitude = null;
            let longitude = null;
            const hasLatitudeInput = latitudeInput !== undefined && latitudeInput !== null && latitudeInput !== '';
            const hasLongitudeInput = longitudeInput !== undefined && longitudeInput !== null && longitudeInput !== '';

            if (hasLatitudeInput || hasLongitudeInput) {
                latitude = Number(latitudeInput);
                longitude = Number(longitudeInput);

                if (!Number.isFinite(latitude) || latitude < -90 || latitude > 90) {
                    return res.status(400).json({ message: 'Invalid latitude value.' });
                }

                if (!Number.isFinite(longitude) || longitude < -180 || longitude > 180) {
                    return res.status(400).json({ message: 'Invalid longitude value.' });
                }
            }

            try {
                const result = await pool.query(
                    `
                        INSERT INTO user_ai_preferences (
                            user_id,
                            age_range_key,
                            preferred_gender,
                            preferred_times,
                            interests,
                            onboarding_completed,
                            last_known_latitude,
                            last_known_longitude,
                            updated_at
                        )
                        VALUES ($1, $2, $3, $4::text[], $5::text[], true, $6, $7, NOW())
                        ON CONFLICT (user_id)
                        DO UPDATE SET
                            age_range_key = EXCLUDED.age_range_key,
                            preferred_gender = EXCLUDED.preferred_gender,
                            preferred_times = EXCLUDED.preferred_times,
                            interests = EXCLUDED.interests,
                            onboarding_completed = true,
                            last_known_latitude = COALESCE(EXCLUDED.last_known_latitude, user_ai_preferences.last_known_latitude),
                            last_known_longitude = COALESCE(EXCLUDED.last_known_longitude, user_ai_preferences.last_known_longitude),
                            updated_at = NOW()
                        RETURNING
                            user_id,
                            age_range_key,
                            preferred_gender,
                            preferred_times,
                            interests,
                            onboarding_completed,
                            last_known_latitude,
                            last_known_longitude,
                            created_at,
                            updated_at
                    `,
                    [userId, ageRangeKey, preferredGender, preferredTimes, interests, latitude, longitude]
                );

                await createUserNotification({
                    userId,
                    type: 'general',
                    title: 'Bạn đã cập nhật sở thích thành công',
                    content: 'Hệ thống sẽ dùng sở thích mới để gợi ý địa điểm phù hợp hơn.',
                    metadata: {
                        section: 'preferences',
                        action: 'updated',
                        ageRangeKey,
                        preferredGender,
                        preferredTimes,
                        interests
                    }
                });

                return res.json({
                    success: true,
                    message: 'Preferences saved successfully.',
                    preference: mapUserPreferenceRow(result.rows[0] || null)
                });
            } catch (error) {
                if (isUndefinedTableError(error)) {
                    return res.status(500).json({
                        message: 'User preference schema is missing. Please run backend migrations.'
                    });
                }

                return res.status(500).json({ message: error.message });
            }
        };

        const listUserRecommendationsHandler = async (req, res) => {
            const userId = String(req.user?.id || '').trim();
            const limit = normalizePaginationValue(req.query?.limit, 12, { min: 4, max: 24 });
            const latitudeQuery = req.query?.latitude;
            const longitudeQuery = req.query?.longitude;
            const preferOpenNow = normalizeBooleanQueryValue(req.query?.preferOpenNow, false);
            const weatherMain = String(req.query?.weatherMain || '').trim();
            const currentTimeIsoInput = String(req.query?.currentTimeIso || '').trim();

            if (!userId) {
                return res.status(401).json({ message: 'Unauthorized' });
            }

            let currentTime = new Date();
            if (currentTimeIsoInput) {
                const parsedCurrentTime = new Date(currentTimeIsoInput);
                if (Number.isNaN(parsedCurrentTime.getTime())) {
                    return res.status(400).json({ message: 'Invalid currentTimeIso value.' });
                }

                currentTime = parsedCurrentTime;
            }

            const currentTimeWindowKey = resolveCurrentPreferenceTimeWindowKey(currentTime);

            const hasLatitudeQuery = latitudeQuery !== undefined && latitudeQuery !== null && latitudeQuery !== '';
            const hasLongitudeQuery = longitudeQuery !== undefined && longitudeQuery !== null && longitudeQuery !== '';

            if (hasLatitudeQuery !== hasLongitudeQuery) {
                return res.status(400).json({ message: 'latitude and longitude must be provided together.' });
            }

            let requestLatitude = null;
            let requestLongitude = null;

            if (hasLatitudeQuery && hasLongitudeQuery) {
                requestLatitude = Number(latitudeQuery);
                requestLongitude = Number(longitudeQuery);

                if (!Number.isFinite(requestLatitude) || requestLatitude < -90 || requestLatitude > 90) {
                    return res.status(400).json({ message: 'Invalid latitude value.' });
                }

                if (!Number.isFinite(requestLongitude) || requestLongitude < -180 || requestLongitude > 180) {
                    return res.status(400).json({ message: 'Invalid longitude value.' });
                }
            }

            try {
                const preference = await getUserPreferenceRecordByUserId(userId);

                if (!preference || !preference.onboardingCompleted) {
                    return res.json({
                        success: true,
                        preferencesCompleted: false,
                        recommendations: []
                    });
                }

                const effectiveLatitude = Number.isFinite(requestLatitude)
                    ? requestLatitude
                    : preference.lastKnownLatitude;
                const effectiveLongitude = Number.isFinite(requestLongitude)
                    ? requestLongitude
                    : preference.lastKnownLongitude;

                if (Number.isFinite(requestLatitude) && Number.isFinite(requestLongitude)) {
                    await pool.query(
                        `
                            UPDATE user_ai_preferences
                            SET
                                last_known_latitude = $2,
                                last_known_longitude = $3,
                                updated_at = NOW()
                            WHERE user_id = $1
                        `,
                        [userId, requestLatitude, requestLongitude]
                    );
                }

                const venueResult = await pool.query(
                    `
                        SELECT
                            venues.id,
                            venues.name,
                            venues.title,
                            venues.address,
                            venues.description,
                            venues.latitude,
                            venues.longitude,
                            venues.ward_id,
                            wards.name AS ward_name,
                            venues.category_id,
                            place_categories.name AS category_name,
                            venues.cover_image_url,
                            venues.metadata,
                            venues.average_rating,
                            venues.total_reviews,
                            venues.status::text AS status,
                            venues.created_at,
                            venues.updated_at
                        FROM venues
                        LEFT JOIN wards ON wards.ward_id = venues.ward_id
                        LEFT JOIN place_categories ON place_categories.id = venues.category_id
                        WHERE venues.status::text = 'approved'
                        ORDER BY COALESCE(venues.approved_at, venues.created_at) DESC, venues.id DESC
                        LIMIT 300
                    `
                );

                const scoredVenues = venueResult.rows
                    .map((row) => normalizeVenueCoordinates(row))
                    .map((venue) => {
                        const scoring = scoreVenueByUserPreference(
                            venue,
                            preference,
                            effectiveLatitude,
                            effectiveLongitude,
                            {
                                currentTime,
                                currentTimeWindowKey,
                                weatherMain,
                                preferOpenNow
                            }
                        );

                        return {
                            ...venue,
                            recommendationScore: Number(scoring.score.toFixed(4)),
                            distanceKm: scoring.distanceKm,
                            isOpenNow: scoring.isOpenNow,
                            openingTimeRange: scoring.openingTimeRange,
                            hasRealtimeSchedule: scoring.hasRealtimeSchedule,
                            recommendationReasons: scoring.reasons
                        };
                    })
                    .filter((venue) => !(preferOpenNow && venue.hasRealtimeSchedule && venue.isOpenNow === false))
                    .filter((venue) => venue.recommendationScore > 0.15)
                    .sort((first, second) => {
                        if (second.recommendationScore !== first.recommendationScore) {
                            return second.recommendationScore - first.recommendationScore;
                        }

                        const secondRating = Number(second.average_rating || 0);
                        const firstRating = Number(first.average_rating || 0);
                        return secondRating - firstRating;
                    });

                const diversifiedVenuesRaw = diversifyRecommendedVenues(scoredVenues, limit);
                const promotionAssignmentMap = await resolveCurrentVenuePromotionMapByVenueIds(
                    diversifiedVenuesRaw.map((v) => v.id)
                );
                const featuredPromotionMap = await resolveFeaturedVenuePromotionMapByVenueIds(
                    diversifiedVenuesRaw.map((v) => v.id)
                );

                const diversifiedVenues = diversifiedVenuesRaw.map((venue) => {
                    const decoratedVenue = attachFeaturedVenuePromotion(venue, featuredPromotionMap, promotionAssignmentMap);
                    return {
                        id: decoratedVenue.id,
                        name: decoratedVenue.name,
                        title: decoratedVenue.title,
                        address: decoratedVenue.address,
                        description: decoratedVenue.description,
                        latitude: decoratedVenue.latitude,
                        longitude: decoratedVenue.longitude,
                        ward_id: decoratedVenue.ward_id,
                        ward_name: decoratedVenue.ward_name,
                        category_id: decoratedVenue.category_id,
                        category_name: decoratedVenue.category_name,
                        cover_image_url: decoratedVenue.cover_image_url,
                        metadata: decoratedVenue.metadata,
                        average_rating: decoratedVenue.average_rating,
                        total_reviews: decoratedVenue.total_reviews,
                        recommendationScore: decoratedVenue.recommendationScore,
                        distanceKm: decoratedVenue.distanceKm,
                        isOpenNow: decoratedVenue.isOpenNow,
                        openingTimeRange: decoratedVenue.openingTimeRange,
                        recommendationReasons: decoratedVenue.recommendationReasons,
                        featuredPromotion: decoratedVenue.featuredPromotion,
                        promotionAssignment: decoratedVenue.promotionAssignment
                    };
                });

                return res.json({
                    success: true,
                    preferencesCompleted: true,
                    preference,
                    context: {
                        evaluatedAt: currentTime.toISOString(),
                        currentTimeWindowKey,
                        currentTimeWindowLabel: resolveTimeWindowLabel(currentTimeWindowKey),
                        weatherMain: weatherMain || null,
                        preferOpenNow
                    },
                    recommendations: diversifiedVenues
                });
            } catch (error) {
                if (isUndefinedTableError(error)) {
                    return res.status(500).json({
                        message: 'User preference schema is missing. Please run backend migrations.'
                    });
                }

                return res.status(500).json({ message: error.message });
            }
        };

        const refineUserRecommendationsHandler = async (req, res) => {
            const userId = String(req.user?.id || '').trim();
            const refineQuery = String(req.body?.query || '').trim();
            const limit = normalizePaginationValue(req.body?.limit, 24, { min: 4, max: 40 });
            const latitudeInput = req.body?.latitude;
            const longitudeInput = req.body?.longitude;
            const weatherMain = String(req.body?.weatherMain || '').trim();
            const currentTimeIsoInput = String(req.body?.currentTimeIso || '').trim();
            const baseVenueIdsFilter = parsePositiveIntegerList(req.body?.baseVenueIds);
            const requestedRefineScope = String(req.body?.scope || '').trim().toLowerCase();

            if (!userId) {
                return res.status(401).json({ message: 'Unauthorized' });
            }

            if (!refineQuery || refineQuery.length < 2) {
                return res.status(400).json({ message: 'Please provide a refine query with at least 2 characters.' });
            }

            if (baseVenueIdsFilter.invalid) {
                return res.status(400).json({ message: 'baseVenueIds must contain positive integers only.' });
            }

            const hasLatitudeInput = latitudeInput !== undefined && latitudeInput !== null && latitudeInput !== '';
            const hasLongitudeInput = longitudeInput !== undefined && longitudeInput !== null && longitudeInput !== '';

            if (hasLatitudeInput !== hasLongitudeInput) {
                return res.status(400).json({ message: 'latitude and longitude must be provided together.' });
            }

            let requestLatitude = null;
            let requestLongitude = null;

            if (hasLatitudeInput && hasLongitudeInput) {
                requestLatitude = Number(latitudeInput);
                requestLongitude = Number(longitudeInput);

                if (!Number.isFinite(requestLatitude) || requestLatitude < -90 || requestLatitude > 90) {
                    return res.status(400).json({ message: 'Invalid latitude value.' });
                }

                if (!Number.isFinite(requestLongitude) || requestLongitude < -180 || requestLongitude > 180) {
                    return res.status(400).json({ message: 'Invalid longitude value.' });
                }
            }

            let currentTime = new Date();
            if (currentTimeIsoInput) {
                const parsedCurrentTime = new Date(currentTimeIsoInput);
                if (Number.isNaN(parsedCurrentTime.getTime())) {
                    return res.status(400).json({ message: 'Invalid currentTimeIso value.' });
                }

                currentTime = parsedCurrentTime;
            }

            const currentTimeWindowKey = resolveCurrentPreferenceTimeWindowKey(currentTime);

            try {
                const preference = await getUserPreferenceRecordByUserId(userId);

                if (!preference || !preference.onboardingCompleted) {
                    return res.json({
                        success: true,
                        preferencesCompleted: false,
                        recommendations: []
                    });
                }

                const effectiveLatitude = Number.isFinite(requestLatitude)
                    ? requestLatitude
                    : preference.lastKnownLatitude;
                const effectiveLongitude = Number.isFinite(requestLongitude)
                    ? requestLongitude
                    : preference.lastKnownLongitude;

                if (Number.isFinite(requestLatitude) && Number.isFinite(requestLongitude)) {
                    await pool.query(
                        `
                            UPDATE user_ai_preferences
                            SET
                                last_known_latitude = $2,
                                last_known_longitude = $3,
                                updated_at = NOW()
                            WHERE user_id = $1
                        `,
                        [userId, requestLatitude, requestLongitude]
                    );
                }

                const parsedRefine = await parseRecommendationRefineConstraints(refineQuery);
                const refineConstraints = parsedRefine.constraints || buildHeuristicRefineConstraints(refineQuery);

                const venueSelectSql = `
                    SELECT
                        venues.id,
                        venues.name,
                        venues.title,
                        venues.address,
                        venues.description,
                        venues.latitude,
                        venues.longitude,
                        venues.ward_id,
                        wards.name AS ward_name,
                        venues.category_id,
                        place_categories.name AS category_name,
                        venues.cover_image_url,
                        venues.metadata,
                        venues.average_rating,
                        venues.total_reviews,
                        venues.status::text AS status,
                        venues.created_at,
                        venues.updated_at
                    FROM venues
                    LEFT JOIN wards ON wards.ward_id = venues.ward_id
                    LEFT JOIN place_categories ON place_categories.id = venues.category_id
                    WHERE venues.status::text = 'approved'
                `;

                let venueResult;
                const useBaseScope = baseVenueIdsFilter.values.length > 0
                    && ['base', 'base_scope', 'narrow', 'seed'].includes(requestedRefineScope);
                let refineScope = useBaseScope ? 'base_scope' : 'global_scope';
                const prioritizeDistanceSort = Number.isFinite(refineConstraints.maxDistanceKm);
                const prioritizeBudgetSort = Number.isFinite(refineConstraints.maxBudgetVnd)
                    || Number.isFinite(refineConstraints.minBudgetVnd);
                const sortBudgetDescending = Boolean(
                    refineConstraints.strictBudgetFloor
                    && Number.isFinite(refineConstraints.minBudgetVnd)
                    && !Number.isFinite(refineConstraints.maxBudgetVnd)
                );

                if (useBaseScope) {
                    venueResult = await pool.query(
                        `${venueSelectSql}
                         AND venues.id = ANY($1::bigint[])
                         ORDER BY COALESCE(venues.approved_at, venues.created_at) DESC, venues.id DESC
                        `,
                        [baseVenueIdsFilter.values]
                    );
                } else {
                    venueResult = await pool.query(
                        `${venueSelectSql}
                         ORDER BY COALESCE(venues.approved_at, venues.created_at) DESC, venues.id DESC
                         LIMIT 1200
                        `
                    );
                }

                const sortScoredRefineVenues = (first, second) => {
                    if (prioritizeDistanceSort) {
                        const firstDistance = Number(first.distanceKm);
                        const secondDistance = Number(second.distanceKm);
                        const firstDistanceComparable = Number.isFinite(firstDistance) && firstDistance >= 0
                            ? firstDistance
                            : Number.POSITIVE_INFINITY;
                        const secondDistanceComparable = Number.isFinite(secondDistance) && secondDistance >= 0
                            ? secondDistance
                            : Number.POSITIVE_INFINITY;

                        if (firstDistanceComparable !== secondDistanceComparable) {
                            return firstDistanceComparable - secondDistanceComparable;
                        }
                    }

                    if (prioritizeBudgetSort) {
                        const firstBudget = resolveVenueBudgetRange(first);
                        const secondBudget = resolveVenueBudgetRange(second);

                        const resolveComparableBudget = (budgetRange) => {
                            const minPrice = Number(budgetRange?.minPrice);
                            const maxPrice = Number(budgetRange?.maxPrice);

                            if (Number.isFinite(minPrice) && minPrice > 0) {
                                return minPrice;
                            }

                            if (Number.isFinite(maxPrice) && maxPrice > 0) {
                                return maxPrice;
                            }

                            return Number.POSITIVE_INFINITY;
                        };

                        const firstBudgetComparable = resolveComparableBudget(firstBudget);
                        const secondBudgetComparable = resolveComparableBudget(secondBudget);

                        if (firstBudgetComparable !== secondBudgetComparable) {
                            return sortBudgetDescending
                                ? secondBudgetComparable - firstBudgetComparable
                                : firstBudgetComparable - secondBudgetComparable;
                        }
                    }

                    if (second.finalScore !== first.finalScore) {
                        return second.finalScore - first.finalScore;
                    }

                    const secondRating = Number(second.average_rating || 0);
                    const firstRating = Number(first.average_rating || 0);
                    return secondRating - firstRating;
                };

                const computeScoredRefineVenuesFromRows = (venueRows) => {
                    return venueRows
                        .map((row) => normalizeVenueCoordinates(row))
                        .map((venue) => {
                            const scoring = scoreVenueByUserPreference(
                                venue,
                                preference,
                                effectiveLatitude,
                                effectiveLongitude,
                                {
                                    currentTime,
                                    currentTimeWindowKey,
                                    weatherMain,
                                    preferOpenNow: refineConstraints.requireOpenNow
                                }
                            );
                            const refineEvaluation = evaluateVenueAgainstRefineConstraints(
                                venue,
                                refineConstraints,
                                {
                                    userLatitude: effectiveLatitude,
                                    userLongitude: effectiveLongitude,
                                    currentTime,
                                    weatherMain
                                }
                            );

                            const finalScore = Number((scoring.score + refineEvaluation.refineScore * 1.65).toFixed(4));
                            const mergedReasons = [...new Set([
                                ...(Array.isArray(scoring.reasons) ? scoring.reasons : []),
                                ...(Array.isArray(refineEvaluation.reasons) ? refineEvaluation.reasons : [])
                            ])].slice(0, 5);

                            return {
                                ...venue,
                                recommendationScore: Number(scoring.score.toFixed(4)),
                                refineScore: Number(refineEvaluation.refineScore.toFixed(4)),
                                finalScore,
                                distanceKm: scoring.distanceKm,
                                isOpenNow: refineEvaluation.isOpenNow,
                                openingTimeRange: refineEvaluation.openingTimeRange,
                                hasRealtimeSchedule: scoring.hasRealtimeSchedule,
                                passesRefine: refineEvaluation.passes,
                                hardFailures: refineEvaluation.hardFailures,
                                matchedRefineDimensions: refineEvaluation.matchedDimensions,
                                failedRefineDimensions: refineEvaluation.failedDimensions,
                                recommendationReasons: mergedReasons
                            };
                        })
                        .filter((venue) => {
                            if (hasStructuredRefineSignals(refineConstraints)) {
                                return true;
                            }

                            return venue.recommendationScore > 0.05;
                        });
                };

                let scoredVenueCandidates = computeScoredRefineVenuesFromRows(venueResult.rows);
                let refinedVenues = scoredVenueCandidates
                    .filter((venue) => venue.passesRefine)
                    .sort(sortScoredRefineVenues);

                // If base-scope refinement yields no result, expand to broader candidate pool.
                if (!refinedVenues.length && useBaseScope) {
                    const expandedVenueResult = await pool.query(
                        `${venueSelectSql}
                         ORDER BY COALESCE(venues.approved_at, venues.created_at) DESC, venues.id DESC
                         LIMIT 1200
                        `
                    );

                    scoredVenueCandidates = computeScoredRefineVenuesFromRows(expandedVenueResult.rows);
                    refinedVenues = scoredVenueCandidates
                        .filter((venue) => venue.passesRefine)
                        .sort(sortScoredRefineVenues);

                    if (refinedVenues.length) {
                        refineScope = 'expanded_scope';
                    }
                }

                const heuristicRefinedVenues = [...refinedVenues];

                const semanticRefine = await runSemanticVenueRefine({
                    queryText: refineQuery,
                    candidateVenues: [...scoredVenueCandidates].sort(sortScoredRefineVenues).slice(0, 260),
                    currentTime
                });

                const semanticMatchMap = new Map(
                    (Array.isArray(semanticRefine.matches) ? semanticRefine.matches : [])
                        .map((item) => {
                            const venueId = Number(item?.venueId);
                            if (!Number.isFinite(venueId) || venueId <= 0) {
                                return null;
                            }

                            return [venueId, item];
                        })
                        .filter(Boolean)
                );

                const requiredRefineDimensionsFromConstraints = resolveRequiredRefineDimensions(refineConstraints);
                const requiredRefineDimensions = Array.isArray(semanticRefine.requiredDimensions) && semanticRefine.requiredDimensions.length
                    ? semanticRefine.requiredDimensions
                    : requiredRefineDimensionsFromConstraints;
                const requiresConcurrentDimensionMatch = requiredRefineDimensions.length >= 2;
                const semanticScoreThreshold = requiresConcurrentDimensionMatch ? 0.62 : 0.48;
                const requireHeuristicPassForSemantic = Boolean(
                    Number.isFinite(refineConstraints.maxDistanceKm)
                    || refineConstraints.requireKeywordMatch
                    || refineConstraints.requireFoodVenue
                    || refineConstraints.requireNameMatch
                    || refineConstraints.requireLocationMatch
                    || refineConstraints.requireActivityMatch
                    || refineConstraints.requireServiceMatch
                    || (Array.isArray(refineConstraints.cuisineKeywords) && refineConstraints.cuisineKeywords.length > 0)
                );

                if (!semanticRefine.understood) {
                    refinedVenues = [...heuristicRefinedVenues];
                } else if (semanticMatchMap.size > 0) {
                    refinedVenues = scoredVenueCandidates
                        .filter((venue) => {
                            const semanticMatch = semanticMatchMap.get(Number(venue.id));
                            if (!semanticMatch) {
                                return false;
                            }

                            const semanticScore = Number(semanticMatch.score || 0);
                            if (semanticScore < semanticScoreThreshold) {
                                return false;
                            }

                            if (requireHeuristicPassForSemantic && !venue.passesRefine) {
                                return false;
                            }

                            const matchedDimensions = new Set([
                                ...(Array.isArray(venue.matchedRefineDimensions) ? venue.matchedRefineDimensions : []),
                                ...(Array.isArray(semanticMatch.matchedDimensions) ? semanticMatch.matchedDimensions : [])
                            ]);
                            const failedDimensions = new Set(
                                Array.isArray(venue.failedRefineDimensions) ? venue.failedRefineDimensions : []
                            );

                            if (requiresConcurrentDimensionMatch) {
                                const allRequiredMatched = requiredRefineDimensions.every(
                                    (dimension) => matchedDimensions.has(dimension) && !failedDimensions.has(dimension)
                                );

                                if (!allRequiredMatched) {
                                    return false;
                                }
                            }

                            if (requiredRefineDimensionsFromConstraints.length >= 2 && !venue.passesRefine) {
                                return false;
                            }

                            return true;
                        })
                        .map((venue) => {
                            const semanticMatch = semanticMatchMap.get(Number(venue.id));
                            const semanticScore = Number(semanticMatch?.score || 0);
                            const semanticReason = String(semanticMatch?.reason || '').trim();
                            const semanticDimensions = Array.isArray(semanticMatch?.matchedDimensions)
                                ? semanticMatch.matchedDimensions
                                : [];

                            return {
                                ...venue,
                                finalScore: Number((venue.finalScore + semanticScore * 3.45).toFixed(4)),
                                recommendationReasons: [...new Set([
                                    ...(Array.isArray(venue.recommendationReasons) ? venue.recommendationReasons : []),
                                    semanticDimensions.length
                                        ? `Semantic dimensions: ${semanticDimensions.join(', ')}`
                                        : '',
                                    semanticReason ? `Semantic match: ${semanticReason}` : ''
                                ].filter(Boolean))].slice(0, 5)
                            };
                        })
                        .sort(sortScoredRefineVenues);
                } else {
                    refinedVenues = [...heuristicRefinedVenues];
                }

                const fallbackConstraintSummary = buildRefineConstraintsSummary(refineConstraints);
                const hasConstraintSignals = hasStructuredRefineSignals(refineConstraints);
                const refineSummary = hasConstraintSignals
                    ? fallbackConstraintSummary
                    : (semanticRefine.understood
                        ? 'Semantic intent understood. Applied sentence-level matching without hard numeric constraints.'
                        : (heuristicRefinedVenues.length
                            ? 'Semantic parser uncertain. Returned broader heuristic refine results from approved venues.'
                            : 'Unable to confidently understand this refine sentence. Please rewrite with clearer details.'));

                const slicedRefinedVenues = refinedVenues.slice(0, limit);
                const promotionAssignmentMap = await resolveCurrentVenuePromotionMapByVenueIds(
                    slicedRefinedVenues.map((v) => v.id)
                );
                const featuredPromotionMap = await resolveFeaturedVenuePromotionMapByVenueIds(
                    slicedRefinedVenues.map((v) => v.id)
                );

                const recommendations = slicedRefinedVenues.map((venue) => {
                    const decoratedVenue = attachFeaturedVenuePromotion(venue, featuredPromotionMap, promotionAssignmentMap);
                    return {
                        id: decoratedVenue.id,
                        name: decoratedVenue.name,
                        title: decoratedVenue.title,
                        address: decoratedVenue.address,
                        description: decoratedVenue.description,
                        latitude: decoratedVenue.latitude,
                        longitude: decoratedVenue.longitude,
                        ward_id: decoratedVenue.ward_id,
                        ward_name: decoratedVenue.ward_name,
                        category_id: decoratedVenue.category_id,
                        category_name: decoratedVenue.category_name,
                        cover_image_url: decoratedVenue.cover_image_url,
                        metadata: decoratedVenue.metadata,
                        average_rating: decoratedVenue.average_rating,
                        total_reviews: decoratedVenue.total_reviews,
                        recommendationScore: decoratedVenue.recommendationScore,
                        refineScore: decoratedVenue.refineScore,
                        finalScore: decoratedVenue.finalScore,
                        distanceKm: decoratedVenue.distanceKm,
                        isOpenNow: decoratedVenue.isOpenNow,
                        openingTimeRange: decoratedVenue.openingTimeRange,
                        recommendationReasons: decoratedVenue.recommendationReasons,
                        featuredPromotion: decoratedVenue.featuredPromotion,
                        promotionAssignment: decoratedVenue.promotionAssignment
                    };
                });

                return res.json({
                    success: true,
                    preferencesCompleted: true,
                    preference,
                    context: {
                        evaluatedAt: currentTime.toISOString(),
                        currentTimeWindowKey,
                        currentTimeWindowLabel: resolveTimeWindowLabel(currentTimeWindowKey),
                        weatherMain: weatherMain || null,
                        preferOpenNow: refineConstraints.requireOpenNow
                    },
                    refine: {
                        query: refineQuery,
                        parsedBy: `${parsedRefine.agent?.mode || 'heuristic'}+semantic_sentence`,
                        model: parsedRefine.agent?.model || null,
                        passes: Number(parsedRefine.agent?.passes || 0),
                        fallbackModelUsed: Boolean(parsedRefine.agent?.fallbackModelUsed),
                        semanticModel: semanticRefine.model || null,
                        semanticFallbackModelUsed: Boolean(semanticRefine.fallbackModelUsed),
                        understood: Boolean(semanticRefine.understood),
                        confidence: Number(semanticRefine.confidence || 0),
                        requiredDimensions: requiredRefineDimensions,
                        requestedScope: requestedRefineScope || 'global',
                        scope: refineScope,
                        summary: refineSummary,
                        constraints: refineConstraints
                    },
                    recommendations
                });
            } catch (error) {
                if (isUndefinedTableError(error)) {
                    return res.status(500).json({
                        message: 'User preference schema is missing. Please run backend migrations.'
                    });
                }

                return res.status(500).json({ message: error.message });
            }
        };

