        const toggleUserFavoriteHandler = async (req, res) => {
            const userId = req.user.id;
            const { itemId, itemType, name, image, price, description } = req.body;

            try {
                const normalizedItemId = String(itemId ?? req.body?.id ?? '').trim();
                const normalizedItemType = String(itemType || req.body?.type || 'place').trim().toLowerCase();

                if (!normalizedItemId || !normalizedItemType) {
                    return res.status(400).json({ message: 'Missing item information.' });
                }

                const existing = await pool.query(
                    'SELECT id FROM user_favorites WHERE user_id = $1 AND item_id = $2 AND item_type = $3',
                    [userId, normalizedItemId, normalizedItemType]
                );

                if (existing.rows.length > 0) {
                    await pool.query(
                        'DELETE FROM user_favorites WHERE user_id = $1 AND item_id = $2 AND item_type = $3',
                        [userId, normalizedItemId, normalizedItemType]
                    );
                    await createUserNotification({
                        userId,
                        type: 'favorite',
                        title: 'Đã bỏ khỏi yêu thích',
                        content: String(name || normalizedItemId),
                        metadata: {
                            itemId: normalizedItemId,
                            itemType: normalizedItemType,
                            action: 'removed'
                        }
                    });
                    return res.json({ success: true, favorited: false });
                }

                await pool.query(
                    `INSERT INTO user_favorites (user_id, item_id, item_type, name, image, price, description)
             VALUES ($1, $2, $3, $4, $5, $6, $7)`,
                    [
                        userId,
                        normalizedItemId,
                        normalizedItemType,
                        name || null,
                        image || null,
                        price || null,
                        description || null
                    ]
                );

                await createUserNotification({
                    userId,
                    type: 'favorite',
                    title: 'Đã thêm vào yêu thích',
                    content: String(name || normalizedItemId),
                    metadata: {
                        itemId: normalizedItemId,
                        itemType: normalizedItemType,
                        action: 'added'
                    }
                });

                if (normalizedItemType === 'place') {
                    const venueOwnerUserId = await resolveVenueOwnerUserIdByVenueId(normalizedItemId);
                    const actorName = await resolveNotificationActorName(userId);

                    if (venueOwnerUserId && venueOwnerUserId !== String(userId || '').trim()) {
                        await createUserNotification({
                            userId: venueOwnerUserId,
                            type: 'venue_favorite',
                            title: 'Bài đăng của bạn có lượt yêu thích mới',
                            content: `${actorName} đã yêu thích bài đăng của bạn.`,
                            metadata: {
                                itemId: normalizedItemId,
                                itemType: normalizedItemType,
                                action: 'added',
                                actorUserId: String(userId || '').trim()
                            }
                        });
                    }
                }

                res.json({ success: true, favorited: true });
            } catch (err) {
                console.error('Favorites toggle error:', err);
                res.status(500).json({ message: 'Server error' });
            }
        };

